var e={common:{cancel:`Abbrechen`,"count.files":{one:`{count} Datei`,other:`{count} Dateien`},"list.and":`{first} und {second}`,"list.then":`{first}, dann {second}`,"list.comma":`{first}, {second}`,"list.semicolon":`{first}; {second}`,"bank.slot":`Slot {letter}`,"bank.recovery":`Recovery-Slot {letter}`,"bank.slotInSentence":`Slot {letter}`,"bank.recoveryInSentence":`Recovery-Slot {letter}`},app:{title:`Seek Thermal Firmware Toolkit`,"header.cameraSelected":`Kamera ausgewählt`,"header.noCamera":`Keine Kamera ausgewählt`,"header.usbUnavailable":`USB nicht verfügbar`,"header.github":`Das Toolkit auf GitHub`,"header.tabs":`Tabs`,"tab.info":`Info`,"tab.preserve":`Auslesen & entschlüsseln 0.x/1.x 2014/2016`,"tab.v4":`Auslesen & entschlüsseln 4.x/Nano`,"tab.decrypt":`Datei/Slot entschlüsseln`,"tab.slots":`Firmware-Slots bearbeiten`,documentTitle:`Seek Thermal Firmware — {tab} (WebUSB)`,"theme.label":`Dunkles Design`,"theme.followsSystem":`Folgt der hellen oder dunklen Einstellung Ihres Systems`,"theme.chosenDiffers":`Hier gewählt. Schalten Sie zurück, um wieder der Einstellung Ihres Systems zu folgen.`,"theme.chosenSame":`Hier gewählt, derzeit gleich der Einstellung Ihres Systems`,"language.label":`Sprache`,"intro.info":"Liest die angeschlossene Kamera so aus wie `seek-fw info`: ihre Firmware, die Familie, als die sie sich meldet, wie sie startet, ihre Schlüssel und jeden Slot. Die Seite sagt Ihnen, welcher der anderen Tabs für die Kamera zuständig ist, und erklärt in einfachen Worten, wofür jeder Tab da ist. **In diesem Tab wird nichts in den Flash-Speicher geschrieben.**","intro.preserve":`Für Kameras mit **0.x und 1.x** (die Builds von 2014 und 2016). Erstellt eine **vollständige** Kopie des 4 MB großen Flash-Speichers der Kamera — auch der Teile, die ein normales Auslesen nicht erreicht — und stellt die Kamera danach genau so wieder her, wie sie war. Die Seite sichert, was sie lesen kann, patcht die Firmware kurzzeitig, damit sich der Rest lesen lässt, liest alles aus, stellt das Original wieder her und prüft es. Alles läuft lokal in Ihrem Browser. **Zwei der Schritte schreiben in den Flash-Speicher**, und jeder fragt vorher nach.`,"intro.v4":`Erstellt über WebUSB eine reine Lesekopie des 4 MB großen SPI-Flash-Speichers einer **4.x- oder Nano**-Kamera und entschlüsselt alle Firmware-Images, die darin gefunden werden. Alles läuft lokal in Ihrem Browser — nichts wird irgendwohin hochgeladen. **Nur Lesen:** Dieser Tab sendet keinen Befehl zum Schreiben, Löschen, Hochladen, Committen oder Zurücksetzen des Flash-Speichers. Eine Kamera mit einer anderen Firmware-Linie wird abgelehnt, bevor irgendetwas gelesen wird.`,"intro.decrypt":`Entschlüsselt Firmware, die Sie bereits haben, auf diesem Computer: ein vollständiges Flash-Abbild oder einen einzelnen 64-KB-Firmware-Slot. **Es wird keine Kamera verwendet**, das funktioniert also auch ohne angeschlossenes Gerät und in Browsern ohne USB-Zugriff. Die Datei wird hier gelesen und nie hochgeladen.`,"intro.slots":`Liest die drei Firmware-Slots der Kamera — Slot A, Slot B und Recovery-Slot R — und zeigt, was jeder enthält, aus welchem die Kamera startet und was dieser Build damit tun kann, daneben die laufende Firmware und die Schlüssel des Geräts. Alles läuft lokal in Ihrem Browser. **Dieser Tab schreibt in den Flash-Speicher:** Er kann einen Slot aus einem entschlüsselten Image oder aus Rohdaten beschreiben und fragt vor jedem Schreibvorgang nach.`,"support.ios.title":`**WebUSB ist unter iOS und iPadOS nicht verfügbar,** daher kann dieses Gerät den Flash-Speicher einer Kamera nicht lesen.`,"support.ios.body":`Safari unterstützt es nicht, und jeder Browser unter iOS muss WebKit verwenden, daher können auch Chrome und Firefox es hier nicht anbieten. Daran ändert keine Einstellung und keine Erweiterung etwas. Um eine Kamera auszulesen, verwenden Sie einen Desktop-Computer oder ein Android-Telefon mit USB-OTG-Kabel.`,"support.noWebUsb.title":`**Dieser Browser kann nicht auf USB-Geräte zugreifen.**`,"support.noWebUsb.body":`WebUSB ist in Chrome, Edge, Opera und anderen Chromium-Browsern unter Windows, macOS, Linux und Android verfügbar. Firefox und Safari haben beide abgelehnt, es zu unterstützen.`,"support.noWebUsb.insecure":`Diese Seite wird außerdem nicht über eine sichere Verbindung ausgeliefert, was WebUSB schon für sich allein blockiert.`,"support.insecure.title":`**Unsichere Verbindung.** WebUSB ist hier deaktiviert.`,"support.insecure.body":"Öffnen Sie diese Seite über HTTPS oder von `http://localhost`. Eine einfache LAN-Adresse wie `http://192.168.1.10:8000` genügt nicht.","support.offlineStillWorks":`Den Tab **{tab}** können Sie trotzdem verwenden — er arbeitet nur mit einer Datei, die Sie auswählen, und braucht keinen USB-Zugriff.`,"support.ready":`**Bereit.** Schließen Sie Ihre Seek-Kamera an und klicken Sie auf *{connect}*.`,"support.fileProtocol":`Als lokale Datei geöffnet, daher merkt sich der Browser das Gerät nicht über ein Neuladen hinweg. Das ist unbedenklich.`,unlockNote:`Hinweis: {note}.`,"connect.title":`Verbinden`,"connect.actions":`Geräteaktionen`,"connect.connect":`Gerät verbinden`,"connect.change":`Gerät wechseln`,"connect.test":`Verbindung testen`,"connect.forget":`Gerät vergessen`,"connect.vendorNote":"Jedes Seek-Thermal-Gerät wird angeboten (USB-Hersteller `{vendor}`) — Compact, Compact PRO, Nano und so weiter. Wählen Sie Ihres in der Geräteauswahl des Browsers aus.","platform.title":`Hinweise zu den Plattformen`,"platform.macos":`Funktioniert ohne Weiteres in Chrome, Edge oder jedem Chromium-Browser. Keine Treiberinstallation, keine Administratorrechte. Beenden Sie vorher jedes andere Programm, das bereits mit der Kamera kommuniziert — die USB-Schnittstelle kann jeweils nur ein Prozess belegen.`,"platform.linux.access":`Geben Sie Ihrem Benutzer Zugriff auf das Gerät, ziehen Sie es dann ab und stecken Sie es wieder ein:`,"platform.linux.sandbox":"Chromium aus Snap oder Flatpak ist oft per Sandbox von direktem USB-Zugriff abgeschnitten; das `.deb`- oder `.rpm`-Paket ist die zuverlässige Wahl.","platform.windows":"Unter Windows muss der WinUSB-Treiber an die Kamera gebunden sein, bevor irgendein Browser sie erreichen kann. Verwenden Sie <zadig>Zadig</zadig>: *Options → List All Devices*, wählen Sie dann in der Auswahlliste den Eintrag, der nach Ihrer Kamera benannt ist — zum Beispiel `CompactPRO FF` —, wählen Sie **WinUSB** als Treiber und klicken Sie auf Replace Driver. Erscheint Ihre Kamera mehrfach, nehmen Sie den Eintrag mit *(Interface 0)*. Damit ist das Gerät für die Herstellersoftware nicht mehr nutzbar, bis Sie die Änderung im Geräte-Manager rückgängig machen (*Gerät deinstallieren → Treiber löschen*, dann neu anstecken).","platform.android":`Funktioniert in Chrome für Android mit einem USB-OTG-Kabel, sofern das Telefon die Kamera über USB mit Strom versorgen kann. Android gewährt den USB-Zugriff über einen eigenen Berechtigungsdialog. Der Download landet wie jede andere Datei in Ihrem Download-Ordner.`,"platform.ios.name":`iPhone und iPad`,"platform.ios.cannot":`**Kann keine Kamera lesen**, und daran wird sich nichts ändern. Safari unterstützt WebUSB nicht, und unter iOS und iPadOS muss jeder Browser — auch Chrome und Firefox — mit WebKit darstellen, daher bietet keiner von ihnen diese Schnittstelle an. Es gibt keine Einstellung, keine Erweiterung und keine App, die das umgeht. Verwenden Sie zum Auslesen einen Desktop-Computer oder ein Android-Telefon.`,"platform.ios.decrypt":`Das optionale Entschlüsseln funktioniert hier: Ein vorhandenes Flash-Abbild zu entschlüsseln braucht keinen USB-Zugriff, das geht also auf einem iPhone oder iPad oder mit Firefox und Safari auf dem Desktop.`},core:{"unlock.powerCycleNote":`die Kamera bleibt entsperrt, bis sie aus- und wieder eingeschaltet wird, und andere Programme lesen sie bis dahin womöglich falsch; schalten Sie sie aus und wieder ein, bevor Sie diese verwenden`,"boot.rule":`{first} zuerst, dann {second}, dann {last}`,"boot.verdict.notRead":`wurde nicht gelesen`,"boot.verdict.checkKeyUnnamed":`konnte nicht geprüft werden: Der Schlüssel, unter dem sein Bootloader einen Slot prüft, wurde nicht benannt`,"boot.cfg0NotRead":`das Boot-Konfigurationswort (cfg[0]) wurde nicht gelesen, daher ist nicht bekannt, aus welchem Slot der nächste Start erfolgt`,"boot.select.unknown":`das Boot-Konfigurationswort ist {word}, daher probiert der Bootloader zuerst {first}, aber {bank} {verdict}, daher ist nicht bekannt, welcher Slot läuft`,"boot.select.first":`das Boot-Konfigurationswort ist {word}, daher probiert der Bootloader zuerst {first}, und dieser Slot enthält ein Image, das der Bootloader annimmt`,"boot.select.second":`das Boot-Konfigurationswort ist {word}, daher probiert der Bootloader zuerst {first}; {first} enthält kein Image, das der Bootloader annimmt, daher nimmt er {second}`,"boot.select.lastBoots":`das Boot-Konfigurationswort ist {word}, daher probiert der Bootloader zuerst {first}; weder {first} noch {second} enthält ein Image, das der Bootloader annimmt, daher startet er {last}, den er nicht prüft`,"boot.select.lastTakes":`das Boot-Konfigurationswort ist {word}, daher probiert der Bootloader zuerst {first}; weder {first} noch {second} enthält ein Image, das der Bootloader annimmt, daher nimmt er {last}, den er nicht prüft`,"boot.bootsNow":`{bank} ist der Slot, aus dem die Kamera jetzt startet`,"boot.bootedNow":`jetzt gestartet`,"boot.notBooted":`nicht gestartet`,"boot.unknownWhy.checkKeyUnnamed":`der Schlüssel, unter dem sein Bootloader einen Slot prüft, wurde bei diesem Lesen nicht benannt`,"boot.unknownWhy.noKeyTable":`die Schlüsseltabelle des Bootloaders wurde nicht gelesen, daher lassen sich die Schlüssel, die er probiert, nicht benennen`,"fpsBoot.boots":`Die Kamera startet aus {bank}. {why}.`,"fpsBoot.holdsOne":`{bank} enthält einen Bildraten-Patch, läuft aber nicht, daher wirkt der Patch nicht.`,"fpsBoot.holdsTwo":`{banks} enthalten Bildraten-Patches, aber keiner von beiden läuft, daher wirken die Patches nicht.`,"fpsBoot.wouldNotRun":`Wird {target} gepatcht, läuft er dadurch nicht, weil die Kamera stattdessen aus {bank} startet.`,"fpsBoot.patchRunning":`Patchen Sie auch {bank} (den Slot, der läuft): Erst das lässt den Bildraten-Patch wirken.`,"fpsBoot.cannotPatch":`{bank} kann hier nicht gepatcht werden ({reason}), daher wirkt ein Bildraten-Patch in einem anderen Slot auf dieser Kamera nicht.`,"backup.bank.notInPlan":`{name} (nicht im Plan dieses Builds: die ZIP-Datei vermerkt das)`,"backup.bank.unsupported":`{name} (dieser Build kann ihn nicht lesen, {reason}: die ZIP-Datei vermerkt das)`,"backup.bank.empty":`{name} (leer, jedes Byte 0xFF: die ZIP-Datei vermerkt das, und der Schreibvorgang überschreibt keine Firmware)`,"backup.bank.unread":`{name} (das Lesen der Slots hat ihn nicht erreicht: die ZIP-Datei vermerkt, ob das Lesen vor dem Schreiben ihn erreicht)`,"backup.bank.noKey":`{name} (wie gespeichert; kein Schlüssel aus diesem Lesen öffnet ihn, daher gibt es keine entschlüsselte Datei)`,"backup.bank.decrypted":`{name} (wie gespeichert und entschlüsselt)`,"backup.plan.one":`Bevor irgendetwas geschrieben wird, wird {banks} erneut gelesen und in einer ZIP-Datei gespeichert, mit einer Notiz, was jede Datei ist: {file}.`,"backup.plan.many":`Bevor irgendetwas geschrieben wird, werden {banks} erneut gelesen und in einer ZIP-Datei gespeichert, mit einer Notiz, was jede Datei ist: {file}.`,"staging.detail.keyACiphertext":`so verschlüsselt, dass das Gerät es unter dem Schlüssel speichert, den der gestartete Slot enthält`,"staging.detail.slotKeystreamCiphertext":`verschlüsselt unter dem eigenen Übertragungsschlüssel des Images (Schlüsselblock 0); die Kamera speichert es unter dem eigenen Schlüssel des Slots`,"staging.detail.plain":`Klartext, ohne Verschlüsselung`,"staging.detail.keyAKeystream":`das 1.3.0.8-FF-Image so, wie die Hersteller-App es überträgt (XOR Schlüssel A) — der 16-Hz-Build speichert es unter Schlüssel B, nicht diese Bytes`,"staging.detail.verbatim":`unverändert — die Bytes genau wie angegeben`,"copy.source.noRead":`kein Lesevorgang`,"copy.source.notInPlan":`{name} ist nicht im Plan dieses Builds`,"copy.source.notRead":`{name} wurde nicht gelesen ({reason}), daher gibt es kein Image zum Kopieren`,"copy.source.empty":`{name} ist leer: Es gibt kein Image zum Kopieren`,"copy.source.foreign":`{name} enthält kein Firmware-Image, das dieses Lesen erkennt, daher gibt es nichts zu kopieren`,"copy.source.noKey":`kein Schlüssel aus diesem Lesen öffnet {name}, daher gibt es kein entschlüsseltes Image zum Kopieren`,"copy.from":`{name} bei {address}, wie das Lesen der Slots es entschlüsselt hat`,"copy.fromVersion":`{name} bei {address}, Firmware {version}, wie das Lesen der Slots es entschlüsselt hat`,"copy.note":`Das Image stammt aus {name}, wie das Lesen der Slots es entschlüsselt hat: {size} B, sha256 {sha256}.`,"copy.noteVersion":`Das Image stammt aus {name}, wie das Lesen der Slots es entschlüsselt hat: Firmware {version}, {size} B, sha256 {sha256}.`,"restore.where":`{name} der Sicherung (bei {address})`,"restore.from":`{where} in der vollständigen Flash-Sicherung {file}`,"restore.fromVersion":`{where} in der vollständigen Flash-Sicherung {file}, Firmware {version}`,"restore.kind.flash-file":`ein 4-MB-Flash-Abbild`,"restore.kind.preserve-run":`eine Preserve-Durchlaufdatei`,"restore.kind.dump":`eine ZIP-Datei von „Auslesen & entschlüsseln 4.x/Nano“`,"restore.kind.all-selectors":`eine ZIP-Datei von „Alle Selektoren auslesen“`,"restore.decryptedTo.image":`ein Image`,"restore.decryptedTo.firmware":`Firmware {version}`,"restore.note.image":`Das Image ist {where} in {file}, {kind}: gespeichert mit sha256 {stored}, entschlüsselt ergibt es {decrypted} mit {size} B (sha256 {sha256}).`,"restore.note.imageEntry":`Das Image ist {where} in {file}, {kind} (darin {entry}): gespeichert mit sha256 {stored}, entschlüsselt ergibt es {decrypted} mit {size} B (sha256 {sha256}).`,"restore.note.readBack":`Nach dem Schreiben wird der zurückgelesene Slot mit den gespeicherten Slot-Bytes der Sicherung verglichen.`,"restore.note.sameCamera":`Der Identitätsblock der Sicherung nennt diese Kamera (Seriennummer {serial}).`,"restore.note.sameBytes":`{name} enthält bereits die gespeicherten Bytes der Sicherung: Der Schreibvorgang schreibt dasselbe Image zurück.`,"restore.warn.otherCamera":`Diese Sicherung sieht nach einer anderen Kamera aus: Ihr Identitätsblock nennt die Seriennummer {theirs}, und diese Kamera ist {camera}. Geschrieben wird nur das Image von {name}; nichts von der Identität oder Kalibrierung jener Kamera.`,"restore.warn.noIdentity":`Diese Sicherung hat keinen Identitätsblock bei {address}, daher lässt sich nicht sagen, von welcher Kamera sie gelesen wurde.`,"restore.warn.serialNotRead":`Die Seriennummer der Kamera wurde nicht gelesen, daher kann die Sicherung (Seriennummer {serial}) ihr nicht zugeordnet werden.`,"restore.warn.otherFirmware":`{where} enthält Firmware {version}, und die Kamera führt {camera} aus: Die Wiederherstellung bringt eine andere Firmware in den Slot.`,"restore.readBack.notCompared":`{bank} wurde nicht zurückgelesen und daher nicht mit der Sicherung verglichen.`,"restore.readBack.equal":`{bank} liest sich Byte für Byte so zurück, wie die Sicherung ihn speichert.`,"restore.readBack.differs":`{bank} liest sich in {count} B anders zurück als die gespeicherten Bytes der Sicherung (erste Abweichung bei {offset}).`,"keys.derived.same":`{key}, abgeleitet vom gestarteten {bank}`,"keys.derived.holds":`{key} (der Speicherschlüssel), abgeleitet vom gestarteten {bank}, der {holds} enthält`,"keys.derived.sameUnnamed":`{key}, abgeleitet vom gestarteten Slot`,"keys.derived.holdsUnnamed":`{key} (der Speicherschlüssel), abgeleitet vom gestarteten Slot, der {holds} enthält`,"keys.ffVendor.staged":`das 1.3.0.8-FF-Image (16 Hz) so, wie die Hersteller-App es überträgt: das Image XOR seinen eigenen Schlüsselblock 0 (Schlüssel A), Header-Fenster unverändert, in jeden Slot; die Schlüssel dieser Kamera werden nicht verwendet`,"keys.ffVendor.stored":`Schlüssel B: Die Kamera verschlüsselt den Upload mit Schlüsselblock 1 neu und speichert das Image darunter`,"keys.imageBlock0.staged":`das Image unter seinem eigenen Schlüsselblock 0 (im Image anhand des Werts gefunden), in jeden Slot; die Schlüssel dieser Kamera werden nicht verwendet`,"keys.imageBlock0.storedUnnamed":`der Schlüssel, unter dem ihr Bootloader einen Slot prüft (bei diesem Lesen nicht benannt); die Kamera verschlüsselt den Upload darunter neu`,"keys.imageBlock0.stored":`{key}, der Schlüssel, unter dem ihr Bootloader einen Slot prüft; die Kamera verschlüsselt den Upload darunter neu`,"notes.ffBootUntested":`UNTESTED (ungetestet): Von einer Kamera wurde noch kein Bootloader des 16-Hz-FF-Builds gelesen, daher ist nicht bekannt, ob der beschriebene Slot startet. Auf dem Bootloader 0.9.0.0 ist eine frühere Form dieses Images aus Recovery-Slot R gestartet; diese Form wird das nicht, weil dieser Bootloader Recovery-Slot R so startet, wie er gespeichert ist, ohne ihn zu dekodieren.`,"write.ff.otherVersion":`Das 16-Hz-FF-Image wird in der Form gesendet, die nur der 16-Hz-Build {version} liest. Diese Kamera beschreibt einen Slot, ohne das Image zu prüfen (ihr Firmware-Quelltext sagt das, und eine Compact mit 1.3.0.0 tat das beim Versuch), daher wird erwartet, dass sie die Bytes so schreibt, wie sie gesendet werden: Der Slot enthält das Image dann in einer Form, aus der diese Kamera nicht starten kann.`,"write.ff.untested":`{untested} Nichts hier behauptet, dass die Kamera es startet.`,"write.ff.runsFast":`Die eigenen Antworten der Kamera sagen, dass sie den 16-Hz-FF-Build ausführt: {why}.`,"write.ff.outcome.takes":`prüft Nutzdaten, bevor er einen Slot löscht, und diese Nutzdaten bestehen die Prüfung. Er schreibt diese Bytes also womöglich so, wie sie sind, in einer Form, aus der sein Bootloader nicht starten kann: Der Slot startet dann womöglich nicht (nicht ausprobiert; die vor dem Schreiben gespeicherte Sicherung stellt ihn wieder her)`,"write.ff.outcome.refuses":`prüft Nutzdaten, bevor er einen Slot löscht, und diese Nutzdaten bestehen die Prüfung nicht. Es wird also erwartet, dass er diesen Schreibvorgang ablehnt, bevor er irgendetwas schreibt (eine Kamera mit diesem Build hat eine frühere Form dieses Images auf dieselbe Weise abgelehnt)`,"write.ff.runsSlow":`Die Kamera führt den 8-Hz-Build {version} aus: {why}. Dieser Build {outcome}.`,"write.ff.buildUnknown":`Die eigenen Antworten der Kamera sagen nicht, welchen Build {version} sie ausführt: {why}. Führt sie den 16-Hz-FF-Build aus, nimmt sie diese Nutzdaten an. Führt sie den 8-Hz-Build aus, gilt: Dieser Build {outcome}.`,"write.raw.asGiven":`Rohe Nutzdaten: genau wie angegeben gesendet. Nichts hier prüft, ob sie startfähig sind.`,"write.raw.ffStagedForm":`Diese Nutzdaten sind die übertragene Form von 1.3.0.8 FF (das Image XOR Schlüsselblock 0, Wortsumme 0xFFFF). Die Kamera speichert das Image unter Schlüssel B, daher wird das Rücklesen gegen diese Bytes geprüft.`,"write.raw.noStaging":`Dieser Build nennt keine Übertragungsform für den Slot, daher lassen sich die Prüfungen des Bootloaders nicht angeben.`,"write.raw.reencrypts":`Das Gerät dekodiert diese Nutzdaten und verschlüsselt neu, was es behält, daher sind die gespeicherten Bytes nicht vorhergesagt. Das Rücklesen wird, wo das möglich ist, als das Image geprüft, zu dem es sich entschlüsseln lässt.`,"write.raw.bootloaderRejects":`Der Bootloader würde diese Nutzdaten ablehnen: {failure}.`,"write.raw.stageKeyUnchecked":`Der Übertragungsschlüssel von 2016 (Schlüsselblock 0) ist in Rohdaten nicht enthalten, daher wird die entschlüsselte Wortsumme dieser Nutzdaten hier nicht geprüft.`,"write.image.rekeyRisk":`{name} enthält bereits ein Image, das der Bootloader nicht annehmen kann. Dieser Schreibvorgang führt zum selben Zustand.`,"write.ack.recovery":`Recovery-Slot R: Das Schreiben verlangt, dass Sie das Risiko bestätigen. Nichts hier prüft, ob die Kamera danach startet.`,"write.ack.risk":`{risk}: Das Schreiben verlangt, dass Sie das Risiko bestätigen, und die Kamera führt nach dem nächsten Aus- und Einschalten aus, was immer dieser Slot dann enthält.`,"write.ack.bootUnnamed":`der gestartete Slot konnte nicht benannt werden, daher wird dieser als der gestartete behandelt`,"write.ack.recoveryFallback":`Recovery-Slot R ist die letzte Rückfallkopie, auf die der Bootloader zurückgreift`,"boot.cfg0.modernBlank":`leer/0: Slot A bevorzugt, dann B, dann Recovery`,"boot.cfg0.modernB":`Slot B bevorzugt, dann A, dann Recovery`,"boot.cfg0.modernRecovery":`Recovery bevorzugt, dann A, dann B`,"report.nextStart.unknown":`unbekannt — {why}`,"report.nextStart.runs":`{bank} — {why}`,"upgrade.targetBooted":`{name} ist sowohl der Slot, aus dem die Kamera gestartet ist, als auch der Slot, in den ihr eigenes Upgrade schreibt. Ein Upgrade, das von dieser Kamera aus läuft, würde das Image überschreiben, das sie gerade ausführt. Das ist nur eine Warnung: Nichts hier verhindert ein Upgrade.`,"upgrade.whileRecovery":`Die Kamera läuft aus ihrem Recovery-Slot, und ihr eigenes Upgrade schreibt in {name}, aus dem sie nicht läuft. {verdict} Das ist nur eine Warnung: Nichts hier verhindert ein Upgrade.`,"upgrade.verdict.notRead":`{name} konnte bei dieser Prüfung nicht gelesen werden, daher ist nicht bekannt, was er enthält.`,"upgrade.verdict.blank":`{name} ist leer, das Upgrade schreibt also in einen leeren Slot.`,"upgrade.verdict.bootableSame":`{name} enthält dasselbe startfähige Image wie der Slot, aus dem sie läuft, und das Upgrade ersetzt es. {name} bleibt startunfähig zurück, wenn das Upgrade mittendrin abbricht.`,"upgrade.verdict.bootable":`{name} enthält ein startfähiges Image, das das Upgrade ersetzt. {name} bleibt startunfähig zurück, wenn das Upgrade mittendrin abbricht.`,"upgrade.verdict.unknown":`Ob {name} startfähig ist, ist bei diesem Lesen unbekannt, das Upgrade ersetzt also womöglich ein Image, aus dem die Kamera starten würde.`,"upgrade.verdict.notBootable":`{name} wird bei diesem Lesen nicht als startfähig angezeigt, das Upgrade ersetzt also kein Image, aus dem die Kamera starten würde.`,"report.booted.name":`{bank}`,"report.booted.entered":`{bank} — der Slot, den der Bootloader bei diesem Start angesprungen hat, wie er es festhält`,"report.lastStart.notRead":`nicht gelesen`,"report.lastStart.noBank":`die Kamera meldet {word}, was keinen Slot bezeichnet`,"report.lastStart.entered":`die Kamera meldet, dass sie aus {bank} gestartet ist (Aktiv-Slot-Wort {word})`,"running.noVersion":`keine Version`,"running.why.otherVersion":`die Kamera meldet {version}, und nur {only} gibt es in zwei Builds`,"running.why.noVerdicts":`die Kamera hat die Slot-Urteile nicht beantwortet (GetFirmwareInfo-Selektoren 6, 7, 8)`,"running.why.notRead":`ein Slot, von dem die Urteile abhängen, wurde nicht gelesen, daher lassen sich die Antworten nicht vorhersagen`,"running.answers":`die Kamera antwortet {answers}`,"running.answers.each":`A {a}, B {b}, R {r}`,"running.why.plain":`{answers}, was der 8-Hz-Build 1.3.0.8 für diese Slots antwortet ({predicted})`,"running.why.ff":`{answers}, was der 16-Hz-FF-Build 1.3.0.8 für diese Slots antwortet ({predicted})`,"running.why.both":`{answers}, und beide Builds antworten für diese Slots genau so, die Slots unterscheiden sie also nicht`,"running.why.neither":`{answers}, was zu keinem der beiden Builds passt (8 Hz: {plain}; 16 Hz FF: {ff})`,"imageBuild.noVersion":`Der Header dieses Images nennt keine Firmware-Version, daher lässt sich nicht sagen, ob es der Build ist, den die Kamera ausführt ({camera}). Prüfen Sie, ob es das Image ist, das Sie schreiben wollen.`,"imageBuild.otherVersion":`Dieses Image ist Firmware {image}; die Kamera führt {camera} aus.`,"imageBuild.otherVersionTaken":`Dieses Image ist Firmware {image}; die Kamera führt {camera} aus. Auf dieser Firmware-Linie prüft die Kamera nur, ob ein Image wohlgeformt ist (Header und Wortsumme), nicht seine Version. Sie nimmt dieses Image also an, und wenn sie aus diesem Slot startet, führt sie {image} aus.`,"imageBuild.otherVersionUnchecked":`Dieses Image ist Firmware {image}; die Kamera führt {camera} aus. Ob diese Kamera einen anderen Build annimmt und ausführt, wurde nicht geprüft.`,"imageBuild.otherBuild":`Dieses Image ist der 8-Hz-Build {version}; die Kamera führt den 16-Hz-FF-Build {version} aus. Der 16-Hz-Build prüft Nutzdaten beim Commit gegen seine eigene FF-Form und lehnt solche, die durchfallen, ab, bevor er den Slot löscht (laut seinem Quelltext). Den 8-Hz-Build darauf zu schreiben wurde an keiner Kamera ausprobiert.`,"imageBuild.runningUnknown":`Dieses Image ist der 8-Hz-Build {version}. Die Kamera führt {version} aus, das es als 8-Hz- und als 16-Hz-FF-Build gibt, und ihre eigenen Antworten haben nicht gesagt, welchen sie ausführt. Daher lässt sich nicht sagen, ob dies ihr Build ist.`,"bootFail.tooShort":`die Nutzdaten sind {size} B groß, zu kurz für einen Header bei 0x200`,"bootFail.noMagic":`kein Image-Magic bei 0x200 (gefunden {found}, der Bootloader braucht {needs})`,"bootFail.lengthOutside":`header.length {length} liegt außerhalb der Nutzdaten von {size} B`,"bootFail.lengthNotPayload":`header.length {length} ist nicht die Länge der Nutzdaten, {size}`,"bootFail.overStage":`{size} B überschreitet die Übertragungsgrenze von {max} B`,"bootFail.plainSum":`gespeicherte Wortsumme {sum}, der Bootloader von 2014 braucht 0`,"bootFail.noFooter":`kein Footer bei {offset}: die Nutzdaten enden bei {end}`,"bootFail.footerNotCode":`der Footer bei {offset} ist nicht „CODE“ — der Bootloader nimmt seinen segmentierten Loader`,"bootFail.footerLength":`die Footer-Länge ist nicht gleich header.length {length}`,"bootFail.keyASum":`unter Schlüssel A dieser Kamera entschlüsselt ist die Wortsumme {sum}, der Bootloader braucht {needs}`,"keyConfidence.family":`durch die Prüfsumme bestätigt`,"keyConfidence.structural":`nur durch die Vektortabelle bestätigt`,"keyConfidence.unverified":`nicht bestätigt`,"keyCheck.family":`Schlüssel durch die Prüfsumme {sum} bestätigt`,"keyCheck.other":`Schlüssel {phrase}; Prüfsumme {sum}`,"staging.phrase.keyACiphertext":`unter den eigenen Schlüsseln der Kamera übertragen`,"staging.phrase.slotKeystreamCiphertext":`unter dem eigenen Schlüssel des Images übertragen`,"staging.phrase.plain":`unverschlüsselt übertragen`,"staging.phrase.keyAKeystream":`so übertragen, wie die Hersteller-App das FF-Image überträgt (XOR Schlüssel A)`,"staging.phrase.verbatim":`wie angegeben gesendet`,"written.committed":`{size} B per Commit in {name} bei {address} geschrieben, {staged}; Commit-Status {status}`,"written.noReadWindow":`dieser Build nennt kein Lesefenster für den Slot, daher wurde nichts zurückgelesen`,"written.readBackFailed":`das Rücklesen ist fehlgeschlagen: {error}`,"written.readBack":`{size} B zurückgelesen, SHA-256 {sha256}`,"written.verifyOff":`Prüfen ist ausgeschaltet: Der Slot wurde nicht zurückgelesen`,"readBack.reference.folded":`den Bytes, die der Plan für den Slot vorhergesagt hat (das Image so, wie der 16-Hz-Build es speichert, nicht die gesendeten Bytes)`,"readBack.reference.asSent":`den Bytes, die der Plan für den Slot vorhergesagt hat (die Bytes so, wie sie gesendet wurden)`,"readBack.sizeDiffers":`die zurückgelesenen Daten sind {size} B groß, der Plan hat {predictedSize} B vorhergesagt: Der Slot stimmt NICHT überein mit {reference}`,"readBack.matchesFolded":`der Slot enthält das Image so, wie der 16-Hz-Build es speichert (nicht die gesendeten Bytes), und der Rest des Slots ist gelöscht`,"readBack.matches":`der Slot stimmt mit den vom Plan vorhergesagten Bytes überein (die Klartext-Kette von 2014 programmiert genau das, was sie gesendet bekommt)`,"readBack.differs":`der Slot stimmt NICHT überein mit {reference} (erste Abweichung bei {offset})`,"readBack.noHeader":`die zurückgelesenen Daten enthalten keinen Image-Header bei {offset} (Magic {magic}), daher entschlüsselt sich der Slot NICHT zum erwarteten Image`,"readBack.lengthDiffers":`der Header der zurückgelesenen Daten nennt {length} B, das Image des Plans hat {imageLength} B: Der Slot entschlüsselt sich NICHT zum erwarteten Image`,"readBack.tooShort":`die zurückgelesenen Daten sind {size} B groß, zu kurz für ein Image mit {length} B: Der Slot entschlüsselt sich NICHT zum erwarteten Image`,"readBack.recovered":`aus den zurückgelesenen Daten gewonnenen Schlüsselstrom ({check})`,"readBack.decrypts":`der Slot entschlüsselt sich mit dem {recovered} zum erwarteten Image ({length} B)`,"readBack.decryptDiffers":`der Slot entschlüsselt sich NICHT zum erwarteten Image: erste Abweichung bei Image-Offset {offset}, mit dem {recovered}`,"readBack.rawNotCompared":`Rohdaten: Rücklesen gemeldet, nicht verglichen (die Bytes entschlüsseln sich in dieser Form nicht zu einem vorhersagbaren Klartext-Image, und das Gerät verschlüsselt neu, was es behält)`,"readBack.notCompared":`kein Vergleich möglich: Der Plan sagt weder die gespeicherten Bytes noch das Klartext-Image vorher`,"keyName.keyA":`Schlüssel A`,"keyName.keyB":`Schlüssel B`,"keyName.perDevice":`Geräteschlüssel`,"keyName.thePerDevice":`der Geräteschlüssel`,"keyName.applicationKeyA":`Schlüssel A der Anwendung`,"keyName.applicationKeyB":`Schlüssel B der Anwendung`,"keyName.block1":`Schlüsselblock 1`,"keyName.theDeviceKey":`der Geräteschlüssel`,"keyName.unknown":`unbekannter Schlüssel`,"keys.noKnownKey":`kein bekannter Schlüssel`,"keys.evidence.plainChain":`die Klartext-Kette von 2014: Jeder Slot ist im Klartext gespeichert, daher wird kein Upload-Schlüssel abgeleitet; der Upload ist das Image, wie es ist`,"keys.evidence.ffVendor":`der 1.3.0.8-FF-Build (16 Hz): Kein Slot, den dieses Lesen geöffnet hat, ist im Klartext gespeichert, daher ist nicht gezeigt, dass die Kamera auf der Klartext-Kette von 2014 ist; das FF-Image wird in seiner Hersteller-Form geschrieben, Rohdaten werden wie angegeben gesendet, und ein 8-Hz-Klartext-Image wird nicht geschrieben`,"keys.evidence.ffUntested":`ein Schreiben des FF-Images wird mit seiner UNTESTED-Warnung angeboten: Für diesen Build liegt kein echter Bootloader in der Sammlung vor, daher ist nicht gemessen, ob der beschriebene Slot startet`,"keys.evidence.line2016":`die Compact-PRO-Linie von 2016: Ein Upload ist das Image XOR den Schlüsselstrom seines eigenen Schlüsselblocks 0, der im Image anhand des Werts gefunden wird, daher baut ihn kein Schlüssel dieser Kamera`,"keys.evidence.checkKeyUnnamed":`die Kamera entschlüsselt den Upload mit diesem Schlüssel und verschlüsselt ihn neu unter dem Schlüssel, unter dem ihr Bootloader einen Slot prüft; dieser Schlüssel wurde bei diesem Lesen nicht benannt, und der Schreibvorgang braucht ihn nicht: Der Slot wird als das Image zurückgelesen, zu dem er sich entschlüsselt`,"keys.evidence.checkKeyUnnamedWhy":`die Kamera entschlüsselt den Upload mit diesem Schlüssel und verschlüsselt ihn neu unter dem Schlüssel, unter dem ihr Bootloader einen Slot prüft; dieser Schlüssel wurde bei diesem Lesen nicht benannt ({why}), und der Schreibvorgang braucht ihn nicht: Der Slot wird als das Image zurückgelesen, zu dem er sich entschlüsselt`,"keys.evidence.checkKeyNamed":`die Kamera entschlüsselt den Upload mit diesem Schlüssel und verschlüsselt ihn neu unter {key} {hex}, dem Schlüssel, unter dem ihr Bootloader einen Slot prüft, daher wird jeder Slot, den sie schreibt, so gespeichert, wie der Bootloader ihn annimmt`,"keys.evidence.checkKeyInferred":`die Kamera entschlüsselt den Upload mit diesem Schlüssel und verschlüsselt ihn neu unter {key} {hex}, dem Schlüssel, unter dem ihr Bootloader einen Slot prüft (erschlossen aus {bank}, dem Slot, aus dem die Kamera laut eigener Meldung gestartet ist und den der Bootloader ohne seine Prüfung angesprungen hat), daher wird jeder Slot, den sie schreibt, so gespeichert, wie der Bootloader ihn annimmt`,"keys.evidence.checkKeyNamedFrom":`die Kamera entschlüsselt den Upload mit diesem Schlüssel und verschlüsselt ihn neu unter {key} {hex}, dem Schlüssel, unter dem ihr Bootloader einen Slot prüft (benannt anhand von {bank}, dem Slot, aus dem die Kamera laut eigener Meldung gestartet ist), daher wird jeder Slot, den sie schreibt, so gespeichert, wie der Bootloader ihn annimmt`,"keys.evidence.applicationKeyA":`die laufende Anwendung ({bank}, Firmware {firmware}) trägt ihren Schlüssel A {keyA} bei {keyAAt}, aus {source}`,"keys.evidence.applicationKeys":`die laufende Anwendung ({bank}, Firmware {firmware}) trägt ihren Schlüssel A {keyA} bei {keyAAt}, aus {source}, und ihren Schlüssel B {keyB} bei {keyBAt}`,"keys.source.keyTable":`der Schlüsseltabelle des Bootloaders`,"keys.source.applicationPair":`dem dekodierten Anwendungspaar von {builds}`,"keys.evidence.perDevice":`ein Geräteschlüssel ist programmiert, daher verschlüsselt die Anwendung unter ihm neu`,"keys.evidence.noPerDevice":`es ist kein Geräteschlüssel programmiert, daher verschlüsselt die Anwendung unter ihrem eigenen Schlüssel B neu`,"keys.evidence.storeKey":`der Speicherschlüssel der Anwendung ist {key} des Bootloaders ({hex}), daher speichern die Schreibvorgänge jeden Slot darunter; im gestarteten {bank} liegt {held}, was der Bootloader ebenfalls annimmt`,"keys.evidence.bootedKey":`der gestartete {bank} entschlüsselt sich unter {key} ({hex}), einem Schlüssel, den der Bootloader probiert; der Speicherschlüssel der Anwendung ist nicht der des Bootloaders, daher speichern die Schreibvorgänge jeden Slot unter dem Schlüssel des gestarteten Slots`,"keys.evidence.masks":`der Upload ist das Image XOR die Schlüsselströme von {masks}; das Gerät speichert das Image unter {key}`,"keys.evidence.otherBank":`zu {bank} passt {held}; er wird nach derselben Regel unter {key} geschrieben und zur Prüfung zurückgelesen`,"keys.refused.bootUnnamed":`der gestartete Slot konnte nicht benannt werden, daher lässt sich daraus nicht lesen, unter welchem Schlüssel der Slot gespeichert ist`,"keys.refused.notDerived":`die Schlüssel konnten nicht abgeleitet werden`,"keys.refused.notDecrypted":`der gestartete {bank} entschlüsselt sich nicht zu einem Image, daher lässt sich der Schlüssel, unter dem er gespeichert ist, nicht lesen`,"keys.refused.noBootKey":`der gestartete {bank} entschlüsselt sich unter keinem Schlüssel, den der Bootloader probiert (seinem Schlüssel A oder seinem Speicherschlüssel), daher lässt sich daraus nicht lesen, unter welchem Schlüssel der Slot gespeichert ist`,"keys.refused.keyNotInTable":`der gestartete {bank} entschlüsselt sich unter {key}, aber die Schlüsseltabelle dieser Kamera enthält diesen Schlüssel nicht, daher kann nicht darunter geschrieben werden`,"keys.refused.noApplicationPair":`die laufende Anwendung ({bank}, Firmware {firmware}) enthält keines der bekannten Schlüsselpaare (das des Bootloaders und die dekodierten Anwendungspaare) mit jeder Hälfte genau einmal, daher lässt sich ihr Schlüssel A in ihrem Image nicht finden`,"keys.refused.noApplicationPairCounted":{one:`die laufende Anwendung ({bank}, Firmware {firmware}) enthält keines der bekannten Schlüsselpaare (das des Bootloaders und die dekodierten Anwendungspaare) mit jeder Hälfte genau einmal, daher lässt sich ihr Schlüssel A in ihrem Image nicht finden (Schlüssel A des Bootloaders kommt {count}-mal vor, sein Schlüssel B {keyB}-mal)`,other:`die laufende Anwendung ({bank}, Firmware {firmware}) enthält keines der bekannten Schlüsselpaare (das des Bootloaders und die dekodierten Anwendungspaare) mit jeder Hälfte genau einmal, daher lässt sich ihr Schlüssel A in ihrem Image nicht finden (Schlüssel A des Bootloaders kommt {count}-mal vor, sein Schlüssel B {keyB}-mal)`},"keys.refused.uploadChecked":`die laufende Anwendung ({bank}, Firmware {firmware}) prüft einen Upload unter ihren eigenen Schlüsseln, bevor sie ihn programmiert (der dekodierte Quelltext dieses Builds probiert den Upload unter ihrem Schlüssel A und ihrem Speicherschlüssel, so wie ihr Bootloader einen Slot probiert), und der Schlüssel, unter dem die Schreibvorgänge speichern, {key} ({hex}), ist weder ihr Schlüssel A noch ihr Speicherschlüssel, daher würde die Kamera den Upload mit 0x50000 ablehnen, bevor sie irgendetwas löscht`,"writeRefusal.acceptanceSum":`kein Slot entschlüsselt sich zur Prüfsumme {sum} von {family}`,"writeRefusal.keyTable":`die Schlüsseltabelle dieser Kamera konnte nicht bestätigt werden`,"writeRefusal.whitening":`die Schlüsseltabelle dieser Kamera löst sich unter K={k} auf, aber {family} verschlüsselt unter K={expected}`,"writeRefusal.otherFamily":`die Hinweise sagen, dass diese Kamera {detected} ist, nicht {family} ({reasons})`,"writeRefusal.camera":`diese Kamera kann von hier aus nicht beschrieben werden: {reasons}`,"family.summary.modern":`Die Builds von Seek ab 2018 (2.x, 4.x, 10.x, 42.x, 44.x): Compact 4.8/4.16, Compact Pro 4.9/4.18, Compact Pro FF, Compact XR, Mosaic 2.27/10.9, Nano 200 und Nano 300. Ein Auslesen liest 63 der 64 Blöcke des Flash-Speichers, ohne etwas zu entsperren; kein Lesen erreicht auf diesen Builds den Block bei {block}. Die Firmware ist verschlüsselt gespeichert. Slots werden einzeln im Tab „Firmware-Slots bearbeiten“ geschrieben.`,"family.summary.early":`Die Compacts von 2014, die älter als 0.8.0.0 sind: 0.3.0.1, 0.5.0.2, 0.5.1.0, 0.5.1.3, 0.6.0.4, 0.7.0.7 und 0.7.0.8. Ihre Firmware kann den Lesebefehl eines Auslesens nicht beantworten, daher lehnen „Auslesen“, „Alle Selektoren auslesen“, das vollständige Lesen im Tab „Info“ und der Tab „Firmware-Slots bearbeiten“ sie nach dem Lesen der Version ab; auf 0.3.0.1 würde der Befehl, mit dem ein Auslesen beginnt, stattdessen ein Firmware-Upgrade vorbereiten. Der Preserve-Durchlauf liest 0.7.0.7 und 0.7.0.8 über einen anderen Befehl, den diese beiden Builds beantworten. Ein auf anderem Weg erstelltes Flash-Abbild lässt sich wie gewohnt entschlüsseln.`,"family.summary.compact2016":`Die Builds 1.0.3.x der Compact PRO (1.0.3.0 und 1.0.3.2). Sie beantworten Lesebefehle genau wie die Compacts von 2014, Entsperr-Token eingeschlossen. Unterschieden werden sie daher an ihrer Version und daran, wie ihre Slots gespeichert sind: verschlüsselt, während die Slots von 2014 im Klartext vorliegen. Eine Kamera mit 1.0.3.x wird von Anfang an als diese Familie gelesen. Der Preserve-Durchlauf liest den gesamten Flash-Speicher, und Slots werden einzeln im Tab „Firmware-Slots bearbeiten“ geschrieben.`,"family.summary.legacy":`Die Compacts von 2014 mit 0.8.0.0 bis 1.3.0.8, darunter der 16-Hz-Build 1.3.0.8 FF. Eine Kamera im Originalzustand gibt weniger als die Hälfte ihres Flash-Speichers heraus, einen Teil davon nur gegen ein Entsperr-Token, das das Toolkit sendet; der Preserve-Durchlauf liest den Rest über einen vorübergehenden Patch. Slots sind im Klartext gespeichert, außer beim FF-Build. Eine Compact PRO mit 1.0.3.x wird als compact-2016 gelesen und wechselt nur hierher, wenn ein Slot im Klartext gespeichert ist oder sich zu {sum} entschlüsselt, wie die Slots des FF-Builds. Slots werden im Tab „Firmware-Slots bearbeiten“ auf den Builds geschrieben, an denen der Preserve-Durchlauf gemessen wurde; jeder andere Build mit 0.x oder 1.x wird nur gelesen.`,"family.summary.generic":"Eine Kamera, zu der keine andere Familie passt. `seek-fw dump` liest sie mit der 4.x-Blockliste (der 4.x/Nano-Tab lehnt sie ab), und eine Entschlüsselung berechnet den Schlüssel aus dem Image selbst, daher hängt keines von beiden von der Vermutung ab. Es wird kein Slot geschrieben: Der Tab „Firmware-Slots bearbeiten“ lehnt sie ab, bis die Kamera erkannt ist.","detect.source.header":`der Image-Header nennt`,"detect.source.camera":`die Kamera meldet`,"detect.plainArmedNotInForce":`ein einfaches 2-Byte-BeginFirmwareUpgrade hat einen geschützten Slot geöffnet, daher ist der authentifizierte Lesekanal nicht in Kraft`,"detect.modern.plainRefused":`ein einfaches 2-Byte-BeginFirmwareUpgrade für einen geschützten Slot wurde ABGELEHNT, was kein Build dieser Linie tut — sein Handler hat keine Token-Prüfung und nimmt den einfachen Kanal auf jedem Slot an`,"detect.modern.authArmed":`ein geschützter Slot wurde über den authentifizierten 18-Byte-Selektor geöffnet; den einfachen hat dort niemand probiert, daher ordnet das diese Kamera nicht außerhalb dieser Linie ein`,"detect.modern.legacyVersion":`{said} Firmware {version}, die auf der Legacy-Linie 0.x / 1.x liegt (eine andere Nummerierung, kein älteres 4.x — und einer dieser Builds trifft ebenfalls die Summe {sum})`,"detect.modern.noSum":`kein Slot entschlüsselt sich zur Prüfsumme {sum}, die der Bootloader dieser Familie verlangt`,"detect.modern.sum":`ein Slot entschlüsselt sich zur Prüfsumme {sum}`,"detect.modern.version":`Firmware {version} liegt auf der Linie ab 2018, die diese Selektortabelle abdeckt (2.x / 4.x / 10.x / 42.x / 44.x: Compact, Compact Pro, Compact XR, Mosaic, Nano)`,"detect.modern.plainWorks":`ein einfaches 2-Byte-BeginFirmwareUpgrade hat einen geschützten Slot geöffnet, daher ist das nicht die gesperrte Legacy-Firmware`,"detect.modern.none":`keine Hinweise, die diese Kamera auf die Linie ab 2018 einordnen`,"detect.early.noVersion":`es wurde keine Firmware-Version gemeldet oder in einem Image-Header gefunden`,"detect.early.readable":`Firmware {version} ist {first} oder neuer, daher hat ihre RPC-Tabelle einen Getter für GetFeaturedFirmwareData, und der normale Leseweg gilt`,"detect.early.older":`{said} Firmware {version}, die älter ist als {first} — der erste Build, dessen RPC-Methodentabelle einen Lese-Handler (Getter) für GetFeaturedFirmwareData hat`,"detect.early.noWindow":`und kein Fenster konnte gelesen werden, was genau dazu passt`,"detect.generic.fallback":`Ersatzlösung: Keine Firmware-Familie passte sicher, daher bleibt Lesen möglich und Schreiben nicht`,"detect.compact2016.early":`Firmware {version} ist älter als 0.8.0.0 und hat keinen Lese-Handler für GetFeaturedFirmwareData — das ist early-compact, nicht diese Familie`,"detect.compact2016.modernSum":`ein Slot entschlüsselt sich zur Prüfsumme {sum}, die nicht das Ziel dieser Generation ist`,"detect.compact2016.plainArmed":`ein einfaches 2-Byte-BeginFirmwareUpgrade hat einen geschützten Slot geöffnet, daher ist diese Kamera nicht auf der gesperrten Linie, die diese Familie mit legacy-auth teilt`,"detect.compact2016.notLine":`Firmware {version} liegt nicht auf der Linie 0.x / 1.x`,"detect.compact2016.storedPlain":`ein Slot ist im Klartext gespeichert — die Schlüsselstrom-Berechnung liefert den Identitätszustand, seine gespeicherten Wörter SIND also das Image —, das ist die Klartext-Kette von 2014; die Slots dieser Generation sind xorshift128 unter einem echten Schlüssel`,"detect.compact2016.keyedZero":`ein unter einem echten xorshift128-Schlüsselstrom gespeicherter Slot entschlüsselt sich zur Prüfsumme {sum}, was die Verschlüsselung dieser Generation ist`,"detect.compact2016.zeroSum":`ein Slot entschlüsselt sich zur Prüfsumme {sum}, die das Ziel dieser Generation ist`,"detect.compact2016.refused":`und ein geschützter Slot hat das einfache 2-Byte-Öffnen abgelehnt, was der gesperrte Handler ist`,"detect.compact2016.proLine":`{said} Firmware {version}, die 1.0.3.x-Linie der Compact PRO von 2016`,"detect.compact2016.compactLine":`{said} Firmware {version}, ein Compact-Build, nicht die 1.0.3.x-Linie der Compact PRO`,"detect.compact2016.lockedLine":`{said} Firmware {version}, auf der Linie 0.x / 1.x, die diese Generation mit der gesperrten Legacy-Firmware teilt`,"detect.compact2016.bootloader2016":`der Bootloader meldet {version}, einen Bootloader der Generation 2016 (1.2.0.0 ist unter Compact PRO 1.0.3.0 gemessen; der der Compact von 2014 ist 0.9.0.0)`,"detect.compact2016.bootloader2014":`der Bootloader meldet {version}, die Nummerierung der Generation 2014, nicht die dieser Generation`,"detect.compact2016.none":`bei keinem Slot wurde beobachtet, dass er sich unter einem echten Schlüssel zu einer Prüfsumme von null entschlüsselt`,"detect.legacy.proLine":`aber Firmware {version} ist die 1.0.3.x-Linie der Compact PRO von 2016, deren Slots die Verschlüsselung von compact-2016 haben: Die Annahmeprüfung dieser Familie würde jeden von ihnen ablehnen`,"detect.legacy.early":`Firmware {version} ist älter als 0.8.0.0: Ihre RPC-Tabelle hat keinen Lese-Handler für GetFeaturedFirmwareData (vor 0.7.0.7 gar keinen, und auf 0.7.0.7 und 0.7.0.8 nur einen Setter) — das ist early-compact, nicht diese Familie`,"detect.legacy.keyedZero":`ein unter einem echten xorshift128-Schlüsselstrom gespeicherter Slot entschlüsselt sich zu {zero} — die Verschlüsselung der Compact PRO von 2016 (compact-2016). Diese Linie speichert ihre Slots im Klartext mit einer Wortsumme von 0 (die Kette von 2014) oder auf {sum} abgestimmt (Compact 1.3.0.8), und ihre Annahmeprüfung lehnt einen solchen Slot ab`,"detect.legacy.plainChain":`ein Slot ist als Klartext-Firmware gespeichert, deren Wörter sich zu 0 summieren, so wie der Bootloader von 2014 dieser Linie ihn startet`,"detect.legacy.refused":`die Kamera hat es abgelehnt, einen gesperrten Slot für ein Upgrade zu öffnen, als sie ohne die Entsperrung gefragt wurde, was nur diese Firmware-Generation tut`,"detect.legacy.unlocked":`und sie hat denselben Slot geöffnet, als sie mit der Entsperrung gefragt wurde, die Entsperrung dieser Familie ist also die, die diese Kamera prüft`,"detect.legacy.notLine":`{said} Firmware {version}, die nicht auf der Legacy-Linie 0.x / 1.x liegt`,"detect.legacy.authOnly":`sie hat einen gesperrten Slot für ein Upgrade geöffnet, als sie mit der Entsperrung gefragt wurde, wie diese Firmware-Generation es tut; ohne Entsperrung wurde nicht gefragt, daher belegt das allein die Generation nicht`,"detect.legacy.version":`Firmware {version} liegt auf der Legacy-Linie 0.x / 1.x, einer anderen Nummerierung als die Anwendungsversionen ab 2018, nicht auf einem älteren 4.x`,"detect.legacy.none":`nichts Beobachtetes deutet auf den authentifizierten Lesekanal hin`,"fps.table.withheld":`nach einem Lauf an einer Kamera zurückgehalten: Dort hat der Patch die Ausgaberate nicht erhöht, und der Verschluss hat nach dem Schreiben bei jedem Bild ausgelöst`,"fps.table.predates":`Firmware {version} ist älter als 0.8.0.0: Ihre RPC-Tabelle hat keinen Lese-Handler für GetFeaturedFirmwareData, den Befehl, den ein Slot-Lesen sendet. Daher lesen und schreiben die Slot-Funktionen keinen Slot dieses Builds, und der Patch wird nicht angeboten`,"fps.table.stageTwoFf":`stage two: Der 16-Hz-FF-Build wird so übertragen, wie die Hersteller-App ihn überträgt (das Image XOR Schlüssel A, gespeichert unter Schlüssel B), nicht als Klartext-Bytes, daher ist seine Übertragungsprüfung nicht erledigt, und der Patch wird noch nicht angeboten`,"fps.table.stageTwo":`stage two: Dieser Eintrag gehört nicht zur stage-two-Gruppe, daher ist seine Übertragungsprüfung nicht erledigt, und der Patch wird noch nicht angeboten`,"fps.table.notOffered":`nicht angeboten`,"fps.table.notImage":`das ist kein Firmware-Image, daher gilt dafür kein Bildraten-Patch`,"fps.table.otherBuild":`das Image ist der Build {image} („{id}“), aber die Kamera meldet {camera}; der Patch wird abgelehnt, statt auf einen Build angewendet zu werden, zu dem er nicht passt`,"fps.table.otherBuildNoVersion":`das Image ist der Build {image} („{id}“), aber die Kamera meldet keine Version; der Patch wird abgelehnt, statt auf einen Build angewendet zu werden, zu dem er nicht passt`,"fps.table.patched":`der Bildraten-Patch ist bereits angewendet: Dieses Image läuft mit {hz} Hz`,"fps.table.earlierPatch":`dieses Image enthält einen früheren {hz}-Hz-Bildraten-Patch ohne die USB-Korrektur, und ein Patch wird nie auf ein gepatchtes Image angewendet: Stellen Sie das Original-Image wieder her und patchen Sie es dann`,"fps.table.atRate":`dieser Build läuft bereits ohne Patch mit {hz} Hz`,"fps.table.not4821":`dieses Image meldet den Build Compact 4.8.2.1 (oder Compact XR 4.8.2.1, derselbe Build), ist aber nicht das Original-Image, für das der Bildraten-Patch geschrieben wurde (f96ac57eda75: seine 68-Byte-Befehlsseiten, stabile Seite 13), daher wird dafür kein Bildraten-Patch erstellt`,"fps.table.notInTable":`dieses Image ist nicht in der Tabelle der Bildraten-Patches, daher wird für diesen Build kein Bildraten-Patch erstellt. Die Tabelle nennt die Compact-Builds 0.7.0.8 bis 1.3.0.8 (8 Hz; 0.7.0.8 wird vom Slot-Code abgelehnt), 1.3.0.8 (16 Hz FF), 4.8.1.7, 4.8.1.9, 4.8.2.1 und 4.16.1.7 FF sowie die Compact-PRO-Builds 1.0.3.x und 4.9.x; kein anderer Build hat einen Eintrag`,"fps.plan.noBank":`der Plan dieses Builds hat keinen {bank}`,"fps.plan.noPlain":`{bank} kann auf diesem Build kein entschlüsseltes Image annehmen: {reason}`,"fps.plan.empty":`{bank} hat kein entschlüsseltes Image zum Patchen (er ist leer)`,"fps.plan.noImage":`{bank} hat kein entschlüsseltes Image zum Patchen (er wurde nicht gelesen, oder kein Schlüssel öffnet ihn)`,"fpsEvery.stopped.readBack":`{name} wurde geschrieben, aber die zurückgelesenen Daten weichen nicht nur wie geplant vom gesicherten Slot ab, daher wurden die Slots danach nicht geschrieben`,"fpsEvery.stopped.error":`{name}: {error}`,"notes.lockedBootWord":`Der gestartete Slot, der auf dieser Firmware-Linie genannt wird, ist der Slot, aus dem die Kamera bei ihrem letzten Start gestartet ist, wie ihn das Aktiv-Slot-Wort festhält (0 Slot A, 1 Slot B, 2 Recovery-Slot R). Der nächste Start wird durch das Boot-Konfigurationswort festgelegt: 0 oder 0xFFFFFFFF wählen zuerst A, 1 zuerst B, jeder andere Wert zuerst Recovery-Slot R. Recovery-Slot R läuft immer dann, wenn A und B nichts enthalten, was der Bootloader von 2014 annimmt (einen Slot, dessen Wörter sich zu 0 summieren), egal was R enthält (an einer Kamera gemessen).`,"notes.locked2016BootWord":`Der gestartete Slot, der auf dieser Firmware-Linie genannt wird, ist der Slot, aus dem die Kamera bei ihrem letzten Start gestartet ist, wie der Bootloader ihn im Aktiv-Slot-Wort festhält (0 Slot A, 1 Slot B, 2 Recovery-Slot R). Der nächste Start wird durch das Boot-Konfigurationswort festgelegt: 0 oder 0xFFFFFFFF wählen zuerst A, 1 zuerst B, jeder andere Wert zuerst Recovery-Slot R. Der Bootloader von 2016 nimmt einen Slot nur an, wenn er sich unter dem Schlüssel, unter dem er einen Slot prüft (Schlüsselblock 1 auf seinem Bootloader 1.2.0.0), zu einer Wortsumme von 0 entschlüsselt, und der letzte Slot dieser Reihenfolge läuft ungeprüft, wenn die anderen beiden scheitern. Das Lesen benennt diesen Schlüssel anhand des Slots, aus dem die Kamera gestartet ist, weil der Bootloader-Block, der ihn enthält, auf jedem Kanal abgelehnt wird (an einer Kamera gemessen).`,"notes.ep0of1032":`1.0.3.2: EP0-Sitzungen brechen bei etwa 64 bis 81 KB ab, und 128 B ist die verlustfreie Leseeinheit, daher ist ein 64-KB-Slot pro Sitzung die gemessene Grenze. Ein volles Auslesen des ganzen Chips wird auf diesem Build abgelehnt (PRESERVATION.md: Es gibt kein volles Auslesen mit einer einzigen Öffnung). Das Auslesen der Slots liest einen Slot nach dem anderen, in Anfragen zu 64 Bytes.`,"notes.token":`Auf dieser Firmware-Linie sind die Slots gesperrt: Die Kamera öffnet einen Slot nur dann zum Schreiben, wenn sie mit der Entsperrung dieser Linie gefragt wird, die in allen 22 erfassten Firmware-Images dieser Linie gleich ist. Eine Kamera mit einer anderen Entsperrung lehnt ihre Slots ab.`,"notes.staging.lockedPlain":`Übertragen: das Image selbst, höchstens 56 KB (das Meiste, was die Kamera in einem Schreibvorgang annimmt). Der Schreibvorgang löscht den 64-KB-Slot und schreibt genau diese Bytes, und der Rest des Slots liest sich gelöscht. Der Bootloader startet einen Slot nur, wenn dessen Wörter sich zu 0 summieren, daher wird das Image vor dem Senden auf diese Summe ausgeglichen.`,"notes.staging.locked2016":`Übertragen: das Image, XOR den xorshift128-Schlüsselstrom seines EIGENEN Schlüsselblocks 0 (der Übertragungsschlüssel, im Image anhand des Werts gefunden), nur in Image-Länge (höchstens 0xE000 Bytes). Das Gerät entschlüsselt die Nutzdaten mit diesem Schlüssel und speichert sie unter dem Schlüssel, unter dem sein Bootloader einen Slot prüft (Schlüsselblock 1), daher sind die gespeicherten Bytes nicht die übertragenen. Zum Übertragen wird nichts aus dem Ziel-Slot gelesen: Der Schlüsselstrom des Slots dient nur zum Zurücklesen des Slots.`,"notes.staging.modern":`Übertragen: der ganze 64-KB-Slot, Image + 0xFF-Auffüllung + „CODE“-Footer. Das Image wird mit den Schlüsselströmen XOR-verknüpft, die dafür sorgen, dass die zwei eigenen Durchgänge der laufenden Anwendung es unter dem Schlüssel ablegen, den der gestartete Slot enthält: Wenn der Commit-Befehl (CompleteMemoryUpgrade) Datentyp 7, 8 oder 9 erhält, entschlüsselt die Anwendung den Upload mit ihrem Schlüssel A, verschlüsselt ihn unter ihrem Speicherschlüssel neu und programmiert den Slot. Der Footer sorgt dafür, dass der Bootloader den Slot annimmt; ein Slot ohne ihn wird abgelehnt.`,"notes.modernGap":`Slot B liegt auf dieser Firmware-Linie bei 0x14050000 (Modus 8). Kein Selektor erreicht 0x14060000 auf irgendeinem Build 2.x, 4.x, 10.x, 42.x oder 44.x (dekodiert aus den 14 Images der Sammlung ab 2018), daher liegt dort kein Slot. Das Layout mit 0x14060000 gehört zur gesperrten Linie 0.x/1.x.`,"notes.modernNamedWrite":`Benannte Schreibvorgänge (Modi 7 bis 9) sind aus der Firmware dekodiert. Der Emulator schreibt A, B und R über sie auf den 4.x-Builds, und an einer Kamera wurde Slot A einer Compact XR 4.8.2.1 über Modus 7 vom Bildraten-Patch beschrieben. Ein Slot-Schreiben öffnet nie Modus 0, das Upgrade-Ziel.`,"notes.unverified":`Nur Lesen. Das Slot-Layout ist die dekodierte Tabelle der gesperrten Linie, aber für diesen Build wurde keine Übertragungsform gemessen, daher wird kein Schreibvorgang geplant.`,"notes.empty.plain":`Ein leerer Slot nimmt ein Image genauso an wie ein belegter. Die Klartext-Kette überträgt die Image-Bytes, wie sie sind, ohne Schlüssel, und der Commit löscht den Block zuerst, daher wird nichts aus dem Ziel-Slot gelesen. An einer Compact gemessen: Ein in einen leeren Slot B geschriebenes Image las sich identisch zurück, und B startete allein.`,"notes.empty.modern":`Ein leerer Slot nimmt ein Image genauso an wie ein belegter. Die Nutzdaten werden unter Schlüsseln verschlüsselt, die vom gestarteten Slot und der laufenden Anwendung abgeleitet sind, nicht vom Ziel-Slot, und das Gerät verschlüsselt sie neu und löscht den Block, ohne ihn zu lesen. Der Footer wird aus einem Slot kopiert, der einen gültigen enthält, sonst leer aufgebaut. Auf dem Emulator nachgewiesen; an einer Kamera noch nicht gemessen.`,"notes.empty.locked2016":`Ein leerer Slot nimmt ein Image genauso an wie ein belegter. Der Übertragungsschlüssel ist Schlüsselblock 0 aus dem eigenen Paar des IMAGES, kein aus dem Ziel-Slot gelesener Schlüssel, und das Gerät entschlüsselt die Nutzdaten damit, speichert sie unter seinem eigenen Schlüssel und löscht den Block, ohne ihn zu lesen. Auf dem Emulator nachgewiesen; an einer Kamera noch nicht gemessen.`,"notes.mode2of080":`0.8.0.0: Modus 2 (0x14000000) ist auf diesem Build eine Absturzgefahr, ein geöffnetes Lesen läuft über das SRAM hinaus (PRESERVATION.md). Ein Slot-Lesen oder -Schreiben öffnet nur die Modi 7 bis 9 und nie Modus 2.`,"notes.keyPairs2016":`Die 9-Hz-Builds von 1.0.3.0 und 1.0.3.2 teilen sich ein Schlüsselpaar, die FF-Builds ein anderes. Die Versionszeichenkette unterscheidet sie nicht, daher wird der Schlüsselstrom aus dem Slot selbst gewonnen, und das eigene Image des Slots entscheidet.`,"notes.board1030":`Die Anwendung 1.0.3.0 startet auf jeder Platine außer der der Compact Pro neu, daher läuft sie auf einer Compact-Platine nur mit dem Platinen-Patch in ihren Slots.`,"notes.bank.modernA":`Geschrieben über eine Slot-Öffnung, die die moderne Tabelle auslässt; eine Compact XR 4.8.2.1 hat darüber einen Schreibvorgang angenommen (an einer Kamera).`,"notes.bank.recovery2016":`An einer Compact PRO 1.0.3.0 gemessen: Recovery-Slot R hat sein eigenes Image, eine Änderung um ein Byte und die Rohdaten so, wie sie gesendet wurden, angenommen, jeweils ohne Fehler geschrieben.`,"notes.bank.ff1308A":`Das 1.3.0.8-FF-Image (16 Hz) kommt hierher in der Form, in der die Hersteller-App es sendet, und die Kamera speichert es unter ihrem eigenen Schlüssel. Der Bootloader von 2014 startet einen Slot nur, wenn dessen Wörter sich zu 0 summieren, daher übergeht er diesen beim Start; ob der 16-Hz-Build aus Slot A startet, ist UNTESTED (ungetestet). Das 8-Hz-Image wird so geschrieben, wie es ist.`,"notes.bank.ff1308B":`Das 1.3.0.8-FF-Image (16 Hz) kommt hierher in der Form, in der die Hersteller-App es sendet, und die Kamera speichert es unter ihrem eigenen Schlüssel. Der Bootloader von 2014 startet einen Slot nur, wenn dessen Wörter sich zu 0 summieren, daher übergeht er diesen beim Start; ob der 16-Hz-Build aus Slot B startet, ist UNTESTED (ungetestet). Das 8-Hz-Image wird so geschrieben, wie es ist.`,"notes.bank.ff1308R":`Das 1.3.0.8-FF-Image (16 Hz) kommt hierher in der Form, in der die Hersteller-App es sendet, und die Kamera speichert es unter ihrem eigenen Schlüssel. Der Bootloader 0.9.0.0 startet Recovery-Slot R so, wie er gespeichert ist, ohne ihn zu dekodieren, daher startet diese Form womöglich nicht: UNTESTED (ungetestet), und eine frühere Form dieses Images ist von hier gestartet (an einer Kamera gemessen). Das 8-Hz-Image wird so geschrieben, wie es ist.`,"notes.product.4_8_2_1":`Compact 4.8.2.1 und Compact XR 4.8.2.1 (ein Image): die moderne Tabelle mit 63 Fenstern; der Emulator hat 63 von 63 Fenstern am vollständigen Flash-Abbild der Compact und an dem der Compact XR bestätigt.`,"notes.product.10_9_1_31":`Mosaic 320x240 10.9.1.31: die moderne Tabelle mit 63 Fenstern, gemessen: Auf dem Emulator wird jedes Fenster bestätigt.`,"notes.product.2_27_1_33":`Mosaic 320x240 FF 2.27.1.33: die moderne Tabelle mit 63 Fenstern, gemessen: Auf dem Emulator wird jedes Fenster bestätigt.`,"notes.product.42_32_3_10":`Nano 200 42.32.3.10: die moderne Tabelle mit 63 Fenstern, gemessen: Auf dem Emulator wird jedes Fenster bestätigt. Sein Commit-Befehl (CompleteMemoryUpgrade) hat keinen Handler für Datentyp 32, nach dem ein Schreiben über Modus 7, 8 oder 9 nie fragt.`,"notes.product.44_27_3_10":`Nano 300 44.27.3.10: die moderne Tabelle mit 63 Fenstern, gemessen: Auf dem Emulator wird jedes Fenster bestätigt. Sein Öffnungsbefehl (BeginFirmwareUpgrade) lehnt einen Datentyp jenseits des angenommenen Bereichs (0x7F) als ungültiges erstes Argument ab, und die Modi 7 bis 9 liegen innerhalb dieses Bereichs.`,"notes.ff1308":`1.3.0.8-FF (16 Hz) meldet dieselbe Version wie der 8-Hz-Build. Das Lesen unterscheidet sie an der Kamera: Die Kamera sagt Slot für Slot, ob ihre Anwendung den Slot annimmt, und für jeden Build lassen sich seine Antworten aus den Slots vorhersagen. Das FF-Image wird in der Form gesendet, in der die Hersteller-App es sendet, und die Kamera speichert es unter ihrem eigenen Schlüssel. Es kann in Slot A, Slot B oder Recovery-Slot R. Vom 8-Hz-Build wird erwartet, dass er es ablehnt, bevor er irgendetwas schreibt; solange die Antworten der Kamera die Builds nicht unterscheiden können, sagt der Plan, was jeder Build damit tut. {untested}`,"identity.versionUnknown":`die Kamera hat ihre Firmware-Version nicht gemeldet ({note}); eine Befehlsnummer bedeutet nicht in jeder Seek-Firmware dasselbe — auf Compact 0.3.0.1 ist Wire-ID 0x52, die ID, die ein Lesefenster öffnet, EnterBootloaderMode —, daher wird, bis die Version bekannt ist, nichts gesendet außer GetErrorCode, GetOperationMode und GetFirmwareInfo, den Lesebefehlen, die jeder Build gleich beantwortet`,"identity.note.startup":`GetFirmwareInfo hat bei keinem von {reads} Lesevorgängen im Abstand von {spacing} ms geantwortet ({error}), einem Startfenster von {window} ms; eine Kamera, die noch startet, antwortet innerhalb dieser Zeit`,"identity.note.neverTwice":`GetFirmwareInfo wurde in {reads} Lesevorgängen nie zweimal hintereinander beantwortet`,"identity.note.noAnswer":`GetFirmwareInfo hat nicht geantwortet ({error})`,"identity.note.noAnswerSome":`GetFirmwareInfo hat nicht geantwortet ({error}); {answered} von {reads} Lesevorgängen wurden beantwortet, nie zwei hintereinander, daher lässt sich keine dieser Antworten von einem Datensatz unterscheiden, den ein früherer Befehl ausgewählt hinterlassen hat`,"identity.note.tooShort":{one:`GetFirmwareInfo hat mit {count} Byte geantwortet, zu wenig für eine Version`,other:`GetFirmwareInfo hat mit {count} Byte geantwortet, zu wenig für eine Version`},"identity.note.tooShortContext":{one:`GetFirmwareInfo hat mit {count} Byte geantwortet, zu wenig für eine Version; {context}`,other:`GetFirmwareInfo hat mit {count} Byte geantwortet, zu wenig für eine Version; {context}`},"identity.note.otherRecord":`der erste Lesevorgang hat einen anderen Datensatz geliefert ({version}), auf den ein früherer Befehl den Firmware-Info-Selektor gestellt hatte — dieser Lesevorgang hat ihn zurückgesetzt`,"identity.note.afterStartup":{one:`sie hat geantwortet, nachdem sie während des Starts {count}-mal das Lesen abgelehnt hatte`,other:`sie hat geantwortet, nachdem sie während des Starts {count}-mal das Lesen abgelehnt hatte`},"identity.predates":`Firmware {version} ist älter als das Auslese-Protokoll: Ihre RPC-Methodentabelle hat keinen Lese-Handler für GetFeaturedFirmwareData (auf 0.7.0.7 und 0.7.0.8 ist er nur als Setter registriert, und davor ist Wire-ID 0x4F UploadFirmwareRowSize), daher kann damit kein Fenster gelesen werden; auf 0.3.0.1 ist Wire-ID 0x52 EnterBootloaderMode statt BeginFirmwareUpgrade. Der Preserve-Durchlauf liest 0.7.0.7 und 0.7.0.8 stattdessen über Wire-ID 0x58 (GetFeaturedData)`,"identity.refusing":`{operation} abgelehnt: {reason}`,"identity.refusingNoVersion":`{operation} abgelehnt: {reason}. Es wurde kein Fenster geöffnet. Ziehen Sie die Kamera ab, stecken Sie sie wieder ein, lassen Sie sie fertig starten und versuchen Sie es erneut.`,"identity.operation.dump":`Auslesen`,"identity.operation.dumpAll":`Auslesen aller Selektoren`,"identity.operation.readInfo":`Lesen der Geräteinformationen`,"preserve.banks.beforeBackup":`die Slots werden nach der Sicherung gewählt, die sie liest — führen Sie zuerst die Sicherung aus`,"preserve.banks.afterCommit":`die Slots können sich nicht mehr ändern, sobald der Commit gelaufen ist oder versucht wurde: Dieser Durchlauf schreibt {banks}, und die Wiederherstellung stellt genau diese wieder her`,"preserve.banks.none":`keinen Slot`,"status.written":`Geschrieben.`,"status.read":`Gelesen. {count}/{of} Slots lesbar.`,"status.readRefused":`Gelesen, aber kein Slot dieser Kamera kann von hier aus beschrieben werden — siehe Protokoll.`,"compare.field.version":`Firmware-Version`,"compare.field.imageId":`Image-ID`,"compare.field.initialSp":`Anfangs-SP`,"compare.field.resetVector":`Reset-Vektor`,"compare.field.size":`Größe`,"compare.field.shaExpected":`SHA-256 des erwarteten Klartext-Images`,"compare.field.sha":`SHA-256 des Images`,"compare.field.shaNotStored":`SHA-256 des erwarteten Klartext-Images (gespeicherte Bytes nicht vorhergesagt)`,"compare.field.key":`Schlüssel`,"compare.noImage":`(kein Image)`,"compare.notImage":`(kein gültiges Image)`,"compare.notPredicted":`(nicht vorhergesagt: Das Gerät entscheidet, was es speichert)`,"compare.plaintext":`keiner (Klartext)`,"boot.verdict.unsettled":`ließ sich nicht zweimal gleich lesen`,"preserve.boot.inferred":`{why} (der Schlüssel, unter dem der Bootloader einen Slot prüft, ist aus {bank} erschlossen, den er ohne seine Prüfung angesprungen hat) [inferred]`,"preserve.lastStart.entered":`{bank}, wie die Kamera es festhält (Aktiv-Slot-Wort {word})`,"preserve.lastStart.notRead":`unbekannt — das Aktiv-Slot-Wort konnte nicht gelesen werden`,"preserve.lastStart.noBank":`unbekannt — das Aktiv-Slot-Wort ist {word}, was keinen Slot bezeichnet`,"preserve.nextStart.known":`{bank} — {why}`,"preserve.nextStart.unknown":`unbekannt — {why}`,"preserve.bank.notWritten":`wird nicht beschrieben — {reason}`,"preserve.bank.anImage":`ein Image`,"preserve.bank.writable":`{build} — beschreibbar`,"preserve.bank.writablePatch":`{build} — beschreibbar; der Patch ändert {count} Bytes`,"preserve.bank.writableEdit":`{build} — beschreibbar; enthält {edit}`,"preserve.bank.writablePatchEdit":`{build} — beschreibbar; der Patch ändert {count} Bytes; enthält {edit}`,"preserve.choice.notRead":`die Sicherung hat die Slots noch nicht gelesen, daher kann kein Slot gewählt werden`,"preserve.choice.every":`jeder Slot, der ein Image enthält: {banks}`,"preserve.choice.everyBlocked":`die Auswahl „jeder Slot mit Image“ ist nicht möglich: {bank} kann nicht beschrieben werden — {reason}`,"preserve.choice.noImage":`kein Slot enthält ein Image, das der Durchlauf beschreiben kann`,"preserve.choice.nextStart":`{bank}, der Slot des nächsten Starts: {why}`,"preserve.choice.nextStartRefused":`der nächste Start erfolgt aus {bank} ({why}), und der Durchlauf kann ihn nicht beschreiben: {reason}`,"preserve.choice.everyUnknownStart":`jeder Slot, der ein Image enthält ({banks}): Aus welchem Slot der nächste Start erfolgt, ist unbekannt ({why})`,"preserve.choice.unknownStartRefused":`aus welchem Slot der nächste Start erfolgt, ist unbekannt ({why}), und {reason}; wählen Sie einen Slot mit Namen`,"preserve.choice.bank":`{bank}`,"preserve.choice.bankRefused":`{bank} kann nicht beschrieben werden: {reason}`,"preserve.choice.byName":`{banks}, der mit Namen gewählte Slot`,"preserve.choice.warnNotPatched":`Der nächste Start erfolgt aus {bank} ({why}), und diese Auswahl patcht ihn nicht: Nach dem Neustart führt die Kamera das eigene Image dieses Slots aus, daher hält das volle Auslesen an, bevor es irgendetwas liest. Die Wiederherstellung stellt trotzdem jeden beschriebenen Slot wieder her.`,"preserve.choice.warnUnknownStart":`Aus welchem Slot der nächste Start erfolgt, ist unbekannt ({why}). Erfolgt er aus einem Slot, den diese Auswahl nicht patcht, hält das volle Auslesen an, bevor es irgendetwas liest.`,"preserve.build.notKnown":`noch unbekannt`,"preserve.build.firmware":`Firmware {version}`,"preserve.stagedForm.plain":`so, wie die Kamera sie speichert (diese Kamera hält ihre Firmware unverschlüsselt)`,"preserve.stagedForm.oneKey":`in der Form, in der die Kamera sie speichert (verschlüsselt unter dem Schlüssel der Kamera)`,"preserve.stagedForm.twoKeys":`in der Form, in der die Kamera sie speichert (verschlüsselt unter den zwei Schlüsseln der Kamera)`,"preserve.restoreForm.verbatim":`jeder beschriebene Slot erhält genau die Bytes zurück, die die Sicherung aus ihm gelesen hat`,"preserve.restoreForm.factoryStaged":`jeder beschriebene Slot erhält seine Original-Firmware zurück, geschrieben in der Form, in der die Kamera sie speichert, sodass der Slot Byte für Byte so endet, wie die Sicherung ihn gelesen hat`,"preserve.restoreForm.none":`auf diesem Build nicht möglich: Keine Form der Original-Firmware besteht die eigene Prüfung der Kamera und wird zugleich wieder als die Original-Bytes gespeichert, daher endet der Durchlauf mit dem vollständigen Abbild und dem Patch noch an seinem Platz`,"preserve.drain.notPossible":`auf diesem Build nicht möglich: Die gepatchte Firmware kann nicht den gesamten Flash-Speicher lesen, daher hat der Durchlauf kein vollständiges Abbild zu liefern`,"preserve.drain.rotated":`die Kamera liefert ihn rotiert, und der Durchlauf bringt ihn wieder in die richtige Reihenfolge`,"preserve.drain.hazard":`der Patch vermeidet auf diesem Build ein Lesen, das die Kamera abstürzen lässt`,"preserve.drain.whole":`der gesamte 4-MB-Flash-Speicher in einem Durchgang, {size} Bytes auf einmal`,"preserve.drain.wholeNotes":`der gesamte 4-MB-Flash-Speicher in einem Durchgang, {size} Bytes auf einmal; {notes}`,"preserve.site.wholeFlash":`lässt den Lesebefehl der Kamera den gesamten 4-MB-Flash-Speicher erreichen, nicht nur die ersten 64 KB`,"preserve.site.countPast":`lässt die Leseposition über 64 KB hinaus zählen, damit ein Lesen nicht zum Anfang zurückspringt`,"preserve.site.keepPosition":`behält die vollständige Leseposition, wenn sie nach jedem Lesen weiterrückt`,"preserve.site.savePosition":`speichert die weitergerückte Leseposition vollständig`,"preserve.site.clearPosition":`setzt die vollständige Leseposition bei jedem Lesebeginn zurück, damit die Kamera nach dem vollen Auslesen weiterhin gelesen werden kann`,"preserve.site.modeTwoGuard":`lässt das volle Auslesen wie jedes andere Lesen beginnen (die Original-Firmware weist es ab)`,"preserve.site.modeTwoIndirection":`lässt das volle Auslesen am Anfang des Flash-Speichers beginnen (die Original-Firmware lässt es auf einen Wert zeigen, der die Kamera abstürzen lässt)`,"preserve.site.armTail":`entfernt einen Aufruf, der die Kamera auf diesem Build einfrieren lässt, wenn ein Lesen beginnt`,"preserve.site.other":`ändert eine Anweisung, die das volle Auslesen braucht`,"preserve.step.backup":`Sicherung`,"preserve.step.patch":`Patch`,"preserve.step.commit":`Schreiben`,"preserve.step.drain":`Volles Auslesen`,"preserve.step.restore":`Wiederherstellung`,"preserve.step.verify":`Prüfung`,"preserve.stepId.patch":`der Patch`,"preserve.stepId.commit":`der Schritt „Schreiben“`,"preserve.stepId.drain":`das volle Auslesen`,"preserve.stepId.restore":`die Wiederherstellung`,"preserve.stepId.verify":`die Prüfung`,"preserve.result.stoppedPlanned":`{label}: wie geplant angehalten — die Kamera ist aus {bank} gestartet, den dieser Durchlauf nicht gepatcht hat, daher wurde nichts gelesen.`,"preserve.result.noReason":`es wurde kein Grund festgehalten`,"preserve.result.stopped":`{label}: angehalten — {error}`,"preserve.result.writable.none":`kein Slot enthält Firmware, die der Durchlauf patchen kann`,"preserve.result.writable.one":`{banks} enthält Firmware, die der Durchlauf patchen kann`,"preserve.result.writable.many":`{banks} enthalten Firmware, die der Durchlauf patchen kann`,"preserve.result.backup":`{label}: Jeder Block, den ein normales Lesen erreicht, wurde gesichert; {writable}.`,"preserve.result.nextUnknown":`ein unbekannter Slot`,"preserve.result.backupNext":`{label}: Jeder Block, den ein normales Lesen erreicht, wurde gesichert; {writable}; Slot des nächsten Starts: {next}.`,"preserve.result.patch":`{label}: gebaut für {banks}.`,"preserve.result.patchNone":`{label}: Es wurde kein Patch gebaut: Kein Slot enthält Firmware, die der Durchlauf patchen kann.`,"preserve.result.patchCount":`{label}: gebaut für {banks}; in jedem ändern sich {count} Bytes.`,"preserve.result.commitOne":`{label}: {banks} mit dem Patch beschrieben, und die Kamera hat ihn angenommen.`,"preserve.result.commitMany":`{label}: {banks} mit dem Patch beschrieben, und die Kamera hat jeden angenommen.`,"preserve.result.drainNotRead":`{label}: nicht gelesen.`,"preserve.result.drain":`{label}: Der gesamte 4-MB-Flash-Speicher wurde gelesen; das vollständige Abbild hat sha256 {sha256}.`,"preserve.result.drainThrough":`{label}: Der gesamte 4-MB-Flash-Speicher wurde über {bank} gelesen; das vollständige Abbild hat sha256 {sha256}.`,"preserve.result.restore":`{label}: {banks} zurückgeschrieben.`,"preserve.result.restoreForm":`{label}: {banks} zurückgeschrieben, {form}.`,"preserve.result.verifyDone":`{label}: fertig.`,"preserve.result.verifyIdentical":`{label}: {blocks} Blöcke erneut gelesen, 0 Bytes abweichend — der Flash-Speicher der Kamera ist byteidentisch mit der Sicherung.`,"preserve.result.verifyDiffers":`{label}: {blocks} Blöcke erneut gelesen, {bytes} Bytes abweichend.`,"preserve.result.verifyDiffersUnread":{one:`{label}: {blocks} Blöcke erneut gelesen, {bytes} Bytes abweichend, {count} Block nicht lesbar.`,other:`{label}: {blocks} Blöcke erneut gelesen, {bytes} Bytes abweichend, {count} Blöcke nicht lesbar.`},"preserve.unpatchedStart.stop":`Vor dem vollen Auslesen angehalten: Die Kamera ist aus einem Slot gestartet, den dieser Durchlauf nicht gepatcht hat, daher wurde nichts gelesen.`,"preserve.unpatchedStart.next":`Als Nächstes: Die Wiederherstellung stellt jeden beschriebenen Slot wieder her. Das volle Auslesen wird nicht erneut versucht: Die Kamera würde aus demselben Slot starten.`,"preserve.done.title":`Fertig — Ihre Firmware ist gesichert`,"preserve.done.detail":`Das vollständige Abbild ist der gesamte ursprüngliche Flash-Speicher der Kamera, und die Kamera selbst ist wieder genau so, wie sie war.`,"preserve.done.titleNoImage":`Fertig — die Kamera ist wieder wie zuvor; es gibt kein vollständiges Abbild`,"preserve.done.detailNoImage":`Das volle Auslesen ist nicht gelaufen, daher hat dieser Durchlauf kein vollständiges Abbild des Flash-Speichers. Jeder beschriebene Slot wurde wiederhergestellt, und ein frisches Lesen der Blöcke, die ein normales Auslesen erreicht, stimmt mit der Sicherung überein. Für das vollständige Abbild starten Sie einen neuen Durchlauf mit einer Auswahl, die den Slot des nächsten Starts einschließt.`,"preserve.done.detailNoImageCount":`Das volle Auslesen ist nicht gelaufen, daher hat dieser Durchlauf kein vollständiges Abbild des Flash-Speichers. Jeder beschriebene Slot wurde wiederhergestellt, und ein frisches Lesen der {blocks} Blöcke, die ein normales Auslesen erreicht, stimmt mit der Sicherung überein. Für das vollständige Abbild starten Sie einen neuen Durchlauf mit einer Auswahl, die den Slot des nächsten Starts einschließt.`,"preserve.fail.spentReader":"der Fenster-Leser der Kamera hat pro Start ein begrenztes Budget, und diese Lesevorgänge kamen von einem erschöpften Leser — schalten Sie die Kamera aus und wieder ein (abziehen und wieder einstecken oder ihren Netzschalter verwenden) und führen Sie dann `preserve --resume <run-directory>` erneut aus. Signatur: {signature}","preserve.fail.spentReaderDerive":"der Fenster-Leser der Kamera hat pro Start ein begrenztes Budget, und diese Lesevorgänge kamen von einem erschöpften Leser — schalten Sie die Kamera aus und wieder ein (abziehen und wieder einstecken oder ihren Netzschalter verwenden) und führen Sie dann `preserve --resume <run-directory>` erneut aus. Signatur: {signature} — aus diesen Bytes lässt sich kein Werks-Klartext ableiten. Jeder Weg, ihn zu lesen, wurde versucht:\n  - {reasons}","preserve.fail.notInBackup":`die Sicherung enthält {bank} ({address}) nicht — die Standardfenster können ihn nicht liefern`,"preserve.fail.readsDisagree":`die zwei Lesevorgänge von {bank} stimmen nicht überein (sha256 {sha256} gegenüber {other}) — in eine Kamera, die den Slot, aus dem sie läuft, nicht zweimal hintereinander gleich liefern kann, sollte nicht geschrieben werden; die Aufnahme ist die Quelle der Wiederherstellung und die Grundlage für die Ableitung des Patches`,"preserve.fail.notFactory":`{bank} enthält nicht das Werks-Image so, wie die Verschlüsselung dieses Builds es speichert (der erwartete Image-Anfang passt nicht zur Aufnahme) — abgelehnt, bevor irgendetwas festgehalten, geschweige denn geschrieben wird`,"preserve.fail.ffSum":`die gepatchte Firmware besteht in der Form, in der die Kamera sie speichert, die eigene Prüfung dieses Builds nicht (ihre Summe muss {sum} sein) — abgelehnt, statt einen Slot zu senden, den die Kamera nach dem Löschen zurückweisen würde`,"preserve.fail.headChanged":`der Anfang von {bank} hat sich seit der Sicherung geändert (er enthält weder die ursprüngliche Aufnahme noch die gepatchten Bytes) — Schreiben über einen unbekannten Slot-Zustand abgelehnt; es wurde nichts geschrieben. Anfang als Hex: aktuell {live}, Aufnahme {capture}`,"preserve.fail.landedOne":`{banks} enthält bereits die gepatchten Bytes — der Commit ist bei einem früheren Versuch angekommen und darf nicht wiederholt werden. Setzen Sie beim Schritt des vollen Auslesens fort (--resume), der das gepatchte Image startet und von dort weitermacht.`,"preserve.fail.landed":`{banks} enthalten bereits die gepatchten Bytes — der Commit ist bei einem früheren Versuch angekommen und darf nicht wiederholt werden. Setzen Sie beim Schritt des vollen Auslesens fort (--resume), der das gepatchte Image startet und von dort weitermacht.`,"preserve.fail.drainRebootRefused":`der Neustart-Befehl des vollen Auslesens wurde vom Host ABGELEHNT, bevor er hinausging (ein SecurityError: eine Browser-Richtlinie oder ein Test-Schutz), daher führt die Kamera noch das Image aus, mit dem sie gestartet ist, nicht den per Commit geschriebenen Patch. Das volle Auslesen liest nur über das erweiterte Fenster des gepatchten Images, daher hält es an, bevor es irgendetwas öffnet; es wurde nichts gelesen. Führen Sie das volle Auslesen erneut dort aus, wo der Host den Neustart-Befehl durchlässt.`,"preserve.fail.shiftedRebootRefused":`das volle Auslesen kam um eine Seite verschoben zurück, und der Neustart, der einen weiteren Start auslöst, wurde vom Host ABGELEHNT, bevor er hinausging (ein SecurityError: eine Browser-Richtlinie oder ein Test-Schutz) — ein weiterer Versuch würde denselben verschobenen Start auslesen. Es wurde nichts behalten; führen Sie das volle Auslesen erneut dort aus, wo der Reset hinausgehen kann.`,"preserve.fail.verify":{one:`die Prüfung hat {count} abweichendes Byte über {read}/{total} Fenster gelesen — der Chip liest sich nicht byteidentisch mit der Sicherung zurück`,other:`die Prüfung hat {count} abweichende Byte über {read}/{total} Fenster gelesen — der Chip liest sich nicht byteidentisch mit der Sicherung zurück`},"preserve.fail.verifyIn":{one:`die Prüfung hat {count} abweichendes Byte über {read}/{total} Fenster gelesen (Stellen: {places}) — der Chip liest sich nicht byteidentisch mit der Sicherung zurück`,other:`die Prüfung hat {count} abweichende Byte über {read}/{total} Fenster gelesen (Stellen: {places}) — der Chip liest sich nicht byteidentisch mit der Sicherung zurück`},"preserve.fail.verifyShort":{one:`die Prüfung hat {count} abweichendes Byte über {read}/{total} Fenster gelesen (kurze Fenster: {short}) — der Chip liest sich nicht byteidentisch mit der Sicherung zurück`,other:`die Prüfung hat {count} abweichende Byte über {read}/{total} Fenster gelesen (kurze Fenster: {short}) — der Chip liest sich nicht byteidentisch mit der Sicherung zurück`},"preserve.fail.verifyInShort":{one:`die Prüfung hat {count} abweichendes Byte über {read}/{total} Fenster gelesen (Stellen: {places}) (kurze Fenster: {short}) — der Chip liest sich nicht byteidentisch mit der Sicherung zurück`,other:`die Prüfung hat {count} abweichende Byte über {read}/{total} Fenster gelesen (Stellen: {places}) (kurze Fenster: {short}) — der Chip liest sich nicht byteidentisch mit der Sicherung zurück`},"preserve.fail.verifyPlace":`{what} {address}`,"preserve.fail.bootConfigBlock":`der Boot-Konfigurationsblock`,"preserve.fail.dataBlock":`ein Datenblock`,"preserve.refused.secondRead":`sein zweites Lesen ist fehlgeschlagen ({error})`,"preserve.refused.readsDisagree":`seine zwei Lesevorgänge stimmen nicht überein (sha256 {sha256} gegenüber {other})`,"preserve.refused.erased":`er ist gelöscht`,"preserve.refused.watchdogMark":`sein Header-Wort bei +0x200 enthält {word}, die Markierung, die der Bootloader nach einem Watchdog-Reset früh in einem Start über einen Slot schreibt; der Bootloader nimmt diesen Slot nicht mehr an, und der Durchlauf hat dort kein Image zum Patchen`,"preserve.refused.noHeader":`er enthält keinen Image-Header bei +0x200`,"preserve.refused.otherBuild":`er enthält {image} ({id}), nicht den Build, den die Kamera ausführt ({camera})`,"preserve.refused.otherKey":`die Prüfung des Bootloaders lehnt ihn ab: Er ist unter einem anderen Schlüssel gespeichert als dem, unter dem der Bootloader dieser Kamera Slots prüft, und ein Schreiben über die Kamera würde ihn unter jenem Schlüssel speichern, daher könnte die Wiederherstellung seine genauen Bytes nicht zurückbringen`,"preserve.error.otherVersion":`die Kamera meldet Firmware {camera}, erwartet wird {version} — der Patch ist aus den Bytes eines Builds abgeleitet und darf nicht an einen anderen gesendet werden`,"preserve.refused.outsideLine":`Firmware {version} ist kein Build mit 0.x oder 1.x, und dieser Durchlauf deckt nur die Builds von 2014 und 2016 ab. Außer der Version wurde nichts gelesen. Lesen Sie diese Kamera stattdessen mit „Auslesen & entschlüsseln 4.x/Nano“: Dieser Tab liest den Flash-Speicher ohne Patch, jeden Block außer dem bei 0x14060000, den auf diesen Builds kein Lesefenster erreicht.`,"preserve.refused.preWidening":`Firmware {version} ist älter als der Erweiterungsweg, und der Durchlauf lehnt ab, statt über einen Slot zu schreiben, den er nicht zurücklesen kann. Auf dieser Generation weist die Kamera jeden Weg ab, das Lesen zu starten, das der Weg braucht (an 0.3.0.1 gemessen), ihr Lesebefehl erreicht den Anfang des Flash-Speichers nicht, und die Größe, die der Patch ändern würde, ist anders gespeichert. Sie hat auch kein Lesen, das ein normales Auslesen nutzen kann. Außer der Version wurde nichts gelesen.`,"preserve.image.unknown":`enthält ein unbekanntes Image (weder die Original-Firmware {version} noch eine Änderung daran, die Preserve kennt), daher patcht Preserve es nicht und stellt es nicht wieder her`,"preserve.image.frameRate":`enthält einen bekannten Bildraten-Build: die Original-Firmware {version} mit dem {hz}-Hz-Bildraten-Patch. Preserve patcht nur die Original-Firmware, nie ein gepatchtes Image, daher patcht es diesen Slot nicht und stellt ihn nicht wieder her`,"preserve.image.frameRateEarlier":`enthält einen bekannten Bildraten-Build: die Original-Firmware {version} mit einem früheren {hz}-Hz-Bildraten-Patch (erstellt, bevor die USB-Korrektur dazukam). Preserve patcht nur die Original-Firmware, nie ein gepatchtes Image, daher patcht es diesen Slot nicht und stellt ihn nicht wieder her`,"preserve.image.unknownWords":`er {what}. Um diesen Slot einzubeziehen, schreiben Sie zuerst das Original-Image in ihn zurück (zum Beispiel aus einer vollständigen Flash-Sicherung von vor der Änderung) und starten Sie dann einen neuen Durchlauf`,"preserve.image.frameRateWords":`er {what}. Um diesen Slot einzubeziehen, schreiben Sie zuerst das Original-Image in ihn zurück (zum Beispiel aus einer vollständigen Flash-Sicherung von vor dem Bildraten-Patch) und starten Sie dann einen neuen Durchlauf; der Bildraten-Patch lässt sich danach erneut auf das Original-Image anwenden`,"preserve.image.unknownRefusal":`{name} {what}. Der Durchlauf nimmt die Firmware, die er patcht, aus diesem Slot, daher hält er hier an, bevor irgendetwas geschrieben wird. Um diese Kamera zu sichern, schreiben Sie zuerst das Original-Image zurück in {bank} (zum Beispiel aus einer vollständigen Flash-Sicherung von vor der Änderung) und starten Sie dann einen neuen Durchlauf.`,"preserve.image.frameRateRefusal":`{name} {what}. Der Durchlauf nimmt die Firmware, die er patcht, aus diesem Slot, daher hält er hier an, bevor irgendetwas geschrieben wird. Um diese Kamera zu sichern, schreiben Sie zuerst das Original-Image zurück in {bank} (zum Beispiel aus einer vollständigen Flash-Sicherung von vor dem Bildraten-Patch) und starten Sie dann einen neuen Durchlauf; der Bildraten-Patch lässt sich danach erneut auf das Original-Image anwenden.`,"preserve.image.otherFirmware":`er enthält Firmware {image}, nicht die {camera}, die die Kamera ausführt`,"preserve.image.otherFirmwareRefusal":`{name} enthält Firmware {image}, nicht die {camera}, die die Kamera ausführt, daher hat dieser Durchlauf dort kein Image, das er patchen kann, und lehnt ab, statt darüber zu schreiben.`,"preserve.image.noImage":`daraus lässt sich kein Image ableiten, das der Durchlauf patchen kann ({error})`,"preserve.gate.runDone":`dieser Durchlauf ist abgeschlossen — jeder Schritt ist fertig (Durchlauf {run})`,"preserve.gate.stepDone":`{step} ist in diesem Durchlauf bereits erledigt (fertig {finished}) — Fortsetzen macht bei {next} weiter`,"preserve.gate.stepDoneUnknownTime":`{step} ist in diesem Durchlauf bereits erledigt (Zeitpunkt unbekannt) — Fortsetzen macht bei {next} weiter`,"preserve.gate.backupRerun":`die Sicherung kann nicht erneut laufen: Dieser Durchlauf hat {steps} bereits abgeschlossen, und sein nächster Schritt ist {next} — verwenden Sie --resume`,"preserve.gate.powerCycle":`der vorige Sicherungsversuch ist fehlgeschlagen, und die Kamera muss AUS- UND WIEDER EINGESCHALTET werden, bevor dieser Schritt erneut läuft — ein erneuter Versuch im selben Start kann veraltete oder leere Bytes lesen (gemessen: Eine wiederholte Sicherung las das Startwort des Bootloaders anstelle des Boot-Konfigurationsdatensatzes). Schalten Sie die Kamera aus und wieder ein (abziehen und wieder einstecken oder ihren Netzschalter verwenden), führen Sie dann die Sicherung erneut aus und bestätigen Sie das Aus- und Einschalten, wenn Sie gefragt werden: Der Durchlauf kann es nicht selbst sehen. Der festgehaltene Fehler: {error}`,"preserve.gate.noErrorText":`(kein Fehlertext)`,"preserve.gate.patchAfterBackup":`{step} läuft nach der Sicherung: Der Durchlauf liest jeden Bereich, den der Standardplan lesen kann, und speichert ihn dauerhaft, BEVOR irgendetwas anderes geschieht — diese Sicherung ist die einzige Kopie dieser Kamera. Führen Sie zuerst den Sicherungsschritt aus.`,"preserve.gate.commitAfterBackup":`{step} läuft nach der Sicherung (siehe den Patch-Schritt)`,"preserve.gate.commitAfterPatch":`{step} läuft nach dem Patch-Schritt, der festhält, was er überträgt`,"preserve.gate.commitNeedsPatch":`{step} braucht den Patch von {banks}, und der Patch-Schritt hat keinen festgehalten — führen Sie den Patch-Schritt erneut aus`,"preserve.gate.commitFiles":`{step} braucht die Sicherungsdateien im Durchlaufverzeichnis, und sie fehlen: {files} — ohne sie hat ein Commit keine Quelle für die Wiederherstellung, daher lehnt er ab`,"preserve.gate.drainNoCommit":`{step} liest den GEPATCHTEN Chip über das erweiterte Fenster, und dieser Durchlauf hat keinen abgeschlossenen Commit — auf einer Kamera im Originalzustand würde das volle Auslesen hängen bleiben. Führen Sie zuerst den Commit aus (oder setzen Sie dort fort), oder springen Sie ausdrücklich (allowJump), wenn der Commit ohne seinen Checkpoint angekommen ist.`,"preserve.gate.drainRefused":`der Schritt des vollen Auslesens lehnt auf {build} ab: {note}`,"preserve.gate.detectedBuild":`dem erkannten Build`,"preserve.gate.drainHazard":`der Schritt des vollen Auslesens lehnt auf {build} ab: Das volle Auslesen auf der ungepatchten Firmware dieses Builds zu starten, lässt die Kamera abstürzen (sie liest von einem Wert, der keine Flash-Adresse ist; auf dem Emulator gemessen: 32 KB geliefert, dann ein Fehler der Kamera). Die Änderung, die das Lesen sicher macht, liegt bei {sites}, und sie gehört nicht zu den Änderungen, die dieser Durchlauf für {bank} festgehalten hat — führen Sie den Patch-Schritt aus (und schließen Sie das Schreiben ab), bevor Sie voll auslesen.`,"preserve.gate.drainFiles":`{step} braucht {files} (das gelieferte Abbild wird mit der Aufnahme jedes beschriebenen Slots nachbearbeitet), und das fehlt im Durchlaufverzeichnis`,"preserve.gate.restoreNoCommit":`{step} schreibt die Original-Slots über den Patch zurück, und dieser Durchlauf hat keinen abgeschlossenen Commit — es gibt nichts, was sie rückgängig machen könnte. Führen Sie zuerst den Commit aus (oder setzen Sie dort fort), oder springen Sie ausdrücklich (allowJump), um eine bereits gepatchte Kamera wiederherzustellen.`,"preserve.gate.restoreNeedsPatch":`{step} braucht die Patch-Zusammenfassung jedes beschriebenen Slots (für die übertragene Länge) — führen Sie zuerst den Patch-Schritt aus`,"preserve.gate.restoreNoForm":`der Wiederherstellungsschritt lehnt auf {build} ab: Keine Form der Original-Firmware besteht die eigene Prüfung der Kamera und wird zugleich wieder als die Original-Bytes gespeichert — die Prüfsumme der Original-Firmware ist 0xB7AB9D17 (gemessen), nicht das 0xFFFF, das die Kamera verlangt. Dieser Durchlauf endet mit dem vollständigen Abbild in der Hand und dem Patch an seinem Platz; der ursprüngliche Inhalt kann nur mit einem Programmiergerät für den ganzen Flash-Speicher zurückgebracht werden.`,"preserve.gate.restoreFiles":`{step} braucht {files} (das Original jedes beschriebenen Slots, aus dem Sicherungsschritt), und das fehlt im Durchlaufverzeichnis`,"preserve.gate.verifyNoRestore":`{step} vergleicht einen frischen Start mit der Sicherung, und dieser Durchlauf hat keine abgeschlossene Wiederherstellung — ein gepatchter Slot würde als Abweichung erscheinen. Führen Sie zuerst die Wiederherstellung aus (oder setzen Sie dort fort), oder springen Sie ausdrücklich (allowJump), wenn die Wiederherstellung ohne ihren Checkpoint angekommen ist.`,"preserve.gate.verifyNeedsBackup":`{step} braucht {file} (die Referenz für den Vergleich), und die Datei fehlt im Durchlaufverzeichnis`,"preserve.gate.needsBanks":`{step} braucht die Slots, die der Sicherungsschritt gelesen hat, und der Zustand enthält keine`,"preserve.gate.noBanks":`für diesen Durchlauf sind keine Slots gewählt: {what}`,"preserve.gate.bankRefused":`{bank} kann nicht beschrieben werden: {why}`,"preserve.gate.recoveryOnly":`der Patch dieses Builds startet nur aus Recovery-Slot R: {note} — der Durchlauf würde {bank} beschreiben, wo der Bootloader ihn nie ausführt`,"slots.image.tooSmall":`die Datei ist zu klein für einen Image-Header`,"slots.image.notWordSized":`die Image-Größe muss ein Vielfaches von 4 sein (erhalten: {size} B)`,"slots.image.tooLong":`das Image ist {size} B groß; der Bootloader lehnt jedes header.length >= {limit} ab, daher würde es nie starten`,"slots.image.noHeader":`kein Image-Header bei {at} (Magic {magic}, erwartet {expected}) — das muss ein entschlüsseltes Seek-Firmware-Image sein, kein verschlüsselter Slot und kein Flash-Abbild`,"slots.image.stackOutside":`der anfängliche Stack-Pointer {address} liegt nicht im LPC43xx-SRAM — das sieht nicht entschlüsselt aus`,"slots.image.stackUnaligned":`der anfängliche Stack-Pointer {address} ist nicht an einer Wortgrenze ausgerichtet`,"slots.image.notThumb":`der Reset-Vektor {address} ist keine Thumb-Adresse`,"slots.image.noKeyPair":`der Name dieser Datei trägt nicht ihr Schlüsselpaar, und weder das Paar dieser Kamera noch ein dekodiertes Anwendungspaar kommt genau einmal im Image vor, daher lässt sich nicht sagen, für welche Schlüssel das Image gebaut wurde. Entschlüsselte Dateien werden nach den Schlüsseln benannt, die sie enthalten.`,"slots.image.keyMismatch":`der Dateiname gibt Schlüssel A {keyA} und Schlüssel B {keyB} an, aber {mismatch}. Beide Schlüssel müssen vorhanden sein, jeder genau einmal.`,"slots.image.keyInHeader":`dieses Image hat einen Schlüssel bei {at}, innerhalb des Klartext-Header-Fensters — Patchen abgelehnt`,"slots.image.keysOverlap":`Schlüssel A und Schlüssel B aus dem Dateinamen ergeben überlappende Bytes bei {at} und {other} — es müssen zwei verschiedene 16-Byte-Werte sein`,"slots.image.retargetLost":`nach dem Umstellen auf diese Kamera enthält das Image das Schlüsselpaar dieser Kamera nicht genau einmal — abgelehnt, denn für spätere Upgrades dieser Nutzdaten könnte der Bootloader keinen Schlüssel finden`,"slots.image.noStageKey":`das Image enthält kein Schlüsselpaar der Linie von 2016, daher gibt es keinen Übertragungsschlüssel, um es zu kodieren`,"slots.image.ffSumNoKeys":`dieses Image hat die 16-Hz-FF-Wortsumme 0xFFFF, enthält aber nicht das 1.3.0.8-FF-Schlüsselpaar (beide Hälften, je einmal), daher lässt sich seine übertragene Form nicht bauen. Es wurde nichts geschrieben.`,"slots.image.ffNotPlain":`das ist das 1.3.0.8-FF-Image (16 Hz), das in seiner eigenen Form mit Schlüssel A übertragen wird (ff-form.ts), nicht als Klartext-Image. Es wurde nichts geschrieben.`,"slots.plan.otherFirmware":`der Plan wurde für Firmware {firmware} gebaut, aber die Analyse liest {version}. Der Plan ist veraltet; bauen Sie ihn neu. Es wurde nichts geschrieben.`,"slots.plan.otherFirmwareUnknown":`der Plan wurde für Firmware unbekannter Version gebaut, aber die Analyse liest {version}. Der Plan ist veraltet; bauen Sie ihn neu. Es wurde nichts geschrieben.`,"slots.plan.otherCamera":`der Plan wurde für die Kamera {planSerial} gebaut, aber die Analyse liest {serial}. Er wird hier nicht geschrieben. Es wurde nichts geschrieben.`,"slots.plan.cameraUnknownSerial":`mit unbekannter Seriennummer`,"slots.plan.unknownSerial":`eine unbekannte Seriennummer`,"slots.plan.otherAddress":`der Plan zielt auf {address}, aber {name} dieses Builds liegt bei {at}`,"slots.plan.notRead":`die Analyse liest {name} nicht mehr. Es wurde nichts geschrieben.`,"slots.plan.edited":`die Prüfsumme des Plans passt nicht zu seinen Nutzdaten, der Plan wurde also verändert. Es wurde nichts geschrieben.`,"slots.plan.outsideBank":`die Nutzdaten sind {size} B groß und passen nicht in {name}`,"slots.plan.riskAck":`{risk}. Das Schreiben braucht acknowledgeRisk: true. Es wurde nichts gesendet.`,"slots.plan.plainStaging":`diese Kamera kann von hier aus kein unverschlüsselt übertragenes Image annehmen: {reason}. Es wurde nichts geschrieben.`,"slots.plan.noKeyTable":`die Analyse nennt die Schlüsseltabelle des Bootloaders dieser Kamera nicht, daher kann das Image nicht auf sie umgestellt werden`,"slots.commit.unread":`der Commit-Status konnte nach CompleteMemoryUpgrade nicht gelesen werden, daher ist {name} möglicherweise teilweise beschrieben. Lesen Sie die Slots erneut, bevor Sie irgendetwas anderes tun, und bewahren Sie Ihre Sicherung auf.`,"slots.commit.refused":`die Kamera hat das Schreiben in {name} beim Commit mit {status} abgelehnt: {cause}. Es wurde nichts geschrieben; der Slot ist unverändert. Lesen Sie die Slots erneut, bevor Sie irgendetwas anderes tun.`,"slots.commit.eraseStage":`CompleteMemoryUpgrade hat für {name} {status} ({cause}) zurückgegeben: Es wurde nichts programmiert, aber das Löschen hat womöglich begonnen, daher ist der Slot möglicherweise teilweise gelöscht. Lesen Sie die Slots erneut, bevor Sie irgendetwas anderes tun, und bewahren Sie Ihre Sicherung auf.`,"slots.commit.partial":`CompleteMemoryUpgrade hat {status} ({cause}) zurückgegeben — {name} ist möglicherweise teilweise beschrieben. Lesen Sie die Slots erneut, bevor Sie irgendetwas anderes tun, und bewahren Sie Ihre Sicherung auf.`,"slots.commit.stagingStatus":`die Kamera hat beim Übertragen von {name} bei Offset {offset} {status} gemeldet — vor CompleteMemoryUpgrade abgebrochen, daher wurde nichts in den Flash-Speicher geschrieben`,"commit.cause.badChecksum":`die Übertragungsprüfsumme passte nicht zu den übertragenen Bytes`,"commit.cause.unsupported":`das Image ließ sich unter den Schlüsseln der Kamera nicht entschlüsseln, oder der Datentyp wird abgelehnt`,"commit.cause.acceptance":`das Image wurde von seiner Annahmeprüfung abgelehnt, bevor irgendetwas gelöscht wurde (die Prüfung hängt vom Build ab)`,"commit.cause.notArmed":`es war kein Slot-Upgrade geöffnet`,"commit.cause.eraseFailed":`die Löschphase ist fehlgeschlagen`,"commit.cause.programFailed":`die Programmierphase ist fehlgeschlagen`,"commit.cause.verifyFailed":`die Prüfphase ist fehlgeschlagen`,"commit.cause.unknown":`ein hier unbekannter Status`,"copy.refused.ontoItself":`{name} wird nicht auf sich selbst kopiert. Es wurde nichts geschrieben.`,"copy.refused.source":`{why}. Es wurde nichts geschrieben.`,"copy.refused.noPlain":`{name} hat kein entschlüsseltes Image zum Kopieren. Es wurde nichts geschrieben.`,"restore.refused.zipUnreadable":`{file} ist eine ZIP-Datei, die hier nicht gelesen werden kann ({error}). Es wurde nichts geschrieben.`,"restore.refused.noWholeFlash":`{file} enthält keinen vollständigen Flash-Speicher. Eine ZIP-Datei wird angenommen, wenn sie eine Preserve-Durchlaufdatei mit {preserve} ist (sobald ihr Schritt des vollen Auslesens gelaufen ist), eine ZIP-Datei von „Auslesen & entschlüsseln 4.x/Nano“ ({dump}) oder eine von „Alle Selektoren auslesen“ ({selectors}); diese ZIP-Datei enthält: {names}. Es wurde nichts geschrieben.`,"restore.refused.noWholeFlashPatched":`{file} enthält keinen vollständigen Flash-Speicher. Eine ZIP-Datei wird angenommen, wenn sie eine Preserve-Durchlaufdatei mit {preserve} ist (sobald ihr Schritt des vollen Auslesens gelaufen ist), eine ZIP-Datei von „Auslesen & entschlüsseln 4.x/Nano“ ({dump}) oder eine von „Alle Selektoren auslesen“ ({selectors}); diese ZIP-Datei enthält: {names}. Die Datei {patched} darin ist der Flash-Speicher mit dem vorübergehenden Patch des Durchlaufs, daher wird sie nicht angenommen. Es wurde nichts geschrieben.`,"restore.refused.zipEmpty":`nichts`,"restore.refused.wrongSize":`eine vollständige Flash-Sicherung ist {full} B groß (4 MB, der ganze Chip, wie J-Link ihn liest); {file} ist {size} B groß. Es wurde nichts geschrieben.`,"restore.refused.noBank":`der Plan dieses Builds hat keinen {bank}. Es wurde nichts geschrieben.`,"restore.refused.outsideFlash":`{name} liegt nicht innerhalb eines 4-MB-Flash-Speichers. Es wurde nichts geschrieben.`,"restore.refused.gap":`{where} wurde von dem Auslesen, aus dem {file} stammt, nicht gelesen: Laut seiner manifest.json ist {address} eine Lücke. Es gibt kein Image zum Wiederherstellen. Es wurde nichts geschrieben.`,"restore.refused.gapReason":`{where} wurde von dem Auslesen, aus dem {file} stammt, nicht gelesen: Laut seiner manifest.json ist {address} eine Lücke ({gap}). Es gibt kein Image zum Wiederherstellen. Es wurde nichts geschrieben.`,"restore.refused.gapFill":`{where} wurde von dem Auslesen, aus dem {file} stammt, nicht gelesen: Laut seiner manifest.json ist {address} eine Lücke, gefüllt mit {fill}. Es gibt kein Image zum Wiederherstellen. Es wurde nichts geschrieben.`,"restore.refused.gapReasonFill":`{where} wurde von dem Auslesen, aus dem {file} stammt, nicht gelesen: Laut seiner manifest.json ist {address} eine Lücke ({gap}), gefüllt mit {fill}. Es gibt kein Image zum Wiederherstellen. Es wurde nichts geschrieben.`,"restore.refused.empty":`{where} ist leer: Jedes Byte ist 0xFF. Ein Schreibvorgang programmiert ein Image und kann einen Slot nicht gelöscht zurücklassen, daher kann ein leerer Slot nicht durch einen Schreibvorgang wiederhergestellt werden. Es wurde nichts geschrieben.`,"restore.refused.fill":`{where} ist in jedem Byte {fill}, die Füllung, die das Auslesen dort schreibt, wo es nichts gelesen hat: Das Auslesen hat diesen Slot nicht gelesen. Es gibt kein Image zum Wiederherstellen. Es wurde nichts geschrieben.`,"restore.refused.notDecrypted":`{where} kann aus dieser Datei nicht wiederhergestellt werden: {why}. Es wurde nichts geschrieben.`,"support.noWriteArm":`dieser Build hat keine Schreib-Öffnung für den Slot`,"support.noStagingEmpty":`dieser Build hat keine Übertragungsform, daher wird ein leerer Slot nicht beschrieben`,"support.buildUnknown":`der Build ist unbekannt`,"support.unverifiedStaging":`dieser Build liegt auf der gesperrten Linie 0.x/1.x, ist aber keiner der Builds, an denen die Patch-Tabellen des Preserve-Durchlaufs gemessen wurden (0.8.0.0 .. 1.3.0.8 und 1.0.3.0 / 1.0.3.2), daher ist die Übertragungsform seiner Slots unbekannt, und es wird nichts geschrieben`,"support.unknownFamily":`die Familie der Kamera ist nicht bekannt und damit auch nicht der Schlüssel, unter dem ihre Slots geschrieben werden; eine Kamera nimmt einen unter dem falschen Schlüssel geschriebenen Slot an und startet dann nicht daraus. Lesen Sie diese Kamera aus und entschlüsseln Sie sie, bestimmen Sie sie anhand des Flash-Abbilds und nennen Sie dann ihre Familie mit --family.`,"support.noReadCommand":`Firmware älter als 0.8.0.0 hat keinen Lese-Handler für GetFeaturedFirmwareData, den Befehl, mit dem ein Auslesen den Flash-Speicher liest. Auf 0.7.0.7 und 0.7.0.8 steht er in der RPC-Methodentabelle bei 0x4F, ist aber nur als Setter (Schreib-Handler) registriert, daher kann das Control-IN-Lesen, das ein Auslesen sendet, nicht zugestellt werden (der Preserve-Durchlauf liest diese beiden Builds stattdessen über Wire-ID 0x58, GetFeaturedData); vor 0.7.0.7 ist Wire-ID 0x4F UploadFirmwareRowSize, und auf 0.3.0.1 ist Wire-ID 0x52 — die, mit der ein Auslesen öffnet — EnterBootloaderMode statt BeginFirmwareUpgrade: Die Kamera bleibt in ihrer Anwendung, aber jedes Öffnen setzt ein Flash-Ziel und öffnet die Firmware-Upgrade-Phase dieses Builds (GetErrorCode liest danach 0x00400000), was kein Lesefenster ist. Aus den eigenen Methodentabellen der Images gewonnen, beide Handler-Spalten; siehe test/firmware/facts.json.`,"support.noWritePath":`diese Builds nehmen neue Firmware über eine ältere Upgrade-Abfolge an, die dieses Toolkit nicht sendet, und ihre Slots wurden nie kartiert, daher wird nichts geschrieben.`,"support.versionUnread":`die Firmware-Version konnte nicht gelesen werden, daher sind der Build, seine Slots und deren Übertragungsform unbekannt; darauf wird nichts gelesen oder geschrieben`,"support.versionNotDotted":`die Firmware-Version „{version}“ ist keine Version mit Punkten, daher sind der Build, seine Slots und deren Übertragungsform unbekannt; darauf wird nichts gelesen oder geschrieben`,"support.olderThanFirst":`Firmware {version} ist älter als {first}: Ihre RPC-Tabelle hat keinen Lese-Handler für GetFeaturedFirmwareData, den Befehl, den ein Slot-Lesen sendet, daher wird an sie weder ein Lese- noch ein Schreibbefehl gesendet (early-compact hat die Belege)`,"support.modernOnLocked":`die Familie modern-4x deckt 2.x, 4.x, 10.x, 42.x und 44.x ab; {version} liegt auf der gesperrten Linie 0.x / 1.x, die legacy-auth oder compact-2016 braucht`,"support.lockedOnModern":`die Familie legacy-auth deckt die gesperrte Linie 0.x / 1.x ab; {version} liegt auf der modernen Linie, die modern-4x braucht`,"support.notCompactPro":`die Familie compact-2016 deckt die Linie 1.0.3.x der Compact PRO ab; {version} liegt nicht darauf`,"support.earlyCompact":`die Familie early-compact deckt nur die Builds älter als {first} ab, und {version} wird über legacy-auth gelesen`,"support.generic":`die Familie der Kamera ist nicht erkannt (Familie generic), daher sind Slot-Layout und Übertragungsform unbekannt; erkennen Sie die Kamera, bevor ein Slot gelesen oder geschrieben wird`,"support.noPlan":`für die Familie {family} gibt es keinen Slot-Plan: Ihr Slot-Layout und ihre Übertragungsform sind nicht bekannt`,"support.noArmPlain":`die Tabelle dieses Builds öffnet Modus {mode} bei {address} nicht auf dem einfachen Kanal`,"support.noArmToken":`die Tabelle dieses Builds öffnet Modus {mode} bei {address} nicht auf dem Token-Kanal`,"support.windowElsewhere":`das Preserve-Slot-Fenster für {bank} liegt bei {at}, nicht bei {address}`,"support.noDumpWindow":`die BeginFirmwareUpgrade-Tabelle dieses Builds hat kein Fenster bei {address} für {bank}`,"support.capabilityRefused":`{family} unterstützt {capability} nicht: {reason}`,"support.capability.dump":`das Auslesen`,"support.capability.allSelectors":`„Alle Selektoren auslesen“`,"support.capability.decrypt":`das Entschlüsseln`,"support.capability.deviceInfo":`das vollständige Lesen im Tab „Info“`,"support.capability.flash":`das Beschreiben von Slots`,"slots.unread.noWindow":`{name} bei {address} ist auf diesem Build nicht lesbar: Seine Selektortabelle hat dort kein Fenster, daher wurde dafür nichts geöffnet`,"slots.unread.missing":`{name} fehlt in der Analyse der Kamera`,"slots.unread.notRead":`{name} wurde nicht gelesen`,"slots.refused.nothingWritten":`{refusal}. Es wurde nichts geschrieben.`,"slots.refused.versionUnknown":`die Analyse sagt nicht, welche Firmware die Kamera ausführt, und die Slot-Befehle bedeuten auf verschiedenen Builds Verschiedenes. Lesen Sie die Geräteinformationen erneut.`,"slots.refused.versionUnknownWrite":`die Analyse sagt nicht, welche Firmware die Kamera ausführt. Es wurde nichts geschrieben.`,"slots.refused.emptyInput":`die Eingabe ist leer`,"slots.refused.emptyNotWritable":`{name} ist leer und kann auf diesem Build nicht beschrieben werden: {reason}`,"slots.refused.noRaw":`{name} kann auf diesem Build keine Rohdaten annehmen: {reason}`,"slots.refused.noPlain":`{name} kann auf diesem Build kein entschlüsseltes Image annehmen: {reason}`,"slots.refused.noStaging":`{name} hat auf diesem Build keine Übertragungsform, daher kann kein Image dafür kodiert werden`,"slots.refused.rawTooLong":`{size} B ist länger als {name} ({bankSize} B)`,"slots.refused.imageTooLong":`das Image ist {size} B groß, länger als {name} ({bankSize} B)`,"preserve.routeNote.recoveryOnly":`der Bootloader von 2014 nimmt die Prüfsumme dieses Builds in Slot A oder B nicht an und startet Recovery-Slot R (0x14070000), ohne ihn zu prüfen, daher wird der Patch in Recovery-Slot R geschrieben und nirgendwo sonst`,"preserve.refused.recoveryOnly":`dieser Build läuft nur aus Recovery-Slot R: {note}`,"decryptFile.wrongSize":`ein Firmware-Slot ist {size} B groß ({kib} KB); diese Datei ist {count} B groß`,"decryptFile.erasedBank":`leer, nichts zu entschlüsseln: alle {size} B lesen sich als 0xFF (ein gelöschter Slot)`,"decryptFile.erasedHeader":`gelöscht: Das Header-Fenster ist vollständig 0xFF, daher enthält der Slot kein Image; es wird nichts entschlüsselt`,"decryptFile.noHeader":`kein Image-Header (Magic {magic}), daher gibt es kein Image zum Entschlüsseln`,"decryptFile.lengthOutOfRange":`header.length {length} liegt außerhalb des gültigen Bereichs; kein Image zum Entschlüsseln`,"decryptFile.ffKeyB":`{size} B unter Schlüssel B von FF 1.3.0.8 entschlüsselt: Das Image ist gespeichert als das Image XOR den Schlüsselstrom seines Schlüsselblocks 1, Header-Fenster unverändert`,"decryptFile.notRecovered":`Schlüssel nicht gewonnen: Das Image entschlüsselt sich zu einem Reset-Vektor, der kein Cortex-M-Einsprungpunkt ist (Schlüssel {check}); es wird nichts entschlüsselt`,"decryptFile.storedPlain":`im Klartext gespeichert: Der Slot enthält das Image so, wie es läuft (die Klartext-Kette von 2014, ein Identitäts-Schlüsselstrom), daher gibt es keinen Schlüssel, und das entschlüsselte Image ist das Image selbst`,"decryptFile.decrypted":`{size} B unter dem aus diesem Slot gewonnenen Schlüssel entschlüsselt ({check})`,"decryptFile.decryptedNamed":`{size} B unter dem aus diesem Slot gewonnenen Schlüssel entschlüsselt ({check}; es ist {key})`,"read.reason.shortRead":`zu kurz gelesen ({size} B)`,"read.reason.noParse":`Image-Header konnte nicht ausgewertet werden`,"read.reason.noHeader":`kein Image-Header (Magic {magic})`,"read.reason.lengthOutOfRange":`header.length {length} liegt außerhalb des gültigen Bereichs`,"read.reason.stopped":`Lesen des Slots bei {count}/{size} B angehalten`,"read.reason.notInPlan":`auf Firmware {version} nicht lesbar: Ihr Plan ({table}) hat kein Fenster bei {address}, daher wurde dafür nichts geöffnet`,"read.reason.notInPlanUnknown":`auf Firmware unbekannter Version nicht lesbar: Ihr Plan ({table}) hat kein Fenster bei {address}, daher wurde dafür nichts geöffnet`,"read.reason.staleDescriptor":`das Fenster hat die Bytes eines veralteten Leser-Deskriptors geliefert — Wort 0 {word} mit Reset {hex} ist die Vektortabelle von 0x14000000, nicht der Inhalt dieses Slots, daher wurde daraus nichts ausgewertet: {remedy}`,"read.reason.spentReader":`die Slots der Kamera konnten nicht gelesen werden — {remedy}`,"read.spentRemedy":`der Fenster-Leser ist für diesen Start womöglich erschöpft; schalten Sie die Kamera aus und wieder ein und versuchen Sie es erneut`,"checkKey.unnamed.wordNotRead":`das Aktiv-Slot-Wort der Kamera (fw info roots, Selektor 10) konnte nicht gelesen werden`,"checkKey.unnamed.wordNamesNoBank":`das Aktiv-Slot-Wort der Kamera ist {word}, was keinen Slot bezeichnet`,"checkKey.unnamed.cfg0NotRead":`das Boot-Konfigurationswort wurde nicht gelesen, daher ist nicht bekannt, ob der Bootloader {bank} geprüft hat, bevor er ihn angesprungen hat`,"checkKey.unnamed.noZeroSum":`die Kamera meldet, dass sie aus {bank} gestartet ist, aber {bank} entschlüsselt sich bei diesem Lesen nicht zu einer Wortsumme von null`,"checkKey.unnamed.noZeroSumUnchecked":`die Kamera meldet, dass sie aus {bank} gestartet ist, den das Boot-Konfigurationswort {word} an die letzte Stelle setzt, daher hat der Bootloader ihn ohne seine Prüfung angesprungen, aber {bank} entschlüsselt sich bei diesem Lesen nicht zu einer Wortsumme von null`,"report.detected":`{family} (Bewertung {score} nach dem Lesen, anhand der Hinweise unten)`,"report.detectedAmbiguous":`{family} (Bewertung {score} nach dem Lesen, anhand der Hinweise unten; nicht eindeutig)`,"report.cell.yes":`ja`,"report.cell.no":`nein`,"report.cell.notApplicable":`k. A.`,"report.cell.unknown":`unbekannt`,"report.cell.recoveryOnly":`nur Recovery`,"report.keyRow.whitening":`Whitening-K`,"report.keyRow.store":`Speicherschlüssel`,"report.keyRow.check":`Prüfschlüssel`,"report.keyRow.table":`Schlüsseltabelle`,"report.keyRow.keys":`Schlüssel`,"report.keyRow.a":`Schlüssel A`,"report.keyRow.b":`Schlüssel B`,"report.keyRow.tableAt":`Tabelle bei`,"report.key.notIdentified":`(nicht erkannt)`,"report.key.candidates":{one:`{count} Kandidat, nicht bestätigt`,other:`{count} Kandidaten, keiner bestätigt`},"report.key.tableAt":`{offset} im Bootloader-Block, an einem Slot bestätigt`,"report.key.plainChain":`keiner nötig: Die Slots sind als Klartext-Firmware gespeichert, daher wird ein Slot so gelesen und geschrieben, wie er ist`,"report.key.tableRefused2016":`nicht gelesen — der Bootloader-Block (0x14000000) wird auf dieser Linie auf jedem Kanal abgelehnt`,"report.checkKey.named":`{key} {hex}{pair}`,"report.checkKey.namedFrom":`{key} {hex}{pair}, benannt anhand von {bank}, dem Slot, aus dem die Kamera laut eigener Meldung nach der Prüfung des Bootloaders gestartet ist`,"report.checkKey.inferredFrom":`{key} {hex}{pair}, erschlossen aus {bank}, dem Slot, aus dem die Kamera laut eigener Meldung gestartet ist: Der Bootloader springt diesen Slot ohne seine Prüfung an und führt ihn unter dem Schlüssel aus, unter dem er die anderen Slots prüft`,"report.checkKey.pair":` (Block 1 von {pair})`,"keyPair.cp103":`dem 9-Hz-Paar der Compact PRO 1.0.3.x`,"keyPair.cp1032ff":`dem FF-Paar der Compact PRO 1.0.3.x`,"report.checkKey.notNamed":`nicht benannt — {why}`,"report.checkKey.couldNotName":`das Lesen konnte ihn nicht benennen`,"report.storeKey.checkKeyUnnamed":`der Schlüssel, unter dem ihr Bootloader einen Slot prüft (bei diesem Lesen nicht benannt): Die Anwendung speichert jeden Slot, den sie schreibt, unter diesem Schlüssel`,"report.storeKey.checkKey":`{key}: Die Anwendung speichert jeden Slot, den sie schreibt, unter dem Schlüssel, den ihr Bootloader prüft`,"report.storeKey.unknown":`unbekannt — der Bootloader-Block mit dem Platz für den Geräteschlüssel wurde nicht gelesen`,"report.storeKey.keyBUnidentified":`Schlüssel B (kein Geräteschlüssel programmiert; Schlüssel B selbst nicht erkannt)`,"report.storeKey.keyB":`Schlüssel B (kein Geräteschlüssel programmiert)`,"report.staged.plain":`unverschlüsselt übertragen (das Image, wie es ist, ohne Schlüssel)`,"report.staged.slotKeystream":`unter dem eigenen Schlüsselblock 0 seines Images übertragen`,"report.staged.keyA":`unter Schlüsseln übertragen, die vom gestarteten Slot und der laufenden Anwendung abgeleitet sind`,"report.staged.ffVendor":`so übertragen, wie die Hersteller-App das 16-Hz-FF-Image überträgt (das Image XOR seinen eigenen Schlüsselblock 0), von der Kamera unter Schlüssel B gespeichert`,"progress.backupBlock":`Sicherung: Block {address}`,"progress.backupDone":`Sicherung: jeder Block gelesen`,"progress.checkBlock":`Prüfung: Block {address}`,"progress.checkDone":`Prüfung: jeder Block gelesen`,"progress.writingBank":`{bank} wird geschrieben`,"progress.restoringBank":`{bank} wird wiederhergestellt`,"progress.staged":`{label}: {done}/{total} B übertragen`,"progress.wholeFlash":`Volles Auslesen: {got}/{total} B`,"progress.readWindow":`lese {address} subcmd={subcmd} ...`,"progress.readWindowAuth":`lese {address} subcmd={subcmd} (auth) ...`,"progress.windowsRead":`Fertig — {ok}/{total} Fenster gelesen.`,"progress.readingBank":`{bank} wird gelesen ...`,"progress.analysing":`Wird ausgewertet ...`,"progress.probeSelector":`teste Selektor {selector} ...`,"progress.selectorsArmed":`Fertig — {armed}/{span} Selektoren aktiviert, {withData} mit Daten.`,"progress.recoveringKey":`Entschlüsseln: Schlüssel für {address} wird gewonnen ...`,"slots.window.unread":`{bank} {address} (subcmd {subcmd}) konnte nicht gelesen werden: {error}`,"slots.read.refusedBuild":`Lesen der Firmware-Slots abgelehnt: {reason}. Außer dem Lesen der Version wurde nichts gesendet, daher wurde kein Slot angetastet.`,"slots.backup.notSaved":`die Sicherung {file} wurde nicht gespeichert, daher wurde nichts geschrieben. Ein Schreibvorgang läuft nie, ohne dass seine Sicherung vorher gespeichert ist; versuchen Sie es erneut, sobald sie gespeichert werden kann.`,"slots.backup.notSavedWhy":`die Sicherung {file} wurde nicht gespeichert ({error}), daher wurde nichts geschrieben. Ein Schreibvorgang läuft nie, ohne dass seine Sicherung vorher gespeichert ist; versuchen Sie es erneut, sobald sie gespeichert werden kann.`,"usb.speed.high":`High Speed (480 Mbit/s)`,"usb.speed.full":`Full Speed (12 Mbit/s)`,"usb.speed.code":`Code {code}`},shared:{"runPanel.percent":`{value} %`,"runPanel.progressLabel":`{label}: Fortschritt`,"runPanel.logLabel":`{label}: Protokoll`,"runPanel.trimmed":{one:`… {count} ältere Zeile ausgeblendet`,other:`… {count} ältere Zeilen ausgeblendet`},"runPanel.lineCount":{one:`{count} Zeile`,other:`{count} Zeilen`},"status.idle":`Bereit.`,"status.cancelled":`Abgebrochen.`,"status.cancelling":`Wird abgebrochen …`,"status.failedSeeLog":`Fehlgeschlagen — siehe Protokoll oben.`,"cameraLock.inUseElsewhere":`Die Kamera wird in einem anderen Browser-Tab oder Fenster verwendet — beenden oder schließen Sie den Vorgang dort zuerst.`,"backup.downloadNote":`Die ZIP-Datei wird automatisch heruntergeladen, bevor irgendetwas gesendet wird. Ein Browser meldet nicht, wann ein Download auf dem Datenträger angekommen ist. Prüfen Sie daher Ihren Download-Ordner, bevor Sie sich auf die Datei verlassen.`,"device.none":`Kein Gerät ausgewählt.`,"device.disconnected":`Gerät getrennt.`,"device.revoked":`Berechtigung entzogen.`,"device.unknownProduct":`unbekanntes Produkt`,"device.unknownVendor":`unbekannter Hersteller`,"hint.udev":`Unter Linux braucht die Kamera eine udev-Regel, bevor der Browser sie öffnen kann:

{rule}

Ziehen Sie die Kamera danach ab und stecken Sie sie wieder ein. Chromium aus Snap oder Flatpak ist oft per Sandbox von direktem USB-Zugriff abgeschnitten; das .deb- oder .rpm-Paket ist die zuverlässige Wahl.`,"hint.windows":`Unter Windows muss der WinUSB-Treiber an die Kamera gebunden sein, bevor irgendein Browser sie erreichen kann. Verwenden Sie Zadig (https://zadig.akeo.ie/): Options → List All Devices, wählen Sie den Eintrag, der nach Ihrer Kamera benannt ist — zum Beispiel „CompactPRO FF“ —, wählen Sie WinUSB und klicken Sie auf Replace Driver.`,"hint.holding":`Ein anderes Programm oder ein Systemtreiber belegt die Kamera — die USB-Schnittstelle kann jeweils nur ein Prozess belegen. Beenden Sie alles andere, was mit der Kamera kommuniziert, ziehen Sie sie dann ab und stecken Sie sie wieder ein.`,"hint.recipientFallback":`Oder stellen Sie in den Optionen den Empfänger (recipient) auf „Gerät“; dafür muss die Schnittstelle nicht belegt werden.`,"hint.optionsInvalid":`Öffnen Sie „Optionen“ und lesen Sie den Hinweis unter den Feldern zum zulässigen Bereich.`,"hint.usbTimeout":`Die Kamera hat die Anfrage angenommen und nie geantwortet. Ziehen Sie sie ab, stecken Sie sie wieder ein und versuchen Sie es dann mit einem kleineren chunk (64 ist der Wert, der überall funktioniert).`,"hint.usbStalled":`Die Kamera hat die Anfrage abgelehnt. Meist bedeutet das, dass ihre Firmware sie nicht unterstützt. Die Seite fragt die Kamera vor jedem Lesen nach ihrer Familie. Anfragen, die weiter abgelehnt werden, galten also der Familie, die die Kamera selbst gemeldet hat. Prüfen Sie die Firmware-Version im Tab „Info“.`,"hint.usbNotOpen":`Ein anderes Programm oder ein Systemtreiber belegt die Kamera. Schließen Sie es, oder stellen Sie in den Optionen den Empfänger (recipient) auf „Gerät“; dafür muss die Schnittstelle nicht belegt werden.`,"hint.usbTransferFailed":`Ziehen Sie die Kamera ab, stecken Sie sie wieder ein und versuchen Sie es erneut.`,"hint.deviceMode":`Die Kamera hat den Bildmodus nicht verlassen. Ziehen Sie sie ab, warten Sie, bis sie sich vollständig ausgeschaltet hat, und stecken Sie sie wieder ein.`,"hint.deviceWindow":`Die Selektortabelle dieser Familie passte nicht zur Kamera. Öffnen Sie im 4.x/Nano-Tab die „Optionen“ und führen Sie „Alle Selektoren auslesen“ aus, um zu sehen, was die Kamera tatsächlich bereitstellt.`,"hint.deviceVersionUnknown":`Es wurde nichts gesendet, was die Kamera verändern könnte. Ziehen Sie sie ab, stecken Sie sie wieder ein, lassen Sie sie fertig starten und versuchen Sie es erneut; eine Kamera, die ihre Firmware-Version meldet, wird normal gelesen.`,"hint.imageMalformed":`Die Datei ist kein entschlüsseltes Seek-Firmware-Image.`,"hint.imageUnsupported":`Dieses Image kann in seiner jetzigen Form nicht für die Kamera aufbereitet werden.`,"hint.imageKeyTable":`Das Image enthält nicht das Schlüsselpaar, das sein Dateiname angibt. Verwenden Sie die entschlüsselte Datei genau so, wie das Auslesen sie gespeichert hat, auch mit unverändertem Namen.`,"hint.flashRefused":`Es wurde nichts in die Kamera geschrieben.`,"hint.familyUnsupported":`Es wurde nichts gelesen oder geschrieben. Jeder Tab deckt einen Bereich von Firmware-Versionen ab: Kameras mit 0.x und 1.x gehören zu „Auslesen & entschlüsseln 0.x/1.x 2014/2016“, Kameras mit 4.x und Nano zu „Auslesen & entschlüsseln 4.x/Nano“. Der Tab „Info“ sagt, zu welchem Tab die Kamera gehört.`,"hint.firmwareTooOld":`Keine Firmware-Familie kann diesen Build hier lesen: Seine Firmware hat keinen Lese-Handler für den Befehl, mit dem dieser Tab den Flash-Speicher liest. Deshalb wurde nichts an sie gesendet, was falsch gelesen werden könnte. Eine Compact mit 0.7.0.7 oder 0.7.0.8 lässt sich unter „Auslesen & entschlüsseln 0.x/1.x 2014/2016“ lesen. Ein Flash-Abbild, das mit einem SPI-Programmiergerät oder über SWD/J-Link erstellt wurde, kann auf dieser Seite trotzdem entschlüsselt werden, unter „Datei/Slot entschlüsseln“.`,"hint.powerCycle":`In diesem Assistenten: Ziehen Sie die Kamera ab und stecken Sie sie wieder ein, klicken Sie auf „Gerät verbinden“ und wählen Sie sie aus, und starten Sie dann denselben Schritt noch einmal. Der Durchlauf ist hier noch geladen — es gibt nichts fortzusetzen.`,"deviceInfo.running":`Laufende Firmware`,"deviceInfo.version":`Version`,"deviceInfo.family":`Firmware-Familie`,"deviceInfo.build":`Build`,"deviceInfo.bootloader":`Bootloader`,"deviceInfo.platform":`Plattform`,"deviceInfo.serial":`Seriennummer`,"deviceInfo.usbLink":`USB-Verbindung`,"deviceInfo.bootConfig":`Boot-Konfiguration`,"deviceInfo.bootedFrom":`Gestartet aus`,"deviceInfo.nextStart":`Nächster Start`,"deviceInfo.upgradeTarget":`Upgrade-Ziel (eigenes Upgrade)`,"deviceInfo.bankAt":`{bank} bei {address}`,"deviceInfo.perDeviceKey":`Geräteschlüssel`,"deviceInfo.notProgrammed":`nicht programmiert — die Kamera verwendet ersatzweise Schlüssel B`,"deviceInfo.keysTitle":`Aus dieser Kamera gelesene Schlüssel`,"deviceInfo.foundAt":`Gefunden bei`,"deviceInfo.flashOffset":`Flash-Offset {offset}`,"deviceInfo.keyA":`Schlüssel A`,"deviceInfo.keyB":`Schlüssel B`,"deviceInfo.keysConfirmed":`Bestätigt durch Abgleich mit dem Schlüsselstrom-Zustand eines Slots, der aus dem Chiffretext selbst gewonnen wurde. Ein Upload wird so gebaut, dass jeder Slot ihn unter dem Speicherschlüssel des Bootloaders ({storeKey}) ablegt, oder unter dem eigenen Schlüssel des gestarteten Slots, wo der Speicherschlüssel der Anwendung ein anderer ist.`,"deviceInfo.keysDecrypted":`Jeder Slot wurde im Browser entschlüsselt, indem sein Schlüsselstrom aus seinen eigenen Reset-Vektoren berechnet wurde, deren Klartext bekanntermaßen null ist. Entschlüsseln ist nicht dasselbe wie Starten: Der Bootloader probiert immer nur {storeKey} und Schlüssel A. Ein Slot, der unter einem anderen Schlüssel geschrieben wurde, hat deshalb eine fehlerfreie Prüfsumme und wird trotzdem übersprungen. Es wurde nichts geschrieben.`,"deviceInfo.orphan":{one:`**{banks} enthält ein gültiges Firmware-Image, das mit einem Schlüssel verschlüsselt ist, den der Bootloader dieser Kamera nicht kennt.** Das Image ist intakt und seine Prüfsumme stimmt, aber der Bootloader probiert beim Prüfen eines Slots nur {storeKey} und Schlüssel A. Deshalb überspringt er ihn und startet etwas anderes.`,other:`**{banks} enthalten jeweils ein gültiges Firmware-Image, das mit einem Schlüssel verschlüsselt ist, den der Bootloader dieser Kamera nicht kennt.** Die Images sind intakt und ihre Prüfsummen stimmen, aber der Bootloader probiert beim Prüfen eines Slots nur {storeKey} und Schlüssel A. Deshalb überspringt er sie und startet etwas anderes.`},"deviceInfo.orphanIsTarget":`Das ist der Slot, in den ein Upgrade schreibt. Die Anwendung, die auf dieser Kamera läuft, verschlüsselt mit diesem unbekannten Schlüssel neu. **Ein Schreiben über diese Seite erzeugt deshalb nur einen weiteren Slot, aus dem der Bootloader nicht starten kann** — in Betrieb bleibt {bank}. Der Ausweg ist, den Slot direkt mit einem SPI-Programmiergerät oder über SWD/J-Link zu schreiben.`,"deviceInfo.otherBank":`der andere Slot`},info:{"status.notRead":`Noch nicht gelesen.`,"status.reading":`Wird gelesen ...`,"status.noVersion":`Keine Version gemeldet.`,"status.tooOld":`Gelesen. Firmware {version} ist älter als 0.8.0.0 — sonst wurde nichts gelesen.`,"status.read":`Gelesen. Firmware {version}.`,"read.title":`Die Kamera lesen`,"read.description":`Nur Lesen. Fragt die Kamera, was sie ausführt, wie sie startet, welche Schlüssel sie hat und was jeder Slot enthält: dasselbe Lesen wie seek-fw info. Es wird nichts geschrieben.`,"read.actions":`Info-Aktionen`,"read.button":`Firmware-Version lesen`,"read.connectFirst":`Verbinden Sie zuerst oben die Kamera und klicken Sie dann auf „Firmware-Version lesen“.`,"read.showDetails":`Details im Protokoll anzeigen`,"read.panel":`Firmware-Version`,"result.title":`Was die Kamera meldet`,"result.version":`Firmware-Version`,"result.build":`Build`,"result.range":`Versionsbereich`,"result.tab":`Tab für diese Kamera`,"result.rangeLegacy":`0.x / 1.x: die Kameras von 2014 und 2016`,"result.rangeModern":`2.x und neuer: die Kameras mit 4.x, Nano und Mosaic`,"result.rangeUnknown":`unbekannt`,"result.noVersion":`**Die Kamera hat ihre Firmware-Version nicht gemeldet.** Sonst wurde nichts gesendet. Ziehen Sie sie ab, stecken Sie sie wieder ein, lassen Sie sie fertig starten und lesen Sie erneut.`,"result.noTab":`Kein Tab liest diesen Build.`,"result.openTab":`Öffnen Sie für diese Kamera <tab>{tab}</tab>. Dieser Tab fragt die Kamera vor jedem Lesen noch einmal nach ihrer Familie und lehnt eine Kamera ab, die nicht zu der Familie gehört, für die er gedacht ist.`,"tabs.title":`Wofür jeder Tab da ist`,"tabs.intro":`Fünf Tabs, in dieser Reihenfolge. Jeder ist eine eigene Seite, und die Kopfzeile zeigt, in welchem Sie sich befinden.`,"tabs.caption":`Die Tabs, was sie tun, welche Kameras sie abdecken und ob sie schreiben`,"tabs.tab":`Tab`,"tabs.does":`Was er tut`,"tabs.cameras":`Kameras`,"tabs.writes":`Schreibt in die Kamera?`,"tabs.info.does":`Liest, was die Kamera meldet: ihre Firmware, die Familie, als die sie sich meldet, wie sie startet, ihre Schlüssel und jeden Slot. Dasselbe Lesen wie seek-fw info. Er schreibt nichts.`,"tabs.info.cameras":`Jede Seek-Kamera, die WebUSB öffnen kann.`,"tabs.info.writes":`Nein.`,"tabs.preserve.does":`Erstellt eine vollständige Kopie des 4 MB großen Flash-Speichers der Kamera und speichert nach jedem Schritt eine Durchlaufdatei. Um alles lesen zu können, patcht er die Firmware vorübergehend, bringt danach die ursprüngliche Firmware zurück und prüft sie. Er führt Schritt für Schritt durch den Ablauf.`,"tabs.preserve.cameras":`Kameras mit Firmware 0.x und 1.x: die Compact-Builds von 2014, die Compact-PRO-Builds von 2016 (1.0.3.x) und der Compact-Build 1.3.0.8 FF (16 Hz).`,"tabs.preserve.writes":`Ja, in zwei Schritten, und jeder fragt vorher nach. Er stellt die Kamera wieder so her, wie sie war.`,"tabs.v4.does":`Liest den gesamten Flash-Speicher einer Kamera mit 4.x oder Nano und entschlüsselt die gefundenen Firmware-Slots. Nur Lesen: Er sendet sechs Lesebefehle und keinen Schreibbefehl.`,"tabs.v4.cameras":`Kameras mit Firmware 4.x (Compact, Compact PRO, Compact XR), Mosaic (10.x und 2.x) und Nano (42.x und 44.x), ab 2018.`,"tabs.v4.writes":`Nein.`,"tabs.decrypt.does":`Entschlüsselt eine Datei, die Sie bereits haben: ein vollständiges Flash-Abbild, Slot für Slot, oder einen einzelnen 64-KB-Firmware-Slot. Das Ergebnis kann heruntergeladen werden.`,"tabs.decrypt.cameras":`Keine. Er verwendet keine Kamera, funktioniert also ohne angeschlossenes Gerät und in jedem Browser.`,"tabs.decrypt.writes":`Nein. Er schreibt nur den Download.`,"tabs.slots.does":`Liest die drei Firmware-Slots (Slot A, Slot B und Recovery-Slot R), zeigt, was jeder enthält und aus welchem die Kamera startet, und kann jeweils einen Slot auslesen oder beschreiben.`,"tabs.slots.cameras":`Kameras mit Firmware 0.8.0.0 und neuer.`,"tabs.slots.writes":`Ja, jeweils einen Slot, und jeder Schreibvorgang fragt vorher nach.`,"split.title":`Wo die Builds von 2016 und 1.3.0.8 FF zu finden sind`,"split.where":`Die Compact-PRO-Builds von 2016 (1.0.3.0 und 1.0.3.2, einschließlich ihrer FF-Varianten) und der Compact-Build 1.3.0.8 FF (16 Hz) sind **keine** 4.x-Kameras und werden auch nicht wie eine gelesen. Ihr Protokoll ist das gesperrte von 2014–2017, und ihre Firmware speichert die Slots mit einer anderen Verschlüsselung (2016) oder als Klartext-Kette von 2014 mit einem Weg nur über den Recovery-Slot (FF). Sie gehören deshalb zu **Auslesen & entschlüsseln 0.x/1.x 2014/2016**, und der 4.x/Nano-Tab lehnt sie ab, bevor er irgendetwas liest.`,"split.evidence":`Der Nachweis, dass sie im 0.x/1.x-Tab funktionieren: Die Preserve-Pipeline hat für jeden von ihnen einen abgeleiteten Patch, und ihre Emulator-Läufe sind für beide erfolgreich. Der Build 1.0.3.0 hat auf seinem nativen Flash-Abbild von 2016 Sicherung, Patch, Commit, vollständiges Auslesen, Wiederherstellung und Prüfung durchlaufen; der 1.3.0.8 FF hat seinen Weg über den Recovery-Slot durchlaufen. Auf der Testkamera, einer Compact PRO 1.0.3.0, wurde das Lesen in Preserve-Schritt 02 ohne Reset und ohne Schreiben abgeschlossen, und die Kamera wurde als 2016er-Verschlüsselung erkannt. Auf diesen Builds wird die 4.x-Selektortabelle bei 38 ihrer 63 Selektoren abgelehnt, der 4.x-Tab könnte für sie also nur Lücken liefern.`,"split.stay":`Sie bleiben deshalb im 0.x/1.x-Tab, und der 4.x/Nano-Tab hat keine Auswahl der Firmware-Familie, über die sie dort gelesen würden.`,"report.camera":`Kamera`,"report.product":`Produkt`,"report.manufacturer":`Hersteller`,"report.serial":`Seriennummer`,"report.platform":`Plattform`,"report.usbLink":`USB-Verbindung`,"report.noProduct":`(kein Produktname)`,"report.none":`(keiner)`,"report.unreadable":`(nicht lesbar)`,"report.firmware":`Firmware`,"report.running":`Laufend`,"report.bootloader":`Bootloader`,"report.family":`Firmware-Familie`,"report.readUnder":`Gelesen als`,"report.detected":`Erkannt`,"report.boot":`Start`,"report.booted":`Gestartet`,"report.lastStart":`Letzter Start`,"report.running1308":`Laufend (1.3.0.8)`,"report.nextStart":`Nächster Start`,"report.upgradeTarget":`Upgrade-Ziel`,"report.notReplayed":`(nicht abgefragt)`,"report.targetConfirmed":`{slot} (über USB bestätigt)`,"report.buildNotKnown":`unbekannt: {why}. Für ein 16-Hz-FF-Image muss die Kamera sagen, welchen Build sie ausführt (der Slots-Tab fragt danach)`,"report.buildWhy":`{build}: {why}`,"report.buildFf":`der 16-Hz-FF-Build 1.3.0.8`,"report.build8Hz":`der 8-Hz-Build 1.3.0.8`,"report.keys":`Schlüssel`,"report.slots":`Slots`,"report.slotsCaption":`Jeder Slot so, wie das Lesen ihn vorgefunden hat. Nur Lesen: Geschrieben wird im Slots-Tab.`,"report.slot":`Slot`,"report.address":`Adresse`,"report.version":`Version`,"report.size":`Größe`,"report.key":`Schlüssel`,"report.accepts":`Akzeptiert`,"report.footer":`Footer`,"report.bootable":`Startfähig`,"report.bytes":`{count} B`,"report.plaintext":`keiner (Klartext)`,"report.yes":`ja`,"report.no":`nein`,"report.notApplicable":`k. A.`,"report.slotReason":`{slot}: {reason}`,"report.writing":`Schreiben`,"report.noBankWritten":`Kein Slot dieser Kamera wird beschrieben:`,"report.oneBank.plain":`Ein Slot nach dem anderen: Der Slots-Tab beschreibt oder patcht jeweils einen Slot dieser Kamera; jeder Slot wird unverschlüsselt übertragen (das Image, wie es ist, ohne Schlüssel); und jeder Schreibvorgang fragt vorher nach.`,"report.oneBank.slotKeystream":`Ein Slot nach dem anderen: Der Slots-Tab beschreibt oder patcht jeweils einen Slot dieser Kamera; jeder Slot wird unter dem eigenen Schlüsselblock 0 seines Images übertragen; und jeder Schreibvorgang fragt vorher nach.`,"report.oneBank.keyA":`Ein Slot nach dem anderen: Der Slots-Tab beschreibt oder patcht jeweils einen Slot dieser Kamera; jeder Slot wird unter Schlüsseln übertragen, die vom gestarteten Slot und der laufenden Anwendung abgeleitet sind; und jeder Schreibvorgang fragt vorher nach.`,"report.oneBank.ffVendor":`Ein Slot nach dem anderen: Der Slots-Tab beschreibt oder patcht jeweils einen Slot dieser Kamera; jeder Slot wird so übertragen, wie die Hersteller-App das 16-Hz-FF-Image überträgt (das Image XOR seinen eigenen Schlüsselblock 0), und von der Kamera unter Schlüssel B gespeichert; und jeder Schreibvorgang fragt vorher nach.`,"report.refusesEvery":`Der Slots-Tab lehnt jeden Slot dieser Kamera ab:`},decrypt:{"status.noFile":`Keine Datei gewählt.`,"status.reading":`Datei wird gelesen ...`,"status.notUsable":`Kein verwendbares Flash-Abbild.`,"status.building":`Archiv wird erstellt ...`,"status.nothingDecrypted":`Keine Images entschlüsselt — der Grund steht im Protokoll. Das Manifest liegt in Ihren Downloads.`,"status.done":{one:`Fertig — {done}/{count} Slot entschlüsselt. Prüfen Sie Ihre Downloads.`,other:`Fertig — {done}/{count} Slots entschlüsselt. Prüfen Sie Ihre Downloads.`},"offline.title":`Ein vorhandenes Flash-Abbild entschlüsseln`,"offline.description":`Ein vollständiges Flash-Abbild, Slot für Slot entschlüsselt.`,"offline.intro":`Schritt 2 im 4.x/Nano-Tab entschlüsselt bereits alles, was er liest. Sie brauchen diesen Teil also nur, wenn Ihr Flash-Abbild aus einer anderen Quelle stammt — einem früheren Durchlauf, J-Link oder einem SPI-Programmiergerät. Die Datei wird lokal gelesen und nie hochgeladen. **Dieser Teil funktioniert in jedem Browser**, auch in Safari und unter iOS, weil er keinen USB-Zugriff braucht.`,"offline.actions":`Aktionen zum Offline-Entschlüsseln`,"offline.choose":`Flash-Abbild wählen…`,"offline.panel":`Offline entschlüsseln`,"offline.detectedTitle":`Erkannte Firmware-Familie`,"offline.detectedIntro":`Es ist keine Kamera angeschlossen, daher wird die Familie anhand der Images in der Datei selbst bewertet. Der Schlüssel wird in jedem Fall aus dem Chiffretext jedes Slots berechnet; diese Bewertung bestimmt nur, welche Firmware-Familie im Bericht genannt wird.`,"offline.scoreBasis":`anhand der Images in der Datei`,"slot.title":`Einen Firmware-Slot entschlüsseln`,"slot.description":`Ein Slot aus einer Datei: 64 KB, so wie die Kamera ihn speichert.`,"slot.intro":`Wählen Sie eine Datei, die einen einzelnen Firmware-Slot enthält — einen Slot mit 65.536 Bytes, wie ihn das Auslesen eines Slots im Tab <link>{tab}</link> speichert, oder die 64 KB an der Adresse eines Slots in einem vollständigen Flash-Abbild. Die Seite ermittelt den Schlüssel aus den eigenen Bytes des Slots, entschlüsselt das Image und bietet es zum Download an, zusammen mit Schlüssel, Größe und SHA-256. Es wird keine Kamera verwendet, das funktioniert also auch ohne angeschlossenes Gerät.`,"slot.refusedIntro":`Eine Datei, die nicht genau ein Slot ist, kein Firmware-Image enthält oder sich nicht entschlüsseln lässt, wird mit Begründung abgelehnt. Ein gelöschter Slot wird als solcher gemeldet; es gibt dann nichts zu entschlüsseln.`,"slot.actions":`Aktionen zur Slot-Datei`,"slot.choose":`Slot-Datei wählen…`,"slot.decrypting":`{file} wird entschlüsselt …`,"slot.unreadable":`Die Datei konnte nicht gelesen werden.`,"slot.notDecrypted":`Nicht entschlüsselt: {file} ist kein Firmware-Slot, den diese Seite entschlüsseln kann.`,"slot.nothingWritten":`Es wurde nirgends etwas geschrieben. Wählen Sie eine 64-KB-Slot-Datei oder im Abschnitt oben ein vollständiges Flash-Abbild.`,"slot.erased":`{file} ist ein gelöschter Slot.`,"slot.resultTitle":`Entschlüsselter Firmware-Slot`,"slot.file":`Datei`,"slot.fileSize":`Dateigröße`,"slot.fileSha":`SHA-256 der Datei`,"slot.imageVersion":`Image-Version`,"slot.imageSize":`Image-Größe`,"slot.imageSha":`SHA-256 des Images`,"slot.acceptanceSum":`Prüfsumme`,"slot.notComputed":`für diese Form nicht berechnet`,"slot.family":`Familie`,"slot.familyDetected":`{name} (aus dem Image erkannt)`,"slot.familyMismatch":`{name} — die Summe ist nicht der Zielwert der Prüfsumme dieser Familie, der Bootloader würde das Image in dieser Form also nicht annehmen`,"slot.unknown":`unbekannt`,"slot.bytes":`{size} B`,"slot.key":`Schlüssel`,"slot.keyPlain":`keiner: Der Slot enthält das Image im Klartext (die Klartext-Kette von 2014)`,"slot.keyFfB":`Schlüssel B des 1.3.0.8-FF-Paars`,"slot.storedAs":`Gespeichert als`,"slot.storedAsFfB":`das Image XOR den Schlüsselstrom von Schlüssel B, Header-Fenster unverändert`,"slot.keyNone":`keiner`,"slot.keyNamed":`{key} — {name}`,"slot.keyForm":`Schlüsselform`,"slot.keyFormOnce":`{k} — das Image selbst enthält diese Form genau einmal, das bestimmt sie`,"slot.keyFormDefault":`{k} — keine Form kommt genau einmal im Image vor, daher wird der Standardwert der Familie angezeigt`,"slot.resultActions":`Aktionen zum entschlüsselten Image`,"slot.download":`{file} herunterladen`,"slot.downloadFallback":`das entschlüsselte Image`,"detection.detected":`Erkannt`,"detection.score":`Bewertung`,"detection.scoreText":`{score} von 1.00, {basis}`,"detection.readAs":`Gelesen als`,"detection.summary":`Zusammenfassung`,"detection.why":`Begründung:`,"detection.ambiguous":`**Die Hinweise haben nicht eindeutig ergeben, welche Familie das ist.** Entweder hat die führende Familie nicht besser abgeschnitten als der allgemeine Ersatz, oder eine zweite lag zu knapp dahinter, um zu entscheiden. Die Entschlüsselung ist davon nicht betroffen — der Schlüssel wird in jedem Fall aus dem Chiffretext berechnet —, aber die im Bericht genannte Familie und alles, was davon abhängt, ist eine Vermutung.`},v4:{"status.starting":`Wird gestartet ...`,"status.building":`Archiv wird erstellt ...`,"status.cancelling":`Wird abgebrochen — alles bisher Gelesene wird gespeichert ...`,"status.refused":`Abgelehnt — es wurde nichts gelesen. Siehe die Meldung über dem Protokoll.`,"status.sweepDone":`Fertig — {armed}/{total} Selektoren aktiviert, {withData} mit Daten. Prüfen Sie Ihre Downloads.`,"status.sweepDoneCancelled":`Fertig — {armed}/{total} Selektoren aktiviert, {withData} mit Daten (abgebrochen). Prüfen Sie Ihre Downloads.`,"status.dumpDone":`Fertig — {read}/{expected} Fenster gelesen. Prüfen Sie Ihre Downloads.`,"status.dumpDoneCancelled":`Fertig — {read}/{expected} Fenster gelesen (abgebrochen). Prüfen Sie Ihre Downloads.`,"status.dumpDoneIncomplete":`Fertig — {read}/{expected} Fenster gelesen (unvollständig — siehe Protokoll). Prüfen Sie Ihre Downloads.`,"refusal.generic":`Die Kamera passte nicht zur Familie 4.x/Nano, und dieser Tab liest nur diese Familie. Es wurde nichts gelesen. Für eine Kamera mit 0.x oder 1.x (Builds von 2014 oder 2016) verwenden Sie „{tab}“.`,"refusal.otherFamily":`Die Kamera sieht nach {name} ({id}) aus, nicht nach einer 4.x/Nano-Kamera, und dieser Tab liest nur 4.x/Nano. Es wurde nichts gelesen. Für eine Kamera mit 0.x oder 1.x (Builds von 2014 oder 2016) verwenden Sie „{tab}“.`,"refusal.legacyLine":`Die Kamera führt {version} aus, einen Build mit 0.x oder 1.x (2014 oder 2016), und dieser Tab liest nur 4.x/Nano. Außer der Version wurde nichts gelesen. Für eine Kamera mit 0.x oder 1.x verwenden Sie „{tab}“.`,"dump.title":`Auslesen`,"dump.actions":`Aktionen zum Auslesen`,"dump.start":`Auslesen starten`,"dump.panel":`Auslesen`,"dump.how":"Beide fragen die Kamera zuerst, welche Firmware sie ausführt: ihre Version, mit `{getInfo}` — dem einen Lesebefehl, den jeder Seek-Build gleich beantwortet — und, nur wenn dieser Build über USB gelesen werden kann, je ein einfaches und ein Token-tragendes `{begin}` sowie ein einzelnes Lesen. So erkennt die Seite, welcher Familie die Kamera angehört. Dieser Tab liest nur die Familie 4.x und Nano. Eine Kamera, die die Antworten anderswo einordnen, wird abgelehnt, bevor irgendetwas gelesen wird, und die Seite nennt den passenden Tab. Eine Kamera, die ihre Version nicht meldet oder einen Build älter als 0.8.0.0 ausführt, wird gar nicht gelesen, und die Seite sagt, warum.","dump.modes":"**Auslesen starten** liest jeden Block, den die eigene Selektortabelle des Builds erreicht. **Alle Selektoren auslesen** unter *Optionen* weiter unten probiert jeden `{begin}`-Selektor `{first}`–`{last}` und speichert, was jeder zurückgibt — langsamer, erfasst aber auch Blöcke, die die kuratierte Tabelle auslässt.","dump.sweep":`Alle Selektoren auslesen ({first}–{last})`,"dump.sweepNote":`Probiert jeden Selektor und speichert, was jeder zurückgibt. Langsamer als „Auslesen starten“.`,"output.title":`Was Sie erhalten`,"output.intro":"Einen einzigen `{ext}`-Download mit:","output.caption":`Dateien im heruntergeladenen Archiv`,"output.file":`Datei`,"output.what":`Inhalt`,"output.flash":`das zusammengesetzte 4-MB-Flash-Abbild (die Lückenfüllung und, falls verwendet, das Entsperr-Token stehen in manifest.json)`,"output.windows":`jeder 64-KB-Block genau so, wie er über USB kam`,"output.decrypted":`jeder Slot mit Firmware-Image, entschlüsselt (falls ein Schlüssel gefunden wurde)`,"output.reports":`Bericht pro Slot: Schlüssel, Fundort des Schlüssels, Familie und Verschlüsselung, SP, Einsprungadresse, SHA-256`,"output.manifest":`genaue Metadaten zu Lesen, Lücken und Entschlüsselung`,"output.readme":`was die Aufnahme ist und wo ihre Grenzen liegen`,"output.keyFromDump":`Der Schlüssel wird aus dem Flash-Abbild selbst gewonnen, es ist also weder eine Schlüsseldatei noch ein Gerätegeheimnis nötig.`,"output.bestEffort":`Die Entschlüsselung bleibt trotzdem ohne Gewähr. Wird kein Schlüssel gefunden — zum Beispiel bei einem Gerät, dessen Bootloader den Schlüssel aus dem OTP-Speicher des Chips ableitet, der in einem Flash-Abbild nicht enthalten ist —, wird dieser Slot einfach übersprungen, und der Rest des Archivs ist nicht betroffen.`,"readonly.title":`Nur-Lese-Garantie`,"readonly.intro":`Dieser Tab kann genau sechs Herstellerbefehle senden. Das ist sein gesamter Wortschatz — es gibt keinen Codepfad zu irgendetwas anderem:`,"readonly.caption":`Die sechs reinen Lese-Herstellerbefehle`,"readonly.absent":"`{setData}`, `{complete}`, `{reset}` und alle Befehle zum Hochladen, Committen und Löschen fehlen in dieser Ansicht. Auch `{usbReset}` wird nie aufgerufen; bei einem erneuten Versuch wird die Verbindung nur geschlossen und neu geöffnet. Die Entschlüsselung geschieht vollständig im Arbeitsspeicher, an der Kopie in Ihrem Browser, und berührt das Gerät nie.","readonly.writing":`Das Schreiben in die Kamera liegt in einem anderen Tab, <link>{tab}</link>, der jeweils einen Slot schreibt und vor jedem Schreibvorgang nachfragt. Nichts in *diesem* Tab kann diese Befehle erreichen.`,"readonly.firstReads":"Bis die Kamera ihre Firmware-Version gemeldet hat, werden nur drei der sechs gesendet, und nur als Lesevorgänge: `{getInfo}`, `{getMode}` und `{getError}`. Das sind die Lesebefehle, die in allen 36 untersuchten Firmware-Images dieselbe Befehlsnummer mit derselben Bedeutung haben. Eine Befehlsnummer bedeutet nicht in jedem Build dasselbe, daher geht nichts anderes hinaus, bis der Build bekannt ist.","gap.summary":`Die Lücke bei {address}`,"gap.where":"Der USB-Befehlssatz bietet einen Selektor für das Lesefenster für jeden 64-KB-Block des 4 MB großen Flash-Speichers außer `{range}`. Dieser Block wird im zusammengesetzten Abbild mit `{fill}` gefüllt und in `{manifest}` vermerkt.","gap.costs":"**In der Praxis kostet Sie das nichts.** Bei den meisten Kameras ist dieser Block einfach gelöschter Flash-Speicher, der ohnehin als `{fill}` gelesen wird — die Füllung entspricht also dem, was wirklich dort steht, und das Abbild ist vollständig.","gap.redundant":"Und wenn der Block *doch* belegt ist, enthält er eine redundante Kopie. Diese Kameras halten dasselbe Firmware-Image in mehreren 64-KB-Slots: In jedem Flash-Abbild mit mehreren Slots, das bei der Entwicklung dieser Seite geprüft wurde, ergaben alle Slots entschlüsselt byteidentische Firmware — in einem Fall über vier Slots hinweg, die mit zwei verschiedenen Schlüsseln geschrieben worden waren. Auf dem einen Gerät mit einem echten Image bei `{address}` war es Byte für Byte gleich den Kopien bei `{before}` und `{after}`. Das Archiv enthält diese Firmware also trotzdem, nur von einer anderen Adresse gelesen.","gap.fine":"Diese Redundanz ist auch der Grund, warum eine Kamera, deren `{address}` als `{fill}` gelesen wird, in Ordnung ist: Die startfähige Firmware ist in den anderen Slots weiterhin vorhanden. Nichts in diesem Tab schreibt ohnehin in das Gerät — die Lücke betrifft nur die Datei, die Sie herunterladen.","gap.complete":`Wenn Sie wirklich ein streng vollständiges Abbild Byte für Byte brauchen — etwa um den Flash-Speicher mit einer Referenz zu vergleichen —, lesen Sie ihn über SWD/J-Link oder mit einem SPI-Programmiergerät.`,"opcodes.opcode":`Opcode`,"opcodes.name":`Name`,"opcodes.dir":`Richtung`,"opcodes.why":`Wozu er dient`,"opcodes.getInfo":`die laufende Firmware-Version, zuerst gelesen: Sie entscheidet, welche Selektortabelle das Auslesen verwendet, und eine Kamera, die keine meldet, wird nicht gelesen`,"opcodes.getError":`Status nach jedem Schritt prüfen`,"opcodes.setMode":`nur um Modus 0 zu wählen, und nur, wenn er nicht schon aktiv ist`,"opcodes.getMode":`den aktuellen Modus lesen`,"opcodes.getData":`das eigentliche Lesen des Flash-Speichers`,"opcodes.begin":`nur flüchtiger Selektor für das Lesefenster — er wählt, welchen 64-KB-Block die nächsten Lesevorgänge liefern, und schreibt nichts`,"identity.versionUnknown":`Nicht gelesen: Die Kamera hat nicht gesagt, welche Firmware sie ausführt.`,"identity.unsupported":`Nicht gelesen: Diese Kamera kann auf diese Weise nicht gelesen werden.`,"identity.title":`Erkannte Kamera`,"identity.firmware":`Firmware`,"identity.scoreBasis":`anhand der Antworten der Kamera, bevor ein Slot gelesen wird`,"options.title":`Optionen`,"options.subtitle":`— die Standardwerte sind richtig; hier müssen Sie nichts ändern.`,"options.chunk":`chunk (Control-IN-Bytes)`,"options.gapFill":`gap-fill-Byte`,"options.retries":`Wiederholungen pro Fenster`,"options.retryDelay":`Wartezeit vor Wiederholung (ms)`,"options.recipient":`Empfänger der Control-Übertragung`,"options.recipientAuto":`automatisch`,"options.recipientInterface":`Schnittstelle ({requestTypes})`,"options.recipientDevice":`Gerät ({requestTypes})`,"options.decrypt":`Firmware entschlüsseln`,"options.yes":`ja`,"options.no":`nein`,"options.help":`**chunk** ist die Größe jedes Control-IN-Lesevorgangs, höchstens 64: ein EP0-Paket. Bei einem längeren Lesevorgang kann ein Paket an das Boot-ROM der Kamera verloren gehen, wenn die Kamera im Leerlauf mit niedrigem Takt läuft; ein größerer Wert wird daher in Schritten von 64 Bytes gelesen. Ein kleinerer Wert wird wie angegeben verwendet, und wenn eine Kamera die Anfrage blockiert, geht die Seite von sich aus tiefer und macht weiter. **gap-fill** ist das Byte, das in den einen 64-KB-Block geschrieben wird, den USB nicht erreicht. **recipient** (der Empfänger) steht standardmäßig auf Schnittstelle und weicht auf Gerät aus, wenn der Browser Interface 0 nicht belegen kann — die Firmware akzeptiert beides.`,"options.chunkRange":`chunk muss zwischen 1 und {max} liegen, erhalten: {value}`,"options.gapFillByte":`gap-fill muss ein einzelnes Byte sein, erhalten: {value}`,"options.retriesMin":`Wiederholungen müssen null oder mehr sein, erhalten: {value}`,"options.retryDelayMin":`Wartezeit muss null oder mehr sein, erhalten: {value}`},slots:{"section.title":`Firmware-Slots bearbeiten`,"section.badge":`Schreibt in den Flash`,"section.description":`„Slots lesen“ fragt die Kamera, was sie ausführt, liest ihre drei Firmware-Slots — {a}, {b} und {r} — und zeigt, was jeder enthält. Lesen und Auslesen ändern nichts. Jede Schaltfläche zum Schreiben fragt nach, bevor auch nur ein Byte gesendet wird.`,"section.danger":`**Diese Seite kann in den Flash-Speicher der Kamera schreiben.** Ein Schreibvorgang löscht einen 64-KB-Slot und programmiert ihn neu. Ein Image, das formal gültig ist, aber nicht läuft, macht die Kamera startunfähig, und der Bootloader hat kein USB — dann können nur SWD/J-Link oder ein SPI-Programmiergerät sie wiederherstellen. Lesen Sie den Slot vorher aus und bewahren Sie die Datei auf.`,"actions.toolbar":`Slot-Aktionen`,"actions.read":`Slots lesen`,"run.label":`Slots`,"empty.connected":`Klicken Sie auf „Slots lesen“. Die Kamera wird zuerst gefragt, welchen Build sie ausführt, und auf einem Build, den diese Seite nicht unterstützt, wird kein Fenster geöffnet.`,"empty.disconnected":`Verbinden Sie die Kamera und klicken Sie dann auf „Slots lesen“.`,"unsupported.title":`Dieser Build wird hier nicht unterstützt. Es wurde kein Slot gelesen, und keiner kann beschrieben werden.`,"refusal.notIdentified.title":`Nicht erkannt: Diese Seite kann nicht feststellen, welchen Build die Kamera ausführt.`,"refusal.notIdentified.body":`Die Kamera hat keine verwendbare Firmware-Version geliefert, daher wurde kein Slot gelesen und kein Fenster geöffnet. Diese Seite deckt Builds ab {minVersion} ab. Builds vor {minVersion} liegen außerhalb dessen, was die Slots-Seite unterstützt; eine Kamera mit einem solchen Build wird hier nie gelesen.`,"refusal.notIdentified.hint":`Wenn die Kamera einen unterstützten Build ausführt, startet sie vielleicht gerade noch. {hint}`,"refusal.title":`Abgelehnt — es wurde kein Fenster geöffnet.`,"status.reading":`Wird gelesen ...`,"status.readingAgain":`Die Slots werden erneut gelesen ...`,"status.read":{one:`Gelesen. {read}/{count} Slot gelesen.`,other:`Gelesen. {read}/{count} Slots gelesen.`},"status.unsupported":`Auf diesem Build nicht unterstützt — es wurde kein Slot gelesen.`,"status.refused":`Abgelehnt — es wurde kein Fenster geöffnet. Siehe die Meldung unter dem Protokoll.`,"status.disconnected":`Gerät getrennt — lesen Sie die Slots erneut.`,"status.newDevice":`Neues Gerät ausgewählt — lesen Sie die Slots erneut.`,"status.dumping":`{bank} wird ausgelesen ...`,"status.dumped":`{bank} ausgelesen.`,"status.readingImage":`Image wird gelesen ...`,"status.ready":`Bereit — prüfen Sie den Plan und schreiben Sie ihn dann.`,"status.rejected":`Zurückgewiesen — siehe Protokoll oben.`,"status.writing":`Wird geschrieben ...`,"status.patching":`{bank} wird gepatcht ...`,"status.patchingEvery":`Alle Slots werden gepatcht ...`,"status.written.mismatch":`Geschrieben, aber die zurückgelesenen Daten stimmen nicht überein — siehe Ergebnis.`,"status.written.verified":`Geschrieben. Der Slot liest sich so zurück, wie er geschrieben wurde.`,"status.written.notCompared":`Geschrieben. Die zurückgelesenen Daten wurden nicht verglichen — siehe Ergebnis.`,"status.patched.unexpected":`Gepatcht, aber die zurückgelesenen Daten weichen nicht nur wie geplant ab — siehe Ergebnis.`,"status.patched.ok":`Gepatcht. Die zurückgelesenen Daten entsprechen dem Plan.`,"status.patched.unchecked":`Gepatcht. Die zurückgelesenen Daten wurden nicht geprüft — siehe Ergebnis.`,"status.every.stopped":{one:`Angehalten bei {bank} — {count} Slot gepatcht; siehe Ergebnis.`,other:`Angehalten bei {bank} — {count} Slots gepatcht; siehe Ergebnis.`},"status.every.unchecked":{one:`{count} Slot gepatcht, aber ein Rücklesen wurde nicht wie geplant geprüft — siehe Ergebnis.`,other:`{count} Slots gepatcht, aber ein Rücklesen wurde nicht wie geplant geprüft — siehe Ergebnis.`},"status.every.ok":{one:`{count} Slot gepatcht. Die zurückgelesenen Daten entsprechen dem Plan.`,other:`{count} Slots gepatcht. Die zurückgelesenen Daten entsprechen jeweils dem Plan.`},"status.cancelled.nothing":`Abgebrochen — es wurde nichts geschrieben.`,"status.cancelled.one":`Abgebrochen, nachdem der Commit für {bank} gesendet wurde — der Slot ist möglicherweise nur teilweise beschrieben. Lesen Sie ihn, bevor Sie sich auf ihn verlassen.`,"status.cancelled.many":`Abgebrochen, nachdem die Commits für {banks} gesendet wurden — jeder davon ist möglicherweise nur teilweise beschrieben. Lesen Sie sie, bevor Sie sich auf sie verlassen.`,"gate.connectFirst":`Verbinden Sie zuerst die Kamera.`,"gate.busy":`Ein anderer Vorgang läuft — warten Sie, bis er fertig ist.`,"gate.readFirst":`Lesen Sie zuerst die Slots.`,"gate.cameraRefused":`Diese Kamera kann von hier aus nicht beschrieben werden, aus dem Grund im Hinweis oben. Es wird nichts gesendet.`,"gate.notRead":`Nicht gelesen: {reason}. Lesen Sie die Slots erneut, bevor Sie diesen Slot beschreiben.`,"gate.notReadNoReason":`Nicht gelesen: Dieser Slot wurde nicht gelesen. Lesen Sie die Slots erneut, bevor Sie ihn beschreiben.`,"gate.emptyNotWritable":`Dieser Slot ist leer und kann auf diesem Build nicht beschrieben werden: {reason}`,"gate.noSuchBank":`Diesen Slot gibt es auf diesem Build nicht.`,"table.caption":`Jeder Firmware-Slot dieser Kamera — {a}, {b} und {r} — so, wie er im Browser gelesen und geprüft wurde`,"table.col.bank":`Slot`,"table.col.firmware":`Firmware`,"table.col.size":`Größe`,"table.col.key":`Schlüssel`,"table.col.bootable":`Startfähig`,"table.col.sha":`SHA-256 des Klartexts`,"table.col.actions":`Aktionen`,"table.notRead":`nicht gelesen — {reason}`,"table.notReadNoReason":`nicht gelesen — der Slot wurde nicht gelesen`,"table.empty":`leer`,"table.emptyNote":`Kein Image: Das Header-Fenster dieses Slots liest sich vollständig als 0xFF. Daraus wird nichts entschlüsselt, und ein Schreiben überschreibt keine Firmware.`,"table.emptyWritable":`Kann beschrieben werden. {why}`,"table.emptyNotWritable":`Kann auf diesem Build nicht beschrieben werden: {reason}`,"table.unknownVersion":`unbekannte Version`,"table.imageId":`Image {id}`,"table.noImage":`kein Image`,"table.bankSize":`Slot mit {size} B`,"table.imageSize":`Image {size} B`,"table.keyNone":`keiner (Klartext)`,"table.boot.empty":`— nichts zu starten`,"table.boot.bootable":`startfähig — der Bootloader nimmt ihn an`,"table.boot.notBootable":`nicht startfähig — wird beim Start übersprungen`,"table.boot.recoveryOnly":`nur Recovery — {letterR} läuft, wenn {letterA} und {letterB} nichts enthalten, was der Bootloader annimmt (an einer Kamera für eine frühere Form dieses Images gemessen); ob diese Form startet, ist ungetestet`,"table.boot.unknown":`unbekannt — {why}`,"table.dump":`Auslesen`,"table.flashPlain":`Entschlüsseltes Image schreiben…`,"table.flashRaw":`Rohdaten schreiben…`,"table.restore":`Aus Flash-Sicherung wiederherstellen (.bin oder .zip)…`,"table.makeFps":`Auf {hz} FPS umstellen`,"table.copyTo":`Nach {bank} kopieren`,"table.copyOff":`{button}: {reason}`,"table.copyOffNoReason":`{button}: aus`,"table.copyNote":`Kopiert die Firmware dieses Slots, so wie dieses Lesen sie entschlüsselt hat, in den Slot, den Sie wählen, egal was dieser jetzt enthält. Sie prüfen den Plan, bevor irgendetwas gesendet wird.`,"table.restoreNote":`Wählen Sie eine vollständige Flash-Sicherung: eine .bin (ein ganzes 4-MB-Flash-Abbild, etwa ein Auslesen mit J-Link) oder eine .zip, die eines enthält (eine Preserve-Durchlaufdatei oder die ZIP-Datei, die „Auslesen & entschlüsseln 4.x/Nano“ oder „Alle Selektoren auslesen“ speichert). Dieser Slot wird daraus herausgeschnitten, entschlüsselt und als Plan angezeigt, bevor irgendetwas gesendet wird.`,"table.fpsNote":`Hebt diesen Slot von {fromHz} Hz auf {toHz} Hz an, indem seine Bytes bearbeitet werden. Der Slot wird zuerst gesichert, als ZIP-Download, und die entschlüsselte Datei darin ist der Weg zurück.`,"table.risk.bootedRecovery":`{booted} und Recovery-Slot: Das Schreiben verlangt eine zusätzliche Bestätigung.`,"table.risk.booted":`{booted}: Das Schreiben verlangt eine zusätzliche Bestätigung.`,"table.risk.recovery":`{bank}: Das Schreiben verlangt eine zusätzliche Bestätigung.`,"table.risk.bootUnnamed":`Die Kamera nennt den Slot nicht, aus dem sie gestartet ist: Das Schreiben verlangt eine zusätzliche Bestätigung.`,"fps.applied":`Bildraten-Patch angewendet: Dieses Image läuft mit {hz} Hz.`,"fps.earlierPatch":`Bildraten-Patch nicht angeboten: Dieser Slot enthält einen früheren {hz}-Hz-Patch ohne die USB-Korrektur. Stellen Sie das Original-Image wieder her und verwenden Sie dann „Auf {hz} FPS umstellen“.`,"fps.atRate":`Kein Bildraten-Patch nötig: Dieser Build läuft bereits mit {hz} Hz.`,"fps.notOffered":`Bildraten-Patch nicht angeboten: {reason}`,"fps.readFirst":`lesen Sie zuerst die Slots — der Patch wird aus dem eigenen Image des Slots geplant`,"everyBank.toolbar":`Alle Slots`,"everyBank.make":`Alle Slots auf {hz} FPS umstellen`,"everyBank.faster":`Alle Slots schneller machen`,"everyBank.note":`Patcht {order} mit einer einzigen Bestätigung. Jeder Slot wird zuerst gesichert, in einem gemeinsamen ZIP-Download, und danach zurückgelesen.`,"everyBank.noteBootedLast":`Patcht {order} mit einer einzigen Bestätigung, den Slot, aus dem die Kamera jetzt startet, als letzten. Jeder Slot wird zuerst gesichert, in einem gemeinsamen ZIP-Download, und danach zurückgelesen.`,"what.copy":`das Image von {bank}`,"what.restore":`{bank} aus {file}`,"preview.title":`Vorbereitet für {bank} bei {address}`,"preview.file":`Datei`,"preview.source":`Image stammt aus`,"preview.target":`Ziel`,"preview.targetEmpty":`{bank} ist leer: Er enthält kein Image, dieser Schreibvorgang überschreibt also keine Firmware`,"preview.readAs":`Gelesen als`,"preview.readAs.ff":`ein entschlüsseltes {version}-FF-Image`,"preview.readAs.plain":`ein entschlüsseltes Image`,"preview.readAs.raw":`Rohdaten`,"preview.staging":`Übertragung`,"preview.key":`Schlüssel`,"preview.payload":`Nutzdaten`,"preview.payloadValue":{one:`{size} B in {count} Teil zu höchstens {chunk} B`,other:`{size} B in {count} Teilen zu je höchstens {chunk} B`},"preview.checksum":`Übertragungs-Prüfsumme`,"preview.stored":`Danach gespeichert`,"preview.storedNotPredicted":`nicht vorhergesagt — das Rücklesen ist die Prüfung`,"preview.storedPredicted":`{size} B vorhergesagt`,"preview.storedKeyB":`{size} B vorhergesagt — das Image XOR Schlüssel B, nicht die Nutzdaten selbst`,"preview.savedFirst":`Vorher gesichert`,"preview.compareCaption":`Was sich in {bank} ändert`,"preview.col.field":`Feld`,"preview.col.now":`Jetzt`,"preview.col.after":`Nach dem Schreiben`,"preview.readFirst":`Vor dem Schreiben lesen:`,"preview.note":`Hinweis: {note}`,"preview.nothingSent":`Es wurde noch nichts an die Kamera gesendet. Beim Schreiben werden diese Nutzdaten an {bank} übertragen und mit einem Commit abgeschlossen.`,"preview.toolbar":`Schreibaktionen für {bank}`,"preview.write":`In {bank} schreiben…`,"preview.discard":`Verwerfen`,"writeConfirm.title":`{what} in {bank} bei {address} schreiben?`,"writeConfirm.booted":`{bootsNow}. Das Schreiben ersetzt die Firmware, die die Kamera gerade ausführt. Wenn das neue Image nicht läuft, startet die Kamera möglicherweise gar nicht mehr.`,"writeConfirm.recovery":`{bank} ist der Recovery-Slot, die letzte Rückfallkopie, auf die der Bootloader zurückgreift. Nach dem Schreiben ist die Kamera ohne diese Kopie, bis sie wiederhergestellt ist.`,"writeConfirm.bootUnnamed":`Die Kamera sagt nicht, aus welchem Slot sie startet, daher wird {bank} als der Slot behandelt, aus dem sie jetzt startet. Das Schreiben kann die Firmware ersetzen, die die Kamera gerade ausführt.`,"writeConfirm.empty":`{bank} ist leer: Er enthält kein Image, es wird also keine Firmware überschrieben.`,"writeConfirm.eraseEmpty":`Der Schreibvorgang löscht trotzdem den 64-KB-Block des Flash-Speichers der Kamera bei {bank} (der schon leer ist) und programmiert ihn.`,"writeConfirm.erase":`Dabei wird ein 64-KB-Block des Flash-Speichers der Kamera gelöscht und bei {bank} neu programmiert.`,"writeConfirm.keyLine":`Das Image wird unter {key} geschrieben. Jeder andere Slot wird genauso geschrieben.`,"writeConfirm.backup":`Bevor irgendetwas gesendet wird, wird {bank} erneut gelesen und als ein ZIP-Download gespeichert: {file}. Prüfen Sie Ihren Download-Ordner darauf.`,"writeConfirm.noReset":`Es wird kein Reset gesendet. Ziehen Sie die Kamera danach ab und stecken Sie sie wieder ein, damit der Slot wirksam wird.`,"writeConfirm.noUsbRecovery":`Wenn das Image nicht läuft, kann die Kamera nicht über USB wiederhergestellt werden — nur mit SWD/J-Link oder einem SPI-Programmiergerät.`,"writeConfirm.ackUnnamed":`Mir ist bewusst, dass die Kamera nicht sagt, aus welchem Slot sie startet, dass dieser hier daher als der gestartete Slot behandelt wird und dass ein fehlerhaftes Image die Kamera startunfähig machen kann.`,"writeConfirm.confirm":`Ja — in {bank} schreiben`,"ack.booted":`Mir ist bewusst, dass dies der Slot ist, aus dem die Kamera jetzt startet, und dass ein fehlerhaftes Image die Kamera startunfähig machen kann.`,"ack.recovery":`Mir ist bewusst, dass dies der Recovery-Slot ist und dass ein fehlerhaftes Image die Kamera ohne letzte Rückfallkopie lässt.`,"fpsConfirm.title":`{bank} auf {hz} FPS umstellen?`,"fpsConfirm.booted":`{bootsNow}. Das gepatchte Image ersetzt die Firmware, die die Kamera jetzt ausführt.`,"fpsConfirm.recovery":`{bank} ist der Recovery-Slot, die letzte Rückfallkopie, auf die der Bootloader zurückgreift.`,"fpsConfirm.what":`{bank} enthält Firmware {version}, und dies lässt sein Image mit {toHz} Hz statt mit {fromHz} Hz laufen.`,"fpsConfirm.unknownVersion":`(unbekannt)`,"fpsConfirm.bytes":{one:`Der Patch ändert {count} Byte des Images und das Prüfsummenwort, sodass die Summe, die der Bootloader prüft, erhalten bleibt. Das Schlüsselpaar wird nicht angetastet.`,other:`Der Patch ändert {count} Bytes des Images und das Prüfsummenwort, sodass die Summe, die der Bootloader prüft, erhalten bleibt. Das Schlüsselpaar wird nicht angetastet.`},"fpsConfirm.wayBack":`Die entschlüsselte Datei in dieser ZIP-Datei ist der Weg zurück: Um den Patch rückgängig zu machen, schreiben Sie sie mit „Entschlüsseltes Image schreiben“ in {bank}.`,"fpsConfirm.noReset":`Es wird kein Reset gesendet. Ziehen Sie die Kamera danach ab und stecken Sie sie wieder ein, damit der gepatchte Slot wirksam wird.`,"fpsConfirm.ackUnnamed":`Mir ist bewusst, dass die Kamera nicht sagt, aus welchem Slot sie startet, und dass dieser hier daher als der gestartete Slot behandelt wird.`,"fpsConfirm.confirm":`Ja — {bank} patchen`,"fpsEvery.title":`Alle Slots auf {hz} FPS umstellen?`,"fpsEvery.titleMixed":{one:`Die Bildrate von {count} Slot patchen?`,other:`Die Bildrate von {count} Slots patchen?`},"fpsEvery.intro":{one:`Dies patcht {count} Slot, für den der Patch verfügbar ist (Firmware {version}):`,other:`Dies patcht {count} Slots, für die der Patch verfügbar ist (Firmware {version}):`},"fpsEvery.role.bootedRecovery":`{bank} (der Slot, aus dem diese Kamera jetzt startet, und der Recovery-Slot)`,"fpsEvery.role.booted":`{bank} (der Slot, aus dem diese Kamera jetzt startet)`,"fpsEvery.role.recovery":`{bank} (der Recovery-Slot, die letzte Rückfallkopie)`,"fpsEvery.role.bootUnnamed":`{bank} (die Kamera sagt nicht, aus welchem Slot sie startet)`,"fpsEvery.offer":{one:`{bank}: {fromHz} Hz auf {toHz} Hz, {count} Byte und das Prüfsummenwort.`,other:`{bank}: {fromHz} Hz auf {toHz} Hz, {count} Bytes und das Prüfsummenwort.`},"fpsEvery.other":`{bank}: {note}`,"fpsEvery.others":`Unverändert bleiben: {others}`,"fpsEvery.orderOne":`Es wird nur {bank} geschrieben und danach zurückgelesen.`,"fpsEvery.order":`Sie werden in dieser Reihenfolge geschrieben: {order}. Jeder Slot wird zurückgelesen, bevor der nächste folgt, und der erste Fehler hält den Rest an.`,"fpsEvery.orderBootedLast":`Sie werden in dieser Reihenfolge geschrieben: {order}. Der Slot, aus dem die Kamera jetzt startet, kommt zuletzt, sodass ein Fehler vor ihm anhält. Jeder Slot wird zurückgelesen, bevor der nächste folgt, und der erste Fehler hält den Rest an.`,"fpsEvery.wayBack":`Die entschlüsselten Dateien in dieser ZIP-Datei sind der Weg zurück: Um den Patch eines Slots rückgängig zu machen, schreiben Sie seine Datei mit „Entschlüsseltes Image schreiben“ in diesen Slot.`,"fpsEvery.noReset":`Es wird kein Reset gesendet. Ziehen Sie die Kamera danach ab und stecken Sie sie wieder ein, damit die gepatchten Slots wirksam werden.`,"fpsEvery.ack":`Mir ist bewusst, dass dies Folgendes beschreibt: {banks}, und dass ein fehlerhaftes Image die Kamera startunfähig machen kann.`,"fpsEvery.confirm":{one:`Ja — {count} Slot patchen`,other:`Ja — {count} Slots patchen`},"outcome.verified":`{bank} — {what}: Der Slot liest sich so zurück, wie er geschrieben wurde.`,"outcome.mismatch":`{bank} — {what}: Die zurückgelesenen Daten stimmen NICHT mit dem Geschriebenen überein.`,"outcome.notCompared":`{bank} — {what}: Der Slot wurde zurückgelesen, aber nicht verglichen; dieser Schreibvorgang ist hier also nicht bestätigt.`,"outcome.commitStatus":`Der Commit der Kamera hat den Status {status} zurückgegeben.`,"outcome.wasEmpty":`{bank} war vor diesem Schreibvorgang leer, es wurde also keine Firmware überschrieben.`,"outcome.provenVerified":`Bisher nachgewiesen: Die Nutzdaten wurden übertragen und mit einem Commit abgeschlossen, und der Slot liest sich so zurück, wie er geschrieben wurde. NICHT nachgewiesen: dass der Bootloader diesen Slot wählt oder dass das Image läuft.`,"outcome.provenCommitted":`Bisher nachgewiesen: Die Nutzdaten wurden übertragen und mit einem Commit abgeschlossen. NICHT nachgewiesen: dass der Bootloader diesen Slot wählt oder dass das Image läuft.`,"outcome.replug":`**ZIEHEN SIE DIE KAMERA JETZT AB UND STECKEN SIE SIE WIEDER EIN.** Es wurde kein Reset gesendet, daher wird der Slot erst nach einem echten Aus- und Wiedereinschalten wirksam. Lesen Sie danach die Slots erneut: Nur die Version und der aktive Slot, die die Kamera dann meldet, geben darüber Gewissheit.`,"outcome.replugShort":`**ZIEHEN SIE DIE KAMERA JETZT AB UND STECKEN SIE SIE WIEDER EIN.** Es wurde kein Reset gesendet. Lesen Sie danach die Slots erneut.`,"outcome.savedFirst":`Vorher gesichert, als Download: {file}.`,"outcome.wayBackOne":`Die entschlüsselte Datei darin ist der Weg zurück („Entschlüsseltes Image schreiben“ auf demselben Slot).`,"outcome.wayBackMany":`Die entschlüsselten Dateien darin sind der Weg zurück („Entschlüsseltes Image schreiben“ auf jedem Slot).`,"outcome.checkDownloads":`Prüfen Sie Ihren Download-Ordner darauf.`,"fpsOutcome.title":`{bank} — von {fromHz} Hz auf {toHz} Hz gepatcht (Firmware {version}).`,"fpsOutcome.readBackOk":{one:`Die zurückgelesenen Daten weichen von der gesicherten Kopie nur an {count} geplanten Byte ab: an den Patch-Stellen und am Summenwort.`,other:`Die zurückgelesenen Daten weichen von der gesicherten Kopie nur an den {count} geplanten Bytes ab: an den Patch-Stellen und am Summenwort.`},"fpsOutcome.readBackBad":{one:`Die zurückgelesenen Daten weichen NICHT nur wie geplant ab: {unexpected} unerwartete und {count} fehlendes Byte.`,other:`Die zurückgelesenen Daten weichen NICHT nur wie geplant ab: {unexpected} unerwartete und {count} fehlende Bytes.`},"fpsOutcome.notTaken":`Es wurde nicht zurückgelesen, der Patch ist hier also nicht geprüft.`,"fpsEveryOutcome.title":{one:`Alle Slots: {done} von {count} gepatcht, in dieser Reihenfolge: {order}.`,other:`Alle Slots: {done} von {count} gepatcht, in dieser Reihenfolge: {order}.`},"fpsEveryOutcome.readBackOk":{one:`Die zurückgelesenen Daten weichen vom gesicherten Slot nur an {count} geplanten Byte ab.`,other:`Die zurückgelesenen Daten weichen vom gesicherten Slot nur an den {count} geplanten Bytes ab.`},"fpsEveryOutcome.notTaken":`Es wurde nicht zurückgelesen.`,"fpsEveryOutcome.stopped":`Angehalten: {reason}.`,"fpsEveryOutcome.notWritten":`Nicht geschrieben: {banks}.`,"keys.refusedTitle":`Kein Slot dieser Kamera kann von hier aus beschrieben werden.`,"keys.title":`Schlüssel für die Schreibvorgänge`,"keys.chain":`Kette`,"keys.chainPlain":`die Klartext-Kette von 2014: Jeder Slot ist im Klartext gespeichert, keiner enthält also einen Schlüssel`,"keys.writtenAs":`Geschrieben als`,"keys.writtenPlain":`das Image, wie es ist, ohne Schlüssel, in jeden Slot`,"keys.stagedAs":`Übertragen als`,"keys.storedAs":`Gespeichert als`,"keys.refused":`Abgelehnt`,"keys.bootedBank":`Gestarteter Slot`,"keys.bootedHolds":`{bank} enthält {key}`,"keys.theBootedBank":`der gestartete Slot`,"keys.unnamedKey":`einen Schlüssel, den die Seite nicht benennen kann`,"keys.bootedBanksKey":`der Schlüssel des gestarteten Slots`,"keys.writtenDerived":`{line}; jeder Slot wird genauso geschrieben`,"how.title":`Was diese Schaltflächen tun`,"how.read":`**Slots lesen** und **Auslesen** ändern nichts an der Kamera. Die Kamera wird vor allem anderen gefragt, welchen Build sie ausführt; ein Build älter als {minVersion} wird gemeldet, und seine Slots werden nicht gelesen.`,"how.flash":`**Entschlüsseltes Image schreiben** nimmt ein Klartext-Image, verschlüsselt es so, wie die Firmware dieses Slots es braucht, bevor es übertragen wird, und zeigt den Plan. **Rohdaten schreiben** überträgt die Datei genau so, wie sie ist. Keine der beiden sendet etwas, bevor Sie bestätigen.`,"how.ff":`Eine Compact mit 1.3.0.8 kann der 8-Hz-Build oder der 16-Hz-FF-Build sein, und beide melden dieselbe Version. Die Kamera unterscheidet sie selbst: Ihre eigene Antwort für jeden Slot sagt, ob die antwortende Anwendung ihn annimmt, und für jeden Build lassen sich seine Antworten vorhersagen. Das 8-Hz-Image kann in jeden Slot. Das FF-Image wird so übertragen, wie die Hersteller-App es überträgt (das Image XOR Schlüssel A), und der 16-Hz-Build speichert es unter Schlüssel B, in jedem Slot. Die Seite lehnt es nicht ab: Der Plan sagt, bevor Sie bestätigen, was die Kamera voraussichtlich damit tut (der 8-Hz-Build lehnt es beim Commit ab, und eine Kamera mit einer anderen Version programmiert es so, wie es gesendet wird, und kann es dann nicht starten). Ob das FF-Image startet, ist UNTESTED (ungetestet): Für diesen Build liegt kein echter Bootloader in der Sammlung vor. Ein Schreiben in {letterR} verlangt wie jedes Schreiben in den Recovery-Slot die zusätzliche Bestätigung. Ein **leerer** Slot (sein Header-Fenster liest sich vollständig als 0xFF, wie bei {b} vieler Kameras von 2014) ist ein Zustand, kein Fehler. Er wird als die rohen 64 KB aus 0xFF ausgelesen, ohne etwas zu entschlüsseln, und genauso beschrieben wie jeder andere Slot; Plan und Bestätigung sagen, dass keine Firmware überschrieben wird.`,"how.copy":`**{copyA}**, **{copyB}** und **{copyR}** in einer Slot-Zeile schreiben die Firmware dieses Slots, so wie dieses Lesen sie entschlüsselt hat, in den anderen Slot, egal was dieser jetzt enthält. Das Image wird übertragen wie jedes entschlüsselte Image, Plan und Bestätigung sind also dieselben wie bei einer Datei. **Aus Flash-Sicherung wiederherstellen** nimmt eine .bin (ein ganzes 4-MB-Flash-Abbild, etwa ein Auslesen mit J-Link) oder eine .zip, die eines enthält (eine Preserve-Durchlaufdatei oder die ZIP-Datei, die „Auslesen & entschlüsseln 4.x/Nano“ oder „Alle Selektoren auslesen“ speichert), schneidet diesen Slot daraus heraus, entschlüsselt ihn und zeigt den Plan; sieht eine Sicherung nach einer anderen Kamera oder einer anderen Firmware aus, steht das im Plan. Ein Slot, der in der Sicherung leer ist oder den das Auslesen nicht gelesen hat, kann nicht durch einen Schreibvorgang wiederhergestellt werden, und die Seite sagt das.`,"how.fps":`**Auf N FPS umstellen** in einer Slot-Zeile bearbeitet das Image dieses Slots auf eine höhere Bildrate, und **Alle Slots auf N FPS umstellen** tut das mit jedem Slot, für den der Patch verfügbar ist, mit einer einzigen Bestätigung, den Slot, aus dem die Kamera jetzt startet, als letzten. Für einen Slot, für den er nicht verfügbar ist, nennt die Seite den Grund.`,"how.backup":"**Jeder Schreibvorgang sichert zuerst seinen Slot**: Der Slot wird erneut gelesen und als ein ZIP-Download gespeichert, benannt nach Uhrzeit, Seriennummer der Kamera, Firmware, Slot und Schreibvorgang (zum Beispiel `{example}`). Er enthält den Slot, wie er gespeichert ist, sein entschlüsseltes Image und eine Notiz, was jede Datei ist. Der Schreibvorgang wartet, bis der Download begonnen hat. Ein Browser meldet nicht, wann ein Download auf dem Datenträger angekommen ist, prüfen Sie daher Ihren Download-Ordner. Um zurückzugehen, schreiben Sie die entschlüsselte Datei aus der ZIP-Datei mit **Entschlüsseltes Image schreiben**.","how.write":"Ein Schreibvorgang löscht einen 64-KB-Slot und programmiert ihn. Der Bootloader bei `{address}` und die Boot-Konfiguration werden hier nie geschrieben, und es gibt kein Bedienelement, um den aktiven Slot zu wählen. Der Slot wird erst wirksam, nachdem die Kamera abgezogen und wieder eingesteckt wurde."},preserve:{"how.title":`Was Sie erwartet`,"how.descriptionIdle":`Verbinden Sie die Kamera und beginnen Sie dann mit Schritt 02.`,"how.descriptionRun":`Durchlauf {runId}.`,"how.descriptionRunVersion":`Durchlauf {runId} — Firmware {version}.`,"how.restarts":`Die Kamera wird in jedem Schritt **neu gestartet**. Nach einem Neustart erkennt Chrome sie nicht mehr (sie hat keine USB-Seriennummer), daher bittet die Seite Sie, auf **Gerät verbinden** zu klicken und die Kamera erneut auszuwählen. Das ist der normale Ablauf — der Schritt läuft von selbst weiter, sobald Sie das getan haben.`,"how.noFile":`Es gibt keine Firmware-Datei auszuwählen: Alles wird aus der Kamera selbst gelesen.`,"how.banks":`Die Kamera hält ihre Firmware in drei **Slots** ({a}, {b} und {r}). Schritt 02 liest alle drei und ermittelt, aus welchem Slot die Kamera beim nächsten Mal startet; der Patch wirkt nur, wenn dieser Slot ihn enthält. Sie wählen die Slots, die Schritt 03 patcht — standardmäßig den, aus dem der nächste Start erfolgt —, und Schritt 04 stellt jeden davon wieder her.`,"how.runFile":"Nach jedem Schritt lädt Ihr Browser eine **Durchlaufdatei** herunter, benannt nach dem Beginn des Durchlaufs, der Speicherzeit und dem erreichten Schritt (`{example}`), mit einem Ordner pro Schritt darin. Behalten Sie die neueste — damit können Sie später weitermachen.","how.writeWarning":`**Die Schritte 03 und 04 schreiben in den Flash-Speicher der Kamera**, und jeder bittet Sie vorher um Bestätigung. Während einer von ihnen läuft, lassen Sie die Kamera angeschlossen (außer die Seite bittet Sie, sie neu einzustecken) und den Computer wach, am besten am Netzstrom. Ein unterbrochener Schreibvorgang hinterlässt eine Kamera, die nur noch ein Hardware-Programmiergerät (SPI oder SWD/J-Link) retten kann.`,"how.phone":`**Auf einem Telefon:** Schalten Sie vor Schritt 03 den Flugmodus ein sowie WLAN und mobile Daten aus, damit kein Anruf und keine Benachrichtigung den Browser mitten im Schreiben verdrängt — und lassen Sie den Bildschirm an. Die Seite funktioniert offline weiter, sobald sie geöffnet ist.`,"how.pastCommit":`**Der Schreibvorgang ist für diesen Durchlauf nicht verzeichnet, daher sind die Schritte danach gesperrt.** Die Kamera führt möglicherweise schon das gepatchte Image aus (ein unterbrochener Schreibvorgang) oder auch nicht (der Schreibvorgang hat nie begonnen) — die Durchlaufdatei kann nicht belegen, was zutrifft. Führen Sie das volle Auslesen oder die Wiederherstellung nicht an einer gepatchten Kamera aus, solange der Schreibvorgang nicht verzeichnet ist. Der Weg nach vorn ist Schritt 03: Seine Prüfung vor dem Schreiben liest den Slot und weigert sich, ihn noch einmal blind zu beschreiben. Nur wenn diese Prüfung bereits mit *already holds the patched bytes* abgelehnt hat, gilt der Sprung — und er läuft über einen eigenen Dialog.`,"phase.readBuild.label":`Lesen & vorbereiten`,"phase.readBuild.inSentence":`Lesen & vorbereiten`,"phase.readBuild.description":`Liest alles, was eine Kamera im Originalzustand herausgibt — 31 Blöcke zu 64 KB — und bewahrt es als Ihre Sicherung auf, liest jeden Firmware-Slot ein zweites Mal, ermittelt, aus welchem Slot die Kamera beim nächsten Mal startet, und bereitet den kleinen Patch vor, den der nächste Schritt schreibt. Es wird nichts in die Kamera geschrieben. Dauert meist weniger als eine Minute. Wenn die Kamera zwischendurch neu starten muss, bittet die Seite Sie, auf „Gerät verbinden“ zu klicken und sie erneut auszuwählen — das ist so vorgesehen.`,"phase.patchDump.label":`Schreiben & volles Auslesen`,"phase.patchDump.inSentence":`Schreiben & volles Auslesen`,"phase.patchDump.description":`Schreibt einen kleinen, vorübergehenden Patch in die in Schritt 02 gewählten Firmware-Slots (standardmäßig in den Slot, aus dem die Kamera beim nächsten Mal startet), damit die Kamera ihren gesamten Flash-Speicher herausgibt. Dann startet die Kamera neu — klicken Sie auf „Gerät verbinden“ und wählen Sie sie erneut aus, wenn die Seite darum bittet —, und der gesamte 4-MB-Flash-Speicher wird gelesen. Schritt 04 bringt die Original-Firmware zurück.`,"phase.restoreVerify.label":`Wiederherstellen & prüfen`,"phase.restoreVerify.inSentence":`Wiederherstellen & prüfen`,"phase.restoreVerify.description":`Schreibt Ihre Original-Firmware zurück, startet die Kamera neu (klicken Sie auf „Gerät verbinden“ und wählen Sie sie erneut aus, wenn Sie darum gebeten werden) und liest dann alles noch einmal, um zu prüfen, dass es Byte für Byte mit der Sicherung übereinstimmt.`,"step.backup.description":`Liest die 31 Blöcke zu 64 KB, die eine Kamera im Originalzustand lesen lässt, liest dann jeden Slot ein zweites Mal (beide Lesevorgänge müssen Byte für Byte übereinstimmen), gewinnt die Firmware jedes Slots aus dem, was die Kamera speichert (entschlüsselt, wo sie verschlüsselt gespeichert ist), prüft sie und ermittelt, aus welchem Slot die Kamera als Nächstes startet. Das ist die einzige Kopie dieser Kamera im Durchlauf, erstellt, bevor irgendetwas geschrieben wird.`,"step.patch.description":`Offline, ohne Kamera. Baut den Patch für jeden Slot, den der Durchlauf beschreiben kann: Er lässt den Lesebefehl der Kamera den gesamten 4-MB-Flash-Speicher erreichen und wird in der Form geschrieben, in der die Kamera ihn speichert, sodass sich nur die eigenen Bytes des Patches ändern.`,"step.commit.description":`Der Schreibvorgang. Liest zuerst jeden gewählten Slot zurück und schreibt nichts, wenn nicht jeder noch genau das enthält, was die Sicherung festgehalten hat (ein Schreibvorgang, der schon angekommen ist, wird nie wiederholt). Dann schreibt er jeden Slot, den Slot, den die Kamera zuerst versucht, als letzten. Die Kamera wird hier nicht neu gestartet: Das tut der nächste Schritt.`,"step.drain.description":`Startet die Kamera neu, damit sie die gepatchte Firmware startet (sie ist etwa zehn Sekunden still; die Seite wartet und findet sie wieder), prüft, aus welchem Slot sie gestartet ist (ein Slot ohne den Patch hält den Schritt an, bevor irgendetwas gelesen wird), liest dann den gesamten 4-MB-Flash-Speicher in einem Durchgang und setzt die Original-Firmware jedes beschriebenen Slots, aus der Sicherung, in das gespeicherte Abbild ein. Es wird nichts geschrieben.`,"step.restore.description":`Der andere Schreibvorgang. Schreibt die Original-Firmware jedes beschriebenen Slots zurück, solange die gepatchte Firmware noch läuft, und startet die Kamera dann neu.`,"step.verify.description":`Liest nach einem frischen Start die 31 Blöcke erneut, darunter jeden Slot: 0 abweichende Bytes belegen, dass der Flash-Speicher der Kamera byteidentisch mit der Sicherung ist. Nur Lesen.`,"phase.start":`{phase} starten`,"phase.retry":`{phase} erneut versuchen`,"phase.goRestore":`Weiter zu Schritt 04: Slots wiederherstellen`,"phase.jumpOnly":`Nicht verzeichnetes Schreiben überspringen`,"phase.skipWrite":`Schreiben überspringen — mit dem vollen Auslesen beginnen`,"phase.toolbar":`Aktionen: {phase}`,"badge.writes":`schreibt in die Kamera`,"badge.running":`Läuft`,"badge.done":`Fertig`,"badge.plannedStop":`Wie geplant angehalten — Wiederherstellung folgt`,"badge.failed":`Angehalten — siehe Protokoll`,"badge.upNext":`Als Nächstes`,"notReady.noRun":`Verfügbar nach Schritt 02 — er startet den Durchlauf.`,"notReady.previous":`Verfügbar nach Schritt {step} ({phase}).`,"notReady.gate":`Noch nicht bereit — {reason}.`,"phase.pastCommit":`Betrifft die gepatchte Kamera, solange der Schreibvorgang nicht verzeichnet ist — die Kamera ist möglicherweise bereits gepatcht. Siehe den Hinweis unter „{section}“.`,"phase.noDrain":`Das volle Auslesen ist nicht gelaufen — dieser Schritt stellt die Kamera ohne es wieder her. Führen Sie zuerst Schritt 03 aus, es sei denn, das volle Auslesen ist Ihnen nicht wichtig.`,"phase.keepPlugged":`Lassen Sie die Kamera angeschlossen und den Computer wach, bis dieser Schritt fertig ist.`,"phase.stepsLabel":`Fortschritt`,"phase.showDetails":`Details im Protokoll anzeigen`,"phase.inDetail":`Was dieser Schritt im Einzelnen tut`,"yourTurn.toolbar":`Sie sind dran`,"yourTurn.reconnect.title":`Sie sind dran: Klicken Sie auf „Gerät verbinden“ und wählen Sie die Kamera aus.`,"yourTurn.reconnect.body":`Die Kamera wurde wie geplant neu gestartet. Chrome kann sie nicht von selbst wiedererkennen (sie hat keine USB-Seriennummer), daher müssen Sie sie noch einmal auswählen. Der Schritt läuft weiter, sobald Sie das tun.`,"yourTurn.replug.title":`Sie sind dran: Ziehen Sie die Kamera ab, stecken Sie sie wieder ein und klicken Sie dann auf „Gerät verbinden“.`,"yourTurn.replug.body":`Der Patch dieses Durchlaufs wurde vor der Lese-Korrektur erstellt, daher muss die Kamera vor der Wiederherstellung frisch eingeschaltet werden. Die Durchlaufdatei ist bereits gespeichert.`,"yourTurn.replugBeforeRestore.title":`Vor Schritt 04: Ziehen Sie die Kamera ab, stecken Sie sie wieder ein und klicken Sie dann auf „Gerät verbinden“.`,"yourTurn.powerCycle.title":`Sie sind dran: Ziehen Sie die Kamera ab, stecken Sie sie wieder ein, klicken Sie auf „Gerät verbinden“ — und versuchen Sie es dann erneut.`,"yourTurn.powerCycle.body":`Die Kamera muss frisch eingeschaltet werden, bevor sie wieder gelesen werden kann. Der Durchlauf ist hier noch geladen; nichts geht verloren.`,"yourTurn.powerCycleAssert.title":`Sie sind dran: Ziehen Sie die Kamera ab, stecken Sie sie wieder ein, klicken Sie auf „Gerät verbinden“ — und fahren Sie dann fort.`,"yourTurn.powerCycleAssert.body":`Der letzte Sicherungsversuch wurde angehalten, und die Kamera muss frisch eingeschaltet werden, bevor er erneut läuft. Die Kamera kann das nicht selbst melden, daher teilen Sie der Seite mit der Schaltfläche unten mit, dass Sie es getan haben.`,"yourTurn.replugged":`Neu eingesteckt — weiter mit {phase}`,"banks.title":`Welche Slots Schritt 03 patcht`,"banks.bootWord":`Boot-Konfigurationswort`,"banks.lastStart":`Letzter Start`,"banks.nextStart":`Nächster Start`,"banks.caption":`Die drei Firmware-Slots, wie Schritt 02 sie gelesen hat`,"banks.col.bank":`Slot`,"banks.col.address":`Adresse`,"banks.col.holds":`Inhalt`,"banks.nextStartBadge":`nächster Start`,"banks.choiceLabel":`Zu patchende Slots`,"choice.nextStart":`Der Slot des nächsten Starts`,"choice.all":`Alle Slots`,"choice.withBanks":`{choice} — {banks}`,"choice.notOffered":`{choice} — nicht angeboten`,"banks.notChosen":`Noch kein Slot gewählt: {what}. Wählen Sie oben einen Slot mit Namen.`,"banks.writes":`Schritt 03 schreibt: {what}.`,"banks.fixed":`Der Schreibvorgang ist gelaufen, daher steht die Auswahl fest: Schritt 04 stellt genau diese Slots wieder her.`,"banks.notOfferedLine":`{choice}: nicht angeboten — {why}.`,"banks.refusedNoRun":`kein Durchlauf aktiv — Schritt 02 startet einen`,"banks.refusedBusy":`ein Schritt läuft — wählen Sie die Slots, wenn er fertig ist`,"plan.summary":`Der Plan — {build}, patcht {banks}`,"plan.summaryNone":`Der Plan — {build}, noch kein Slot gewählt`,"plan.yourCamera":`Ihre Kamera`,"plan.intro":`Aus den eigenen Bytes der Kamera erstellt. Nichts wird geschrieben, bevor Schritt 03 läuft, und Schritt 04 stellt jedes Byte wieder her, das er schreibt.`,"plan.build":`Build`,"plan.version":`Firmware-Version`,"plan.written":`Geschrieben`,"plan.route":`Wohin er geht`,"plan.restore":`Wiederherstellung`,"plan.wholeFlash":`Volles Auslesen`,"plan.outro":`In der Form, die die Kamera speichert, ändern sich dieselben Bytes und keine anderen. Die Firmware der Kamera ändert sich also genau um diesen Unterschied und um nichts sonst.`,"bankPlan.label":`Der Patch von {bank}`,"bankPlan.titleChosen":`{bank} — von diesem Durchlauf beschrieben`,"bankPlan.titleNotChosen":`{bank} — nicht gewählt`,"bankPlan.source":`Quelle des Images`,"bankPlan.sourceValue":`{bank}, wie gespeichert`,"bankPlan.sourceTwoReads":`{bank}, wie gespeichert, zwei übereinstimmende Lesevorgänge (sha256 {sha})`,"bankPlan.edit":`Änderung am Image`,"bankPlan.editValue":`{label} ({id}) auf dem Werks-Image. Sein Ausgleich, {balance}, steht im Ausgleichswort; der Patch gleicht darauf aufbauend aus, und Schritt 04 stellt das Image mitsamt der Änderung wieder her.`,"bankPlan.factorySha":`sha256 des Werks-Klartexts`,"bankPlan.patchedSha":`sha256 gepatcht`,"bankPlan.diffCount":`Bytes, die sich im Chip ändern`,"bankPlan.staged":`Übertragene Länge`,"bankPlan.stagedValue":{one:`{size} B in {count} Teil`,other:`{size} B in {count} Teilen`},"bankPlan.rebalance":`Ausgleichswort`,"bankPlan.rebalanceValue":`{word} (vorher {balance}, der Ausgleich der Änderung)`,"bankPlan.caption":`Die genauen Bytes, die der Patch in {bank} ändert`,"bankPlan.col.what":`Was er ändert`,"bankPlan.col.offset":`Offset`,"bankPlan.col.before":`Vorher`,"bankPlan.col.after":`Nachher`,"verify.ok":{one:`**Bestätigt — eine perfekte Übereinstimmung.** Nach einem frischen Start wurde die Kamera erneut gelesen: {read}/31 Blöcke, {count} abweichendes Byte. Ihr Flash-Speicher ist genau so, wie er vor dem ersten Schreibvorgang war.`,other:`**Bestätigt — eine perfekte Übereinstimmung.** Nach einem frischen Start wurde die Kamera erneut gelesen: {read}/31 Blöcke, {count} abweichende Bytes. Ihr Flash-Speicher ist genau so, wie er vor dem ersten Schreibvorgang war.`},"verify.okShort":{one:`**Bestätigt — eine perfekte Übereinstimmung.** Nach einem frischen Start wurde die Kamera erneut gelesen: {read}/31 Blöcke, {count} abweichendes Byte (kurze Blöcke: {blocks}). Ihr Flash-Speicher ist genau so, wie er vor dem ersten Schreibvorgang war.`,other:`**Bestätigt — eine perfekte Übereinstimmung.** Nach einem frischen Start wurde die Kamera erneut gelesen: {read}/31 Blöcke, {count} abweichende Bytes (kurze Blöcke: {blocks}). Ihr Flash-Speicher ist genau so, wie er vor dem ersten Schreibvorgang war.`},"verify.failed":`**Die Prüfung hat Abweichungen gegenüber der Sicherung gefunden.** {error}`,unknownReason:`unbekannter Grund`,"confirm.titleWrite":`{phase} — in {banks} schreiben?`,"confirm.titleJump":`{phase} — nicht verzeichnetes Schreiben überspringen?`,"confirm.chosenBanks":`die gewählten Slots`,"confirm.jump":`DER SCHREIBVORGANG IST FÜR DIESEN DURCHLAUF NICHT VERZEICHNET, und Sie versichern, dass die Schreibvorgänge ohne ihre Checkpoints angekommen sind: Der Schritt beginnt nach dem Schreiben, statt erneut zu schreiben. Die eigenen Prüfungen der Schritte laufen trotzdem — das Lesen der Version, die Prüfungen der Slots —, und eine falsche Annahme kostet ein vergebliches volles Auslesen, keine unbrauchbar gemachte Kamera.`,"confirm.jumpKeepPlugged":`Lassen Sie die Kamera angeschlossen und den Computer wach, bis der Schritt fertig ist.`,"confirm.patch":`Dies schreibt einen kleinen Patch in {banks}. Schritt 04 stellt die Originale wieder her. Das folgende volle Auslesen liest nur.`,"confirm.patchInOrder":`Dies schreibt einen kleinen Patch in {banks}, in dieser Reihenfolge — der Slot, den die Kamera zuerst versucht, kommt zuletzt. Schritt 04 stellt die Originale wieder her. Das folgende volle Auslesen liest nur.`,"confirm.restore":`Dies schreibt Ihre Original-Firmware zurück in {banks}.`,"confirm.restoreInOrder":`Dies schreibt Ihre Original-Firmware zurück in {banks}, in dieser Reihenfolge — der Slot, den die Kamera zuerst versucht, kommt zuerst.`,"confirm.keepPlugged":`Lassen Sie die Kamera angeschlossen und den Computer wach, solange geschrieben wird — ein unterbrochener Schreibvorgang hinterlässt eine Kamera, die nur noch ein Hardware-Programmiergerät (SPI oder SWD/J-Link) retten kann. Auf einem Telefon: Flugmodus an und den Bildschirm eingeschaltet lassen. Danach startet die Kamera neu; wenn die Seite darum bittet, klicken Sie auf „Gerät verbinden“ und wählen Sie sie erneut aus. Das ist so vorgesehen.`,"confirm.yesJump":`Ja — Schreiben überspringen`,"confirm.yesWrite":`Ja — in die Kamera schreiben`,"summary.proof":`Der Nachweis`,"summary.complete":`Vollständiges Abbild (4 MB)`,"summary.notProduced":`nicht erzeugt`,"summary.differs":{one:`weicht von der Sicherung in {differing} von {count} Block ab: {blocks}`,other:`weicht von der Sicherung in {differing} von {count} Blöcken ab: {blocks}`},"summary.matches":{one:`stimmt mit der Sicherung überein ({count} Block)`,other:`stimmt mit der Sicherung überein (alle {count} Blöcke)`},"summary.onlyInFull":`Nur im vollen Auslesen`,"summary.onlyInFullValue":{one:`{count} Block, den ein normales Lesen nicht erreicht: {blocks}`,other:`{count} Blöcke, die ein normales Lesen nicht erreicht: {blocks}`},"summary.rawDump":`Volles Auslesen, wie gelesen`,"summary.rawDumpBadge":`dasselbe, mit dem Patch noch darin`,"summary.image":`Firmware-Image (entschlüsselt, {bank})`,"summary.verify":`Prüfung`,"summary.toolbar":`Archiv-Aktionen`,"summary.download":`Gesamtarchiv herunterladen (Durchlaufdatei)`,"runFile.eyebrow":`Optional — um einen Durchlauf später fortzusetzen`,"runFile.title":`Durchlaufdatei`,"runFile.description":`Die einzige Aufzeichnung des Durchlaufs. Sie wird nach jedem Schritt von selbst heruntergeladen (auch nach einem vorzeitig angehaltenen Schritt); behalten Sie die neueste. Um später oder nach einem Problem weiterzumachen, laden Sie sie hier, und die Seite macht dort weiter, wo sie aufgehört hat.`,"runFile.run":`Durchlauf`,"runFile.file":`Datei`,"runFile.lastSaved":`Zuletzt gespeichert`,"runFile.lastSavedValue":`nach {step} — {at} ({bytes} B)`,"runFile.nextStep":`Nächster Schritt`,"runFile.none":`Kein Durchlauf aktiv. Schritt 02 startet einen, oder laden Sie hier eine Durchlaufdatei.`,"runFile.toolbar":`Aktionen zur Durchlaufdatei`,"runFile.load":`Durchlaufdatei laden…`,"runFile.save":`Durchlaufdatei erneut speichern`,"runFile.panel":`Fortsetzen`,"status.noFile":`Keine Durchlaufdatei gewählt.`,"status.notRun":`Noch nicht ausgeführt.`,"status.running":`Läuft …`,"status.runningRestarts":`Läuft — die Kamera startet in diesem Schritt neu …`,"status.restarting":`Die Kamera startet neu — das dauert etwa zehn Sekunden …`,"status.waitConnect":`Warte auf Sie — klicken Sie auf „Gerät verbinden“ und wählen Sie die Kamera aus …`,"status.waitPlugBack":`Warte auf Sie — stecken Sie die Kamera wieder ein und klicken Sie dann auf „Gerät verbinden“ …`,"status.waitReplug":`Warte auf Sie — ziehen Sie die Kamera ab und stecken Sie sie wieder ein …`,"status.back":`Die Kamera ist wieder da — es geht weiter …`,"status.swapped":`Angehalten — die Kamera hat gewechselt. Prüfen Sie sie und führen Sie den Schritt dann erneut aus.`,"status.noRun":`Kein Durchlauf.`,"status.notCreated":`Nicht erstellt — siehe Protokoll oben.`,"status.refused":`Abgelehnt — die Schrittliste oben sagt, was fehlt.`,"status.done":`{phase} — fertig. Die Durchlaufdatei in Ihren Downloads ist aktuell.`,"status.doneReplug":`{phase} — fertig, und die Durchlaufdatei ist gespeichert. Vor der Wiederherstellung: Ziehen Sie die Kamera ab, stecken Sie sie wieder ein und klicken Sie auf „Gerät verbinden“.`,"status.backupRefused":`Abgelehnt — es wurde nichts geschrieben. Siehe Protokoll oben.`,"status.failed":`Fehlgeschlagen — siehe Protokoll oben.`,"status.cancelled":`Abgebrochen — die Durchlaufdatei hält weiterhin fest, wo der Durchlauf angehalten hat.`,"status.readingFile":`Durchlaufdatei wird gelesen …`,"status.doneEarlier":`Bereits früher erledigt — aus der Durchlaufdatei geladen.`,"status.failedEarlier":`Früher fehlgeschlagen: {error}`,"status.resumed":`Bei {step} fortgesetzt. Die Schrittliste macht dort weiter.`,"status.notResumed":`Nicht fortgesetzt — siehe Protokoll oben.`,"gate.needs":`benötigt: {missing}`,"gate.noRun":`kein Durchlauf aktiv — der erste Schritt erstellt den Durchlauf`,"gate.runDone":`dieser Durchlauf ist abgeschlossen — jeder Schritt ist fertig`,"gate.alreadyDone":`bereits erledigt — Fortsetzen macht bei {step} weiter`,"gate.banksRead":`die Slots, die die Sicherung liest`,"gate.choice":`eine Auswahl der Slots — {why}`,"gate.bankRefused":`{bank} kann nicht beschrieben werden: {reason}`,"gate.recoveryRoute":`der Weg über den Recovery-Slot (dieser Build läuft nur aus {r}, nicht aus {bank})`,"gate.backupFirst":`die Flash-Sicherung (sie läuft in diesem Schritt zuerst)`,"gate.backup":`die Flash-Sicherung`,"gate.patchStep":`der Patch-Schritt`,"gate.patchOf":`der Patch von {bank}`,"gate.backupFile":`die Datei mit den Sicherungsfenstern`,"gate.capture":`die Aufnahme von {bank}`,"gate.derived":`das abgeleitete Image von {bank}`,"gate.writeStep":`der Schritt „Schreiben“ (führen Sie ihn zuerst aus oder setzen Sie bei ihm fort)`,"gate.drainRefused":`das volle Auslesen lehnt auf {build} ab — {why}`,"gate.patchSummary":`die Patch-Zusammenfassung von {bank} (die übertragene Länge)`,"gate.restoreRefused":`die Wiederherstellung lehnt auf {build} ab — keine Form der Original-Firmware wird wieder als die Original-Bytes gespeichert; der Durchlauf endet mit dem vollständigen Abbild und dem Patch an seinem Platz`,"gate.plaintext":`der Werks-Klartext von {bank} ({file}, aus dem Sicherungsschritt)`,"gate.restoreFirst":`die Wiederherstellung (sie läuft in diesem Schritt zuerst)`,"gate.powerCycle":`die Bestätigung des Aus- und Einschaltens — schalten Sie die Kamera aus und wieder ein (abziehen und wieder einstecken oder ihren Netzschalter verwenden) und verwenden Sie dann die Schaltfläche zum erneuten Ausführen`,"error.cameraNotBack":`die Kamera ist nach {minutes} Min. wiederholter Versuche nicht zurückgekommen: {error} — wenn Chrome nichts gefragt hat, stecken Sie die Kamera neu ein und führen Sie den Schritt erneut aus; wenn das Protokoll sagte, sie neu zu verbinden, war der Klick auf „Gerät verbinden“ das, worauf gewartet wurde`}};export{e as default};
